import * as THREE from 'three';
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import Engine from "../../../lib/core/Engine.js";
import butterflyVertexShader from "./shaders/vertex.glsl";
import butterflyFragmentShader from "./shaders/fragment.glsl";
import CurvedPathUtils from "../../../lib/utils/CurvedPathUtils.js";
import Random from "../../../lib/utils/Random.js";

export type TweakValues  = {
	color    : string,
	size     : number,
}

type ButterflyParams = {
	engine        : Engine,
	group         : THREE.Group,
	resources     : Resources<typeof sources>,
	geometry      : THREE.BufferGeometry,
	initialTweaks : TweakValues,
	/**
	 * The ground bounding box, used to now where to sample path points.
	 */
	boundingBox   : THREE.Box3,
}

export default class Butterfly {
	private static id = 0;

	private static getNewId() {
		return Butterfly.id++;
	}

	private readonly id          : number;
	private readonly group       : THREE.Group;
	private readonly engine      : Engine;
	private readonly resources   : Resources<typeof sources>;
	private readonly tweakValues : TweakValues;
	private readonly geometry!   : THREE.BufferGeometry;
	private readonly wrapper!    : THREE.Group;
	private readonly boundingBox : THREE.Box3;

	private material! : THREE.ShaderMaterial;
	private mesh!     : THREE.Mesh;
	private path!     : CurvedPathUtils;

	constructor(
		{
			group,
			engine,
			resources,
			geometry,
			initialTweaks,
			boundingBox,
		}: ButterflyParams,
	) {
		this.id          = Butterfly.getNewId();
		this.engine      = engine;
		this.group       = group;
		this.resources   = resources;
		this.tweakValues = initialTweaks;
		this.geometry    = geometry;
		this.boundingBox = boundingBox;
		this.wrapper     = new THREE.Group();

		this.init();
		this.configureTweaks();
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: `GrassField.Butterflies.Butterfly.${this.id + 1}`,
				color: {
					onChange: (value: string) => {
						if (!this.material) return;

						this.material.uniforms.uColor.value = new THREE.Color(value);
					}
				},
				size: {
					params : {
						min  : 1.5,
						max  : 4.5,
						step : 0.05
					},
					onChange: (value: number) => {
						if (!this.mesh) return;

						this.mesh.scale.set(value, value, value);
					}
				},
			}
		);
	}

	private init() {
		this.resources.on('loaded:butterflyTexture', () => {
			this.createMaterial();
			this.createMesh();
			this.generateRandomPath();
		});
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			transparent: true,
			side: THREE.DoubleSide,

			vertexShader: butterflyVertexShader,
			fragmentShader: butterflyFragmentShader,
			fog: true,
			depthWrite: false,

			uniforms: {
				uTime    : new THREE.Uniform(0),
				uSize    : new THREE.Uniform(0.04),
				uTexture : new THREE.Uniform(this.resources.items.butterflyTexture),
				uColor   : new THREE.Uniform(new THREE.Color(this.tweakValues.color)),
				...THREE.UniformsLib.fog,
			}
		})
	}

	private createMesh() {
		this.mesh = new THREE.Mesh(
			this.geometry,
			this.material,
		);

		this.mesh.rotation.x = -Math.PI * 0.5;
		this.mesh.rotation.z = Math.PI;
		this.mesh.scale.set(
			this.tweakValues.size,
			this.tweakValues.size,
			this.tweakValues.size,
		);

		this.wrapper.add(this.mesh);
		this.engine.scene.add(this.wrapper);
	}

	private createRandomCurvePoint() {
		return Random.pointInBox(this.boundingBox);
	}

	private generateRandomPath() {
		const points = Array(5).fill(0).map(
			this.createRandomCurvePoint.bind(this),
		);

		this.path = new CurvedPathUtils({ points });
	}

	update() {
		if (!this.material) return;

		this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds + (this.id * 10);

		this.updatePositionOnPath();
	}

	private updatePositionOnPath() {
		const { position, tangent } = this.path.getPositionAndTangent(this.engine.time.deltaSeconds);

		this.wrapper.position.copy(position);
		this.wrapper.lookAt(position.clone().add(tangent));
 }

	destroy() {
		this.group.remove(this.mesh);
		this.material?.dispose();
	}
}