import * as THREE from 'three';
import Sizes from "./Sizes.js";
import Camera from "./Camera.js";
import {isOffscreenCanvas} from "../compatibility/offscreenCanvas.js";

export default class Renderer {
	private readonly sizes: Sizes;
	private readonly camera: Camera;
	private readonly scene: THREE.Scene;
	private readonly canvas: HTMLCanvasElement | OffscreenCanvas;

	#instance!: THREE.WebGLRenderer;
	#autoRenderOnResize: boolean;

	constructor(
		{
			sizes,
			scene,
			camera,
			canvas,
		}: {
			sizes: Sizes,
			scene: THREE.Scene,
			camera: Camera,
			canvas: HTMLCanvasElement | OffscreenCanvas,
		},
	) {
		this.sizes = sizes;
		this.scene = scene;
		this.canvas = canvas;
		this.camera = camera;
		this.#autoRenderOnResize = this.isExecutedInWorker();

		this.initInstance();
	}

	get instance() {
		return this.#instance;
	}

	get autoRenderOnResize() {
		return this.#autoRenderOnResize;
	}

	disableAutoRenderOnResize() {
		this.#autoRenderOnResize = false;
	}

	enableAutoRenderOnResize() {
		this.#autoRenderOnResize = true;
	}

	isExecutedInWorker(): boolean {
		return isOffscreenCanvas(this.canvas);
	}

	private initInstance(): void {
		this.#instance = new THREE.WebGLRenderer({
			canvas    : this.canvas,
			antialias : true,
		});

		this.updateSize();

		this.#instance.toneMapping = THREE.NoToneMapping;
		this.#instance.outputColorSpace = THREE.SRGBColorSpace;
	}

	private runInWorker() {
		return this.canvas instanceof OffscreenCanvas;
	}

	private runInMainThread() {
		return !this.runInWorker();
	}

	private updateSize(): void {
		if (!this.#instance) {
			return;
		}

		this.#instance.setSize(
			this.sizes.width,
			this.sizes.height,
			this.runInMainThread(),
		);

		this.#instance.setPixelRatio(
			this.sizes.pixelRatio,
		);

		if (this.#autoRenderOnResize) {
			this.update();
		}
	}

	resize(): void {
		this.updateSize();
	}

	update(): void {
		this.#instance.render(
			this.scene,
			this.camera.instance,
		);
	}

	destroy() {
		this.#instance.dispose();
	}
}