import * as THREE from "three";
import Engine from "../../lib/core/Engine.js"
import sources from "../../config/resources.config.js";
import Resources from "../../lib/core/Resources.js";
import Flowers from "./flowers/Flowers.js";
import Pampa from "./grass/Pampa.js";
import {Ground} from "./ground/Ground.js";
import Grass from "./grass/Grass.js";
import Butterflies from "./butterflies/Butterflies.js";
import Bender from "./bender/Bender.js";
import WindLines from "./wind/lines/WindLines.js";
import {debugBoundingBox} from "../../lib/dev/debug/TheoreticalObjectDisplay.js";
import config from "../../config/Conf.js";

type ColorsTweakValues = {
	lightColor : string,
	darkColor  : string,
}

type InitialTweaks = {
	scale : number,
}

type TweakValues = InitialTweaks & {
	dirt: ColorsTweakValues,
	grass: ColorsTweakValues,
	misc: {
		lightDirection : THREE.Vector3,
		shadowColor    : string,
	},
}

type GrassFieldProps = {
	group         : THREE.Group,
	islands       : THREE.Group,
	engine        : Engine,
	geometry      : THREE.BufferGeometry,
	resources     : Resources<typeof sources>,
	initialTweaks : InitialTweaks,
}

export default class GrassField {
	private readonly group        : THREE.Group;
	private readonly parentGroup  : THREE.Group;
	private readonly islands      : THREE.Group;
	private readonly engine       : Engine;
	private readonly resources    : Resources<typeof sources>;
	private readonly tweakValues  : TweakValues;

	private geometry!    : THREE.BufferGeometry;
	private flowers1!    : Flowers;
	private flowers2!    : Flowers;
	private pampaGrass!  : Pampa;
	private grass!       : Grass;
	private ground!      : Ground;
	private butterflies! : Butterflies[];
	private bender!      : Bender;
	private windLines!   : WindLines;

	constructor(
		{
			group,
			engine,
			resources,
			geometry,
			islands,
			initialTweaks
		}: GrassFieldProps
	) {
		this.engine       = engine;
		this.resources    = resources;
		this.parentGroup  = group;
		this.islands      = islands;
		this.group        = new THREE.Group();
		this.butterflies  = [];
		this.tweakValues  = {
			...initialTweaks,
			grass: {
				lightColor: config.grassField.grass.lightColor,
				darkColor : config.grassField.grass.darkColor,
			},
			dirt: config.grassField.grass.dirt,
			misc: config.grassField.grass.misc
		};
		this.geometry = geometry;

		this.init();
		this.configureTweaks();
		this.engine.on(
			'global:config:changed',
			(event) => this.configChanged(event?.detail?.config)
		);
	}

	private configChanged(conf: typeof config) {
		if (conf.grassField.grass) {
			const grassConfig = conf.grassField.grass;
			this.updateGrassLightColor(grassConfig.lightColor);
			this.updateGrassDarkColor(grassConfig.darkColor);
		}
	}

	private configureTweaks() {
		this.configureGrassTweaks();
		this.configureDirtTweaks();
		this.configureMiscTweaks();
	}

	private configureGrassTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues.grass,
			{
				folder: 'GrassField.Grass',
				lightColor : {
					onChange : this.updateGrassLightColor.bind(this),
				},
				darkColor  : {
					onChange : this.updateGrassDarkColor.bind(this),
				}
			}
		);
	}

	private configureDirtTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues.dirt,
			{
				folder     : 'GrassField.Dirt',
				lightColor : {
					onChange : this.updateDirtLightColor.bind(this),
				},
				darkColor  : {
					onChange : this.updateDirtDarkColor.bind(this),
				},
			}
		);
	}

	private configureMiscTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues.misc,
			{
				folder     : 'GrassField.Misc',
				lightDirection : {
					onChange : this.updateLightDirection.bind(this),
				},
				shadowColor: {
					onChange : this.updateShadowColor.bind(this),
				}
			}
		);
	}

	private updateLightDirection(value: THREE.Vector3) {
		this.ground.updateLightDirection(value);
		this.grass.updateLightDirection(value);
	}

	private updateShadowColor(value: string) {
		this.ground.updateShadowColor(value);
		this.grass.updateShadowColor(value);
	}

	private updateDirtLightColor(value: string) {
		this.pampaGrass.updateDirtLightColor(value);
		this.ground.updateDirtLightColor(value);
		this.grass.updateDirtLightColor(value);
	}

	private updateDirtDarkColor(value: string) {
		this.pampaGrass.updateDirtDarkColor(value);
		this.ground.updateDirtDarkColor(value);
		this.grass.updateDirtDarkColor(value);
	}

	private updateGrassLightColor(value: string) {
		this.ground.updateGrassLightColor(value);
		this.grass.updateGrassLightColor(value);
	}

	private updateGrassDarkColor(value: string) {
		this.ground.updateGrassDarkColor(value);
		this.grass.updateGrassDarkColor(value);
	}

	private init() {
		this.geometry.computeTangents();
		this.geometry.computeBoundingBox();

		const {
			factor: bendingFactor,
			color: bendingColor,
			colorIntensity: bendingColorIntensity,
			brushRadius,
			fadingFactor,
		} = config.grassField.bending;

		this.ground = new Ground({
			engine         : this.engine,
			group          : this.group,
			resources      : this.resources,
			parentGeometry : this.geometry,
			dirt           : this.tweakValues.dirt,
			grass          : this.tweakValues.grass,
			lightDirection : this.tweakValues.misc.lightDirection,
			shadowColor    : this.tweakValues.misc.shadowColor,
			initialTweaks  : {
				scale: this.tweakValues.scale,
				bendingFactor,
				bendingColorIntensity
			},
		});

		this.bender = new Bender({
			ground: this.ground,
			engine: this.engine,
			initialTweaks : {
				brushRadius,
				fadingFactor,
			},
		});

		this.ground.configureBender(this.bender);

		const butterflyZones = Butterflies.extractZones(this.islands);

		this.butterflies.push(
			new Butterflies({
				engine      : this.engine,
				resources   : this.resources,
				group       : this.group,
				boundingBox : butterflyZones.main,
				butterflies : [
					{
						color : '#ffad15',
						size  : 1.4,
					},
					{
						color : '#ffad15',
						size  : 1.15,
					},
					{
						color : '#ff0000',
						size  : 1.3,
					},
					{
						color : '#ff0000',
						size  : 1.4,
					},
					{
						color : '#ba17ff',
						size  : 1,
					},
					{
						color : '#ba17ff',
						size  : 1,
					},
					{
						color : '#13ff15',
						size  : 1.4,
					},
					{
						color : '#13ff15',
						size  : 1.3,
					},
					{
						color : '#00c3c3',
						size  : 1.15,
					},
					{
						color : '#00c3c3',
						size  : 1.4,
					},
				],
			}),
			new Butterflies({
				engine      : this.engine,
				resources   : this.resources,
				group       : this.group,
				boundingBox : butterflyZones.top,
				butterflies : [
					{
						color : '#ffad15',
						size  : 1.4,
					},
					{
						color : '#ff0000',
						size  : 1.3,
					},
					{
						color : '#ba17ff',
						size  : 1,
					},
					{
						color : '#13ff15',
						size  : 1.4,
					},
					{
						color : '#00c3c3',
						size  : 1.15,
					},
				],
			}),
		);

		const {
			count: flowersCount,
			size: flowersSize,
		} = config.grassField.flowers;

		this.flowers1 = new Flowers({
			engine          : this.engine,
			bender          : this.bender,
			geometry        : this.geometry,
			group           : this.group,
			resources       : this.resources,
			rgbChannelToUse : 'r',
			initialTweaks   : {
				count  : flowersCount,
				size   : flowersSize,
				bendingFactor,
				...config.grassField.flowers.configs[0],
			}
		});

		this.flowers2 = new Flowers({
			engine          : this.engine,
			group           : this.group,
			bender          : this.bender,
			geometry        : this.geometry,
			resources       : this.resources,
			rgbChannelToUse : 'g',
			initialTweaks   : {
				count  : flowersCount,
				size   : flowersSize,
				bendingFactor,
				...config.grassField.flowers.configs[1],
			}
		});

		this.pampaGrass = new Pampa({
			engine         : this.engine,
			group          : this.group,
			bender         : this.bender,
			parentGeometry : this.geometry,
			resources      : this.resources,
			dirt           : this.tweakValues.dirt,
			initialTweaks  : {
				bendingFactor,
				bendingColor,
				bendingColorIntensity,
				...config.grassField.pampa,
			},
		});

		this.grass = new Grass({
			engine         : this.engine,
			group          : this.group,
			parentGeometry : this.geometry,
			resources      : this.resources,
			dirt           : this.tweakValues.dirt,
			grass          : this.tweakValues.grass,
			bender         : this.bender,
			shadowColor    : this.tweakValues.misc.shadowColor,
			lightDirection : this.tweakValues.misc.lightDirection,
			initialTweaks  : {
				bendingFactor,
				bendingColorIntensity,
				count: config.grassField.grass.count,
				height: config.grassField.grass.height,
				width: config.grassField.grass.width,
			},
		});

		this.windLines = new WindLines({
			engine      : this.engine,
			group       : this.group,
			boundingBox : butterflyZones.main,
		});

		this.parentGroup.add(this.group);

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;
			if (!declineLevel) return;

			switch (declineLevel) {
				case 5:
					console.warn('WindLines: Low FPS detected. Deleting windlines.');
					this.windLines.destroy();
					break;
			}
		});
	}

	update() {
		this.butterflies.forEach(butterflies => butterflies.update());
		this.flowers1?.update();
		this.flowers2?.update();
		this.pampaGrass?.update();
		this.grass?.update();
		this.ground?.update();
		this.bender?.update();
		this.windLines?.update();
	}

	destroy() {
		this.parentGroup.remove(this.group);

		this.butterflies.forEach(butterflies => butterflies.destroy());
		this.flowers1?.destroy();
		this.flowers2?.destroy();
		this.pampaGrass?.destroy();
		this.grass?.destroy();
		this.ground?.destroy();
		this.windLines?.destroy();

		this.bender?.destroy();

		this.geometry.dispose();
	}
}