import RingBuffer from "./RingBuffer.js";

type Curve = {
	name: string;
	color: string;
	buffer: RingBuffer;
};

export default class Graph {
	private readonly  canvas     : HTMLCanvasElement;
	private readonly bufferSize  : number;

	private ctx        : CanvasRenderingContext2D;
	private curves     : Curve[] = [];
	private padding    : number  = 1.1;

	constructor(
		container : HTMLElement = document.body,
		bufferSize: number      = 150
	) {
		this.bufferSize = bufferSize;

		this.canvas = document.createElement("canvas");

		this.canvas.style.width     = "100%";
		this.canvas.style.height    = "100%";
		this.canvas.style.minHeight = "75px";
		this.canvas.style.display   = "block";
		this.canvas.style.gridArea  = "graphs";

		this.canvas.width  = this.canvas.clientWidth;
		this.canvas.height = this.canvas.clientHeight;

		container.appendChild(this.canvas);

		const ctx = this.canvas.getContext("2d");
		if (!ctx) {
			throw new Error("Canvas 2D context not supported");
		}

		this.ctx = ctx;

		window.addEventListener("resize", () => this.resize());
		this.resize();

		this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
	}

	private resize() {
		this.canvas.width  = this.canvas.clientWidth;
		this.canvas.height = this.canvas.clientHeight;
	}

	addCurve(name: string, color: string, max: number = 0) {
		this.curves.push({
			name,
			color,
			buffer: new RingBuffer(
				this.bufferSize ?? this.canvas.width,
				max,
			),
		});
	}

	push(name: string, value: number) {
		const curve = this.curves.find(c => c.name === name);

		if (!curve) {
			return;
		}

		curve.buffer.push(value);
	}

	render() {
		this.resize();
		const { ctx, canvas }  = this;
		const width  : number  = canvas.width;
		const height : number  = canvas.height;

		ctx.clearRect(0, 0, width, height);

		for (const { color, buffer } of this.curves) {
			const values : number[] = buffer.values;
			const stepX  : number   = width / buffer.length;

			ctx.beginPath();
			ctx.strokeStyle = color;
			ctx.lineWidth   = 1;

			values.forEach((v, i) => {
				const x = i * stepX;
				const y = height - (v / (buffer.max * this.padding)) * height;

				if (i === 0) {
					ctx.moveTo(x, y);
				} else {
					ctx.lineTo(x, y);
				}
			});

			ctx.stroke();
		}
	}

	destroy() {
		// @ts-ignore
		this.ctx = undefined;
		this.canvas.remove();
		this.curves = [];
	}
}