import * as THREE from 'three';
import ChunkedInstancedMesh, {ChunkedInstancedMeshParams} from "../../../lib/utils/chunked/ChunkedInstancedMesh.js";
import {MeshSurfaceSampler} from "three/examples/jsm/math/MeshSurfaceSampler.js";

type ChunkedGrassParams = ChunkedInstancedMeshParams & {
	sampledGeometry: THREE.BufferGeometry,
};

export default class GrassChunks extends ChunkedInstancedMesh {
	private readonly sampledGeometry : THREE.BufferGeometry;

	private sampledMesh! : THREE.Mesh<THREE.BufferGeometry, THREE.MeshBasicMaterial>;

	constructor(params: ChunkedGrassParams) {
		super(params);

		this.sampledGeometry = params.sampledGeometry;
		this.init();
	}

	private init() {
		this.sampledMesh = new THREE.Mesh(
			this.sampledGeometry,
			new THREE.MeshBasicMaterial(),
		);
	}

	sampleAttributes(): Record<string, Float32Array> {
		const randomScale = Math.random() * 0.5 + 1;
		this.dummy.scale.set(randomScale, randomScale, randomScale);

		this.dummy.updateMatrix();

		const normalMatrix = new THREE.Matrix3();
		normalMatrix.getNormalMatrix(this.dummy.matrix);

		return {
			aRandomYRotation: new Float32Array([
				Math.random() * Math.PI * 2,
			]),
			aNormal: new Float32Array([
				-this.normal.x,
				this.normal.y,
				-this.normal.z,
			]),
			aUv: new Float32Array(
				this.uv.toArray(),
			),
			aNormalMatrix: new Float32Array(
				normalMatrix.elements,
			),
		};
	}

	getSampler() {
		return new MeshSurfaceSampler(this.sampledMesh).build();
	}

	postSample() {
		this.sampledMesh.material.dispose();
	}
}