import EventBusCapabilities, {SubscribeOptions} from "./EventBusCapabilities.js";

export default class DomEventBus<Namespaces extends string> implements EventBusCapabilities<Namespaces> {
	private eventTargets: Map<Namespaces, EventTarget> = new Map();
	private listenerMap: Map<string, EventListener> = new Map();

	constructor() {
		// Pre-register common DOM targets
		this.registerTarget('window' as Namespaces, window);
		this.registerTarget('document' as Namespaces, document);
	}

	/**
	 * Register a namespace with its corresponding event target
	 */
	registerTarget(namespace: Namespaces, target: EventTarget): void {
		this.eventTargets.set(namespace, target);
	}

	/**
	 * Dispatch an event to a namespace
	 */
	dispatch(namespace: Namespaces, event: string, data?: any): void {
		const target = this.eventTargets.get(namespace);

		if (!target) {
			console.warn(`EventBus: No target registered for namespace "${namespace}"`);
			return;
		}

		// Create a custom event with the data
		const customEvent = new CustomEvent(event, {
			detail: data,
			bubbles: true,
			cancelable: true
		});

		target.dispatchEvent(customEvent);
	}

	/**
	 * Subscribe to an event on a namespace
	 */
	subscribe(
		namespace: Namespaces,
		event: string,
		listener: Function,
		{ options }: SubscribeOptions = {},
	): void {
		const target = this.eventTargets.get(namespace);

		if (!target) {
			console.warn(`EventBus: No target registered for namespace "${namespace}"`);
			return;
		}

		// Create a wrapper to handle the event and call the listener
		const eventListener: EventListener = (e: Event) => {
			if (e instanceof CustomEvent) {
				listener(e.detail, e);
			} else {
				listener(e);
			}
		};

		// Store the mapping between original listener and DOM event listener
		const key = this.getListenerKey(namespace, event, listener);
		this.listenerMap.set(key, eventListener);

		// Add the event listener to the target
		target.addEventListener(event, eventListener, options);
	}

	/**
	 * Unsubscribe from an event on a namespace
	 */
	unsubscribe(namespace: Namespaces, event: string, listener: Function): void {
		const target = this.eventTargets.get(namespace);

		if (!target) {
			console.warn(`EventBus: No target registered for namespace "${namespace}"`);
			return;
		}

		// Find the stored event listener
		const key = this.getListenerKey(namespace, event, listener);
		const eventListener = this.listenerMap.get(key);

		if (eventListener) {
			target.removeEventListener(event, eventListener);
			this.listenerMap.delete(key);
		}
	}

	/**
	 * Generate a unique key for listener mapping
	 */
	private getListenerKey(namespace: Namespaces, event: string, listener: Function): string {
		return `${namespace}:${event}:${listener.toString()}`;
	}

	/**
	 * Clean up all event listeners (useful for disposal)
	 */
	dispose(): void {
		this.listenerMap.forEach((eventListener, key) => {
			const [namespace, event] = key.split(':');
			const target = this.eventTargets.get(namespace as Namespaces);
			if (target) {
				target.removeEventListener(event, eventListener);
			}
		});

		this.listenerMap.clear();
		this.eventTargets.clear();
	}
}