import * as THREE from 'three';
import { mergeVertices } from 'three/addons/utils/BufferGeometryUtils.js';
import Engine from "../../../../lib/core/Engine.js";
import vertexShader from './shaders/vertex.glsl';
import fragmentShader from './shaders/fragment.glsl';
import config from "../../../../config/Conf.js";

type TweakValues = {
	lightPosition   : { x: number, y: number, z: number },
	foamColor       : string,
	foamShadowColor : string,
}

type FoamParams = {
	engine : Engine,
	group  : THREE.Group,
	initialTweaks: TweakValues,
};

export default class Foam {
	private readonly engine : Engine;
	private readonly group  : THREE.Group;
	private readonly tweakValues : TweakValues;

	private material! : THREE.ShaderMaterial | THREE.MeshToonMaterial;
	private mesh!     : THREE.Mesh;

	constructor(
		{
			engine,
			group,
			initialTweaks,
		}: FoamParams
	) {
		this.engine = engine;
		this.group  = group;
		this.tweakValues = initialTweaks;

		this.init();
		this.configureTweaks();

		this.engine.on(
			'global:config:changed',
			(event) => {
				const conf = event?.detail?.config;
				if (!conf) return;

				this.configChanged(conf);
			}
		)
	}

	private configChanged(conf: typeof config) {
		if (conf.islands.foam) {
			this.updateColor(conf.islands.foam.color);
			this.updateShadowColor(conf.islands.foam.shadow);
		}
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Islands.Waterfalls.Foam',
				lightPosition: {
					onChange: () => {
						if (this.material instanceof THREE.MeshToonMaterial) {
							return;
						}

						this.material.uniforms.uLightDirection.value.set(...Object.values(this.tweakValues.lightPosition))
					}
				},
				foamColor: {
					onChange: this.updateColor.bind(this),
				},
				foamShadowColor: {
					onChange: this.updateShadowColor.bind(this),
				}
			}
		);
	}

	private updateColor(color: string) {
		if (this.material instanceof THREE.MeshToonMaterial) {
			return;
		}

		this.material.uniforms.uFoamColor.value = new THREE.Color(color);
	}

	private updateShadowColor(color: string) {
		if (this.material instanceof THREE.MeshToonMaterial) {
			return;
		}

		this.material.uniforms.uFoamShadowColor.value = new THREE.Color(color);
	}

	private init() {
		this.extractMesh();
		this.createMaterial();
		this.applyMaterialToMesh();

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;
			if (!declineLevel) return;

			switch(declineLevel) {
				case 5:
					console.warn('Waterfalls: Low fps detected. Deleting foam.');
					this.flipShaderToToonMaterial();
					break;
			}
		});
	}

	private flipShaderToToonMaterial() {
		this.material = new THREE.MeshToonMaterial({
			color: new THREE.Color('#cafff8').multiplyScalar(5),
		});

		this.mesh.material = this.material;
	}

	private extractMesh() {
		this.group.traverse((child) => {
			if (!(child instanceof THREE.Mesh)) return;

			if (child.name === 'main-foam') {
				this.mesh = child;
				const oldGeometry = this.mesh.geometry;
				this.mesh.geometry = mergeVertices(this.mesh.geometry);
				this.mesh.geometry.computeTangents();
				oldGeometry.dispose();
			}
		});
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			vertexShader,
			fragmentShader,
			fog: true,
			uniforms: {
				uTime : new THREE.Uniform(0),
				uLightDirection : new THREE.Uniform(new THREE.Vector3(
					this.tweakValues.lightPosition.x,
					this.tweakValues.lightPosition.y,
					this.tweakValues.lightPosition.z,
				)),
				uFoamColor : new THREE.Uniform(new THREE.Color(this.tweakValues.foamColor)),
				uFoamShadowColor : new THREE.Uniform(new THREE.Color(this.tweakValues.foamShadowColor)),
				...THREE.UniformsLib.fog,
			},
		});
	}

	private applyMaterialToMesh() {
		this.mesh.material = this.material;
	}

	update() {
		if (!this.material || this.material instanceof THREE.MeshToonMaterial) {
			return;
		}

		if(this.material.uniforms?.uTime) {
			this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
		}
	}

	destroy() {
		this.mesh.removeFromParent();
		this.material?.dispose();
		this.mesh?.geometry.dispose();
	}
}