import * as THREE from 'three';
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import TextureUtils, {RGBAChannel} from "../../../lib/utils/TextureUtils.js";
import flowersVertexShader from "./shaders/vertex.glsl";
import flowersFragmentShader from "./shaders/fragment.glsl";
import Engine from '../../../lib/core/Engine.js';
import {MeshSurfaceSampler} from "three/examples/jsm/math/MeshSurfaceSampler.js";
import Bender from "../bender/Bender.js";
import config from "../../../config/Conf.js";

type InitialTweaks = {
	color1        : string,
	color2        : string,
	count         : number,
	size          : number,
	glowIntensity : number,
	bendingFactor : number,
}

type FlowersParams = {
	engine          : Engine,
	group           : THREE.Group,
	bender          : Bender,
	geometry        : THREE.BufferGeometry,
	resources       : Resources<typeof sources>,
	rgbChannelToUse : RGBAChannel,
	initialTweaks   : InitialTweaks,
};

export default class Flowers {
	private static id: number = 1;

	private static newId(): number {
		return Flowers.id++;
	}

	private readonly id             : number;
	private readonly engine         : Engine;
	private readonly group          : THREE.Group;
	private readonly bender         : Bender;
	private readonly parentGeometry : THREE.BufferGeometry;
	private readonly resources      : Resources<typeof sources>;
	private readonly channelToUse   : RGBAChannel;
	private readonly tweakValues    : InitialTweaks;

	private mesh            : THREE.Points         | undefined;
	private material        : THREE.ShaderMaterial | undefined;
	private flowersGeometry : THREE.BufferGeometry | undefined;

	constructor(
		{
			engine,
			group,
			bender,
			geometry,
			resources,
			rgbChannelToUse,
			initialTweaks
		}: FlowersParams
	) {
		this.id = Flowers.newId();

		this.group          = group;
		this.engine         = engine;
		this.bender         = bender;
		this.parentGeometry = geometry;
		this.resources      = resources;
		this.channelToUse   = rgbChannelToUse;
		this.tweakValues    = initialTweaks;

		this.init();
		this.configureTweaks();

		this.engine.on('global:config:changed', (event) => {
			const conf = event?.detail?.config;

			if (!conf) return;

			this.configChanged(conf);
		})
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder : `GrassField.Flowers.${this.id}`,
				color1 : {
					params: { type: 'color' },
					onChange: (value: string) => {
						if (!this.ready()) {
							return;
						}

						this.material!.uniforms.uFlowersColor1.value = new THREE.Color(value);
					}
				},
				color2 : {
					params: { type: 'color' },
					onChange: (value: string) => {
						if (!this.ready()) {
							return;
						}

						this.material!.uniforms.uFlowersColor2.value = new THREE.Color(value);
					}
				},
				size   : {
					params: {
						min: 0.01,
						max: 0.1,
						step: 0.01,
					},
					onChange: (value: number)  => {
						if (!this.ready()) {
							return;
						}

						this.material!.uniforms.uSize.value = value;
					}
				},
				count  : {
					params: {
						min: 500,
						max: 5000,
						step: 100
					},
					onChange: (value: number) => {
						console.warn('Flowers count changed to ' + value + ', but count change has not been implemented yet.');
					}
				},
				glowIntensity : {
					params: {
						min: 1.0,
						max: 30.0,
						step: 0.5,
					},
					onChange: this.updateGlowIntensity.bind(this),
				},

				bendingFactor : {
					params : {
						min  : 0.01,
						max  : 1,
						step : 0.01,
					},
					onChange: (value: number) => {
						if (!this.material) return;

						this.material.uniforms.uBendingFactor.value = value;
					},
				},
			}
		)
	}

	private configChanged(conf: typeof config) {
		if (conf.grassField.flowers.configs[this.id - 1].glowIntensity) {
			this.updateGlowIntensity(conf.grassField.flowers.configs[this.id - 1].glowIntensity);
		}
	}

	private updateGlowIntensity(value: number) {
		if (!this.material) return;

		this.material.uniforms.uFlowerGlowIntensity.value = value;
	}

	private init() {
		this.resources.onceAll(
			[
				'loaded:flowersTexture',
				'loaded:flowersSamplingTexture',
				'loaded:grassFieldDisplacementMap',
				'loaded:smoothWind',
			],
			() => {
				this.addWeightsAttributeToParentGeometry();
				this.createMaterial();
				this.createMesh();

				this.group.add(this.mesh!);
			}
		);
	}

	private ready() {
		return Boolean(this.material);
	}

	get resolution() {
		return new THREE.Vector2(...this.engine.sizes.resolution);
	}

	get weightAttributeName() {
		return `aWeight${this.channelToUse.toUpperCase()}`;
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			vertexShader   : flowersVertexShader,
			fragmentShader : flowersFragmentShader,
			transparent    : true,
			fog            : true,
			uniforms: {
				uTime            : new THREE.Uniform(0),
				uResolution      : new THREE.Uniform(this.resolution),
				uSize            : new THREE.Uniform(this.tweakValues.size),

				uFlowerTexture   : new THREE.Uniform(this.resources.items.flowersTexture),
				uDisplacementMap : new THREE.Uniform(this.resources.items.grassFieldDisplacementMap),
				uBendingTexture  : new THREE.Uniform(this.bender.texture),

				uFlowersColor1   : new THREE.Uniform(new THREE.Color(this.tweakValues.color1)),
				uFlowersColor2   : new THREE.Uniform(new THREE.Color(this.tweakValues.color2)),
				uMousePosition   : new THREE.Uniform(new THREE.Vector2(9999, 9999)),
				uFlowerGlowIntensity : new THREE.Uniform(this.tweakValues.glowIntensity),

				uBendingFactor : new THREE.Uniform(this.tweakValues.bendingFactor),
				uWindTexture   : new THREE.Uniform(this.resources.items.smoothWind),
				...THREE.UniformsLib.fog,
			},
			depthWrite: false,
		});

		this.engine.sizes.on('resize', () => {
			if (!this.ready()) return;

			this.material!.uniforms.uResolution.value = this.resolution;
		});
	}

	public updatePointerPosition(position: THREE.Vector2) {
		if (!this.material) return;

		this.material.uniforms.uMousePosition.value = position;
	}

	private createMesh() {
		this.createFlowersGeometry(
			...this.sampleFlowersAttributes()
		);

		this.mesh = new THREE.Points(
			this.flowersGeometry,
			this.material,
		);
	}

	private sampleFlowersAttributes(): [
		Float32Array<ArrayBuffer>,
		Float32Array<ArrayBuffer>,
		Float32Array<ArrayBuffer>,
		Float32Array<ArrayBuffer>,
		Float32Array<ArrayBuffer>,
		Float32Array<ArrayBuffer>,
		Float32Array<ArrayBuffer>,
	] {
		const samplerMesh = new THREE.Mesh(
			this.parentGeometry,
			new THREE.MeshBasicMaterial(),
		);

		const sampler = new MeshSurfaceSampler(samplerMesh)
			.setWeightAttribute(this.weightAttributeName)
			.build();

		const normal   = new THREE.Vector3();
		const position = new THREE.Vector3();
		const color    = new THREE.Color();
		const uv       = new THREE.Vector2();

		const {
			count,
		} = this.tweakValues;

		const flowersSize        = new Float32Array(count);
		const flowersRotation    = new Float32Array(count);
		const flowersColorMix    = new Float32Array(count);
		const flowersDeformation = new Float32Array(count * 2);
		const flowersPosition    = new Float32Array(count * 3);
		const flowersNormal      = new Float32Array(count * 3);
		const flowersUv          = new Float32Array(count * 2);

		for (let i = 0; i < count; i++) {
			const i2 = i * 2;
			const i3 = i * 3;

			sampler.sample(position, normal, color, uv);

			flowersSize[i]     = Math.min(Math.random() + 0.6, 1.0);
			flowersColorMix[i] = Math.random();
			flowersRotation[i] = (Math.random() - 0.5) * Math.PI * 0.25;

			flowersDeformation[i2    ] = 1.15 + (Math.random() - 0.5) * 0.4;
			flowersDeformation[i2 + 1] = 1.15 + (Math.random() - 0.5) * 0.4;

			flowersPosition[i3    ] = position.x;
			flowersPosition[i3 + 1] = position.y;
			flowersPosition[i3 + 2] = position.z;

			flowersNormal[i3    ] = normal.x;
			flowersNormal[i3 + 1] = normal.y;
			flowersNormal[i3 + 2] = normal.z;

			flowersUv[i2    ] = uv.x;
			flowersUv[i2 + 1] = uv.y;
		}

		samplerMesh.material.dispose();

		return [
			flowersSize,
			flowersRotation,
			flowersColorMix,
			flowersDeformation,
			flowersPosition,
			flowersNormal,
			flowersUv,
		];
	}

	private createFlowersGeometry(
		flowersSize        : Float32Array<ArrayBuffer>,
		flowersRotation    : Float32Array<ArrayBuffer>,
		flowersColorMix    : Float32Array<ArrayBuffer>,
		flowersDeformation : Float32Array<ArrayBuffer>,
		flowersPosition    : Float32Array<ArrayBuffer>,
		flowersNormal      : Float32Array<ArrayBuffer>,
		flowersUv          : Float32Array<ArrayBuffer>,
	) {
		const flowersGeometry = new THREE.BufferGeometry();

		const flowersSizeAttribute        = new THREE.BufferAttribute(flowersSize        , 1);
		const flowersRotationAttribute    = new THREE.BufferAttribute(flowersRotation    , 1);
		const flowersColorMixAttribute    = new THREE.BufferAttribute(flowersColorMix    , 1);
		const flowersDeformationAttribute = new THREE.BufferAttribute(flowersDeformation , 2);
		const flowersPositionAttribute    = new THREE.BufferAttribute(flowersPosition    , 3);
		const flowersNormalAttribute      = new THREE.BufferAttribute(flowersNormal      , 3);
		const flowersUvAttribute          = new THREE.BufferAttribute(flowersUv          , 2);

		flowersGeometry.setAttribute('aSize'        , flowersSizeAttribute        );
		flowersGeometry.setAttribute('aRotation'    , flowersRotationAttribute    );
		flowersGeometry.setAttribute('aColorMix'    , flowersColorMixAttribute    );
		flowersGeometry.setAttribute('aDeformation' , flowersDeformationAttribute );
		flowersGeometry.setAttribute('aNormal'      , flowersNormalAttribute      );
		flowersGeometry.setAttribute('position'     , flowersPositionAttribute    );
		flowersGeometry.setAttribute('aUv'          , flowersUvAttribute          );

		this.flowersGeometry = flowersGeometry;
	}

	addWeightsAttributeToParentGeometry() {
		const texture = new TextureUtils(this.resources.items.flowersSamplingTexture);

		const weights = texture.createVertexWeightsFromTexture(
			this.parentGeometry,
			this.channelToUse,
		);

		this.parentGeometry.setAttribute(
			this.weightAttributeName,
			weights,
		);
	}

	update() {
		if (!this.ready()) return;

		this.material!.uniforms.uTime.value = this.engine.time.elapsedSeconds;
	}

	destroy() {
		if (!this.mesh) return;

		this.group.remove(this.mesh);
		this.material?.dispose();
		this.flowersGeometry?.dispose();
	}
}