import {FolderApi, Pane} from 'tweakpane';
import TweaksCapabilities, {ConfigOptions} from "./TweaksCapabilities.js";

function typedKeys<T extends object>(obj: T): (keyof T)[] {
	return Object.keys(obj) as (keyof T)[];
}

export default class Tweaks implements TweaksCapabilities {
	static isActive(): boolean {
		const queryString = window.location.search;

		const urlParams = new URLSearchParams(queryString);
		const debugParam = urlParams.get('debug');

		return debugParam === 'true';
	}

	private readonly folders : Record<string, FolderApi>;
	private draggableFeatureInitialized : boolean;

	readonly #ui?: Pane;
	private textarea?: HTMLTextAreaElement;

	constructor() {
		this.folders = {};
		this.draggableFeatureInitialized = false;

		if (Tweaks.isActive()) {
			this.#ui = new Pane({
				title: 'Tweaks',
			});

			this.textarea = document.createElement('textarea')!;
			this.textarea.style.width = '100%';
			this.textarea.style.height = '150px';
			this.textarea.style.fontFamily = 'monospace';
			this.textarea.style.fontSize = '12px';
			this.textarea.style.boxSizing = 'border-box';
			this.textarea.style.resize = 'vertical';
			this.textarea.style.margin = '0';

			this.configure({}, {
				folder: 'Import/Export',
				buttons: {
					'Apply': () => {
						try {
							const config = JSON.parse(this.textarea?.value ?? '');

							this.#ui!.importState(config);
						} catch(err: any) {
							alert(`❌ unable to apply configuration : ${err?.stack ?? err}`);
						}
					},
					'Download': this.downloadAsJSON.bind(this),
					'Copy to clipboard': this.copyToClipboard.bind(this),
				},
			});

			const exportFolder = this.getFolder('Import/Export')!;
			const button = exportFolder.element.querySelector('.tp-fldv_c > :first-child')!;
			button.parentNode?.insertBefore(this.textarea, button);

			this.#ui.on('change', this.updateConfigExporterState.bind(this));
		} else {
			this.enhanceOrbitControlSupport();
		}
	}

	private enhanceOrbitControlSupport() {
		document.addEventListener('touchmove', (e) => {
			e.preventDefault();
		}, { passive: false });
	}

	private async copyToClipboard() {
		try {
			const config = this.textarea?.value ?? '';
			await navigator.clipboard.writeText(config);
			alert('✅ Config copied to clipboard!');
		} catch {
			this.downloadAsJSON();
		}
	}

	private downloadAsJSON() {
		try {
			const config = this.textarea?.value ?? '';
			const blob = new Blob([config], { type: 'application/json' });
			const url = URL.createObjectURL(blob);

			const a = document.createElement('a');
			a.href = url;
			a.download = 'tweakpane-config.json';
			a.click();

			URL.revokeObjectURL(url);
			alert('✅ Config downloaded!');
		} catch (err: any) {
			alert(`❌ Unable to download configuration:\n${err?.stack ?? err}`);
		}
	}

	private updateConfigExporterState() {
		const folder = this.getFolder('Import/Export');
		if (!folder) return;

		folder.element.parentNode?.appendChild(folder.element);
		const last = folder.element.parentNode?.querySelector(':scope > .tp-v-lst.tp-v-vlst');
		last?.classList?.remove('tp-v-lst', 'tp-v-vlst');
		folder.element.classList.add('tp-v-lst', 'tp-v-vlst');
		folder.element.classList.remove('tp-v-fst');

		if (!this.textarea) return;

		const config = this.#ui!.exportState();
		this.textarea.value = JSON.stringify(config, null, 2);
	}

	private initDraggableFeature() {
		if (this.draggableFeatureInitialized) {
			return;
		}

		if (!this.#ui) {
			return;
		}

		const pane = document.querySelector('.tp-dfwv')! as HTMLElement;
		const dragControl = document.querySelector('.tp-rotv_b')! as HTMLElement;

		if (!dragControl || !pane) {
			return;
		}

		let isDragging = false;
		let offsetX = 0;
		let offsetY = 0;

		function onDragStart(clientX: number, clientY: number) {
			isDragging = true;
			offsetX = clientX - pane.offsetLeft;
			offsetY = clientY - pane.offsetTop;
		}

		function onDragMove(clientX: number, clientY: number) {
			if (!isDragging) return;
			pane.style.left = `${clientX - offsetX}px`;
			pane.style.top = `${clientY - offsetY}px`;
		}

		function onDragEnd() {
			isDragging = false;
		}

		dragControl.addEventListener('mousedown', (e) => {
			onDragStart(e.clientX, e.clientY);
		});
		document.addEventListener('mousemove', (e) => {
			onDragMove(e.clientX, e.clientY);
		});
		document.addEventListener('mouseup', onDragEnd);

		dragControl.addEventListener('touchstart', (e) => {
			const touch = e.touches[0];
			onDragStart(touch.clientX, touch.clientY);
		}, { passive: true });

		document.addEventListener('touchmove', (e) => {
			e.preventDefault();

			const touch = e.touches[0];
			if (touch) onDragMove(touch.clientX, touch.clientY);
		}, { passive: false });

		document.addEventListener('touchend', onDragEnd);
	}

	private getFolder(name: string): FolderApi | undefined {
		if (!this.#ui) {
			return;
		}

		if (!(name in this.folders)) {
			const path = name.split('.');
			let parentFolder: FolderApi | Pane = this.#ui;
			let currentPath: string = '';

			for(const folderName of path) {
				if (!currentPath) {
					currentPath = folderName;
				} else {
					currentPath += `.${folderName}`;
				}

				if (currentPath in this.folders) {
					parentFolder = this.folders[currentPath];
				} else {
					parentFolder = parentFolder.addFolder({
						title: folderName,
					});

					parentFolder.expanded = false;
					this.folders[currentPath] = parentFolder;
				}
			}
		}

		this.folders[name].expanded = false;

		return this.folders[name];
	}

	update(): void {
		if (!this.#ui) return;

		this.#ui.refresh();
	}

	configure<T extends Record<string, unknown>>(
		params: T,
		{
			folder,
			buttons,
			...bindingParams
		}: ConfigOptions<T> = {}
	) {
		if (!this.#ui) return;

		const parent = folder
			? this.getFolder(folder) ?? this.#ui
			: this.#ui;

		Object.entries(buttons ?? {}).forEach(([key, callback]) => {
			const button = parent.addButton({
				title: key,
			});

			button.on('click', callback);
		});

		typedKeys(params).forEach(<K extends keyof T>(key: K) => {
			const bindingOptions = bindingParams?.[key]?.params;
			const bindingListener = bindingParams?.[key]?.onChange as ((value: T[K]) => void) | undefined;

			if (Array.isArray(params[key])) {
				console.warn(`Ignored key ${String(key)}: arrays not supported yet`);
				return;
			}

			parent.addBinding(params, key, bindingOptions)
				.on('change', (event) => {
					bindingListener?.(event.value);
				});
		});

		if (!this.draggableFeatureInitialized) {
			this.initDraggableFeature();
		}

		this.updateConfigExporterState();
	}

	destroy() {
		if (!this.#ui) {
			return;
		}

		this.#ui.dispose();
	}
}