import * as THREE from 'three';
import Engine from "../../../../lib/core/Engine.js";
import WindLinePool from "./WindLinePool.js";

type WindLinesParams = {
	engine      : Engine,
	group       : THREE.Group,
	boundingBox : THREE.Box3,
}

export default class WindLines {
	private readonly group       : THREE.Group;
	private readonly parentGroup : THREE.Group;
	private readonly lines       : WindLinePool;

	constructor(
		{
			engine,
			group,
			boundingBox,
		}: WindLinesParams
	) {
		this.parentGroup = group;
		this.group       = new THREE.Group();

		const adjustedBox = boundingBox.clone();
		adjustedBox.min.multiplyScalar(0.5);
		adjustedBox.max.add(new THREE.Vector3(0, 0.5, 0));
		adjustedBox.translate(new THREE.Vector3(-2, 0.3, 0.5));

		this.lines = new WindLinePool({
			engine,
			boundingBox: adjustedBox,
			group : this.group,
		});

		this.init();
	}

	private init() {
		this.group.rotateY(Math.PI * -0.25);

		this.parentGroup.add(this.group);
	}

	update() {
		this.lines.update();
	}

	destroy() {
		this.parentGroup.remove(this.group);
		this.lines.destroy();
	}
}