import Experience from "../Experience.js";
import { EVENTS as CAMERA_SPOTS_EVENTS } from "../CameraSpots.js";
import EventEmitter from "../lib/utils/EventEmitter.js";

export enum EVENTS {
	LOOK_AROUND_HINT_HIDDEN = "LOOK_AROUND_HINT_HIDDEN",
}

export default class HomeSection extends EventEmitter{
	private readonly experience: Experience;

	constructor(experience: Experience) {
		super();

		this.experience = experience;

		this.init();
	}

	private init() {
		const lookAround = document.querySelector('.look-around-hint')!;

		this.experience.cameraSpots.on(CAMERA_SPOTS_EVENTS.INTRO_PLAYED, () => {
			document.addEventListener('pointerdown', () => {
				lookAround.classList.remove('show');
				this.emit(EVENTS.LOOK_AROUND_HINT_HIDDEN);
			}, { once: true });

			lookAround.classList.add('show');
		});
	}
}