import * as THREE from 'three';
import Resources from "../../lib/core/Resources.js";
import sources from "../../config/resources.config.js";
import Environment from "../../environment/Environment.js";
import Engine from "../../lib/core/Engine.js";
import createLightStandardMaterial from "../../lib/materials/light/LightStandardMaterial.js";

type CliffsParams = {
	engine      : Engine,
	group       : THREE.Group,
	resources   : Resources<typeof sources>,
	environment : Environment,
};

export default class Cliffs {
	private readonly group       : THREE.Group;
	private readonly resources   : Resources<typeof sources>;
	private readonly environment : Environment;
	private readonly engine      : Engine;

	private topIslandCliffs!  : THREE.Mesh[];
	private mainIslandCliffs! : THREE.Mesh;
	private material!         : THREE.Material;

	constructor(
		{
			engine,
			group,
			environment,
			resources,
		}: CliffsParams
	) {
		this.engine      = engine;
		this.group       = group;
		this.resources   = resources;
		this.environment = environment;

		this.init();
	}

	private init() {
		this.extractMeshes();
		this.initTexture();
		this.applyCliffsTexture();
	}

	private extractMeshes() {
		this.topIslandCliffs = [];

		this.group.traverse((child) => {
			if (!(child instanceof THREE.Mesh)) return;

			if (child.name === 'main-island') {
				this.mainIslandCliffs = child;
			}

			if (['top-island-south', 'top-island-north', 'top-island'].includes(child.name)) {
				this.topIslandCliffs.push(child);
			}
		});
	}

	private initTexture() {
		this.material = new THREE.MeshStandardMaterial({
			map       : this.resources.items.cliffsColor,
			normalMap : this.resources.items.cliffsNormal,
			aoMap     : this.resources.items.cliffsAo,
			aoMapIntensity : 1,
			roughnessMap : this.resources.items.cliffsRoughness,
			fog: true,
			// Fixing visible seems;
			side: THREE.DoubleSide,
		});

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;

			switch(declineLevel) {
				case 3:
					this.flipStandardForShaderMaterial();
					break;
			}
		});
	}

	private flipStandardForShaderMaterial() {
		console.warn('Cliffs: Low fps detected. Switching to light material');

		this.material.dispose();
		this.material = createLightStandardMaterial(
			this.resources.items.cliffsColor,
			this.resources.items.environmentMap,
			new THREE.Color('#c8c7c3')
		);

		this.applyCliffsTexture();
	}

	private applyCliffsTexture() {
		this.mainIslandCliffs.material      = this.material;
		this.mainIslandCliffs.receiveShadow = true;
		this.mainIslandCliffs.castShadow    = true;

		this.topIslandCliffs.forEach((cliff) => {
			cliff.material      = this.material;
			cliff.castShadow    = true;
			cliff.receiveShadow = true;
		});

		this.environment.updateMaterials();
	}

	destroy() {
		this.material?.dispose();
		this.mainIslandCliffs?.geometry.dispose();
		this.topIslandCliffs?.forEach((cliff) => {
			cliff.geometry.dispose();
		});
	}
}