import Experience from "../Experience.js";
import { EVENTS as CAMERA_SPOTS_EVENTS } from "../CameraSpots.js";
import EventEmitter from "../lib/utils/EventEmitter.js";

type SectionName = 'home' | 'about' | 'contact';

export enum EVENTS {
	CHOOSED_CONTACT = 'CHOOSE_CONTACT',
}

export default class MainMenu extends EventEmitter{
	private readonly experience: Experience;

	private readonly navHome: Element;
	private readonly navAbout: Element;
	private readonly navContact: Element;

	private readonly homeSection: Element;
	private readonly aboutSection: Element;
	private readonly contactSection: Element;

	private readonly closeAboutSection: Element;

	private lastDisplayedSection: SectionName;
	private currentlyDisplayedSection: SectionName;

	constructor(experience: Experience) {
		super();

		this.experience = experience;

		this.navHome = document.querySelector('nav a[href="#home"]')!;
		this.navAbout = document.querySelector('nav a[href="#about"]')!;
		this.navContact = document.querySelector('nav a[href="#contact"]')!;

		this.homeSection = document.querySelector('#home')!;
		this.aboutSection = document.querySelector('#about')!;
		this.contactSection = document.querySelector('#contact')!;

		this.closeAboutSection = document.querySelector('#about .close')!;

		this.lastDisplayedSection = 'home';
		this.currentlyDisplayedSection = 'home';

		this.init();
	}

	private updateBodyAttribute(item: SectionName) {
		window.document.body.setAttribute('data-section', item);
	}

	public display(item: SectionName) {
		let updateSectionsState = !this.isSectionActive(item);

		switch(item) {
			case 'about':
				this.displayAbout();
				break;
			case 'contact':
				this.displayContact();
				break;
			case 'home':
				this.displayHome();
				break;
			default: throw new Error(`Unsupported Navigation item ${item} supplied`);
		}

		if (updateSectionsState) {
			this.lastDisplayedSection      = this.currentlyDisplayedSection;
			this.currentlyDisplayedSection = item;
		}
	}

	private displayHome() {
		if (this.isSectionActive('home')) {
			return;
		}

		this.experience.engine.camera.enableControls();

		this.experience.engine.audio.items.button.stop();
		this.experience.engine.audio.items.button.play();

		[this.aboutSection, this.contactSection].forEach(section => {
			section.classList.add('hidden');
		});

		[this.navAbout, this.navContact].forEach(nav => {
			nav.classList.remove('active');
		});

		this.navHome.classList.add('active');
		this.homeSection.classList.remove('hidden');
		this.updateBodyAttribute('home');
	}

	private isSectionActive(section: SectionName) {
		switch (section) {
			case 'about':
				return this.navAbout.classList.contains('active');
			case 'contact':
				return this.navContact.classList.contains('active');
			case 'home':
				return this.navHome.classList.contains('active');
			default: throw new Error(`Unsupported Navigation item ${section}`);
		}
	}

	private displayAbout() {
		if (this.isSectionActive('about')) {
			if (this.lastDisplayedSection === 'about') {
				return;
			}

			this.display(this.lastDisplayedSection);
			return;
		}

		this.experience.engine.camera.enableControls();

		this.experience.engine.audio.items.button.stop();
		this.experience.engine.audio.items.button.play();
		[this.homeSection, this.contactSection].forEach(section => {
			section.classList.add('hidden');
		});

		[this.navHome, this.navContact].forEach(nav => {
			nav.classList.remove('active');
		});

		this.navAbout.classList.add('active');
		this.aboutSection.classList.remove('hidden');
		this.updateBodyAttribute('about');
	}

	private displayContact() {
		if (this.isSectionActive('contact')) {
			return;
		}

		if (this.isSectionActive('about')) {
			this.displayHome();
		}

		this.experience.engine.audio.items.button.stop();
		this.experience.engine.audio.items.button.play();

		this.emit(EVENTS.CHOOSED_CONTACT);

		this.experience.cameraSpots.goTo('contact', {
			ease: 'power1.inOut',
			onComplete: () => {
				this.showContactUi();
			},
		});
	}

	public showContactUi() {
		this.experience.engine.camera.disableControls();

		[this.homeSection, this.aboutSection].forEach(section => {
			section.classList.add('hidden');
		});

		[this.navHome, this.navAbout].forEach(nav => {
			nav.classList.remove('active');
		});

		this.navContact.classList.add('active');
		this.contactSection.classList.remove('hidden');
		this.updateBodyAttribute('contact');
	}

	private init() {
		const nav = document.querySelector('nav')!;

		this.experience.cameraSpots.on(CAMERA_SPOTS_EVENTS.INTRO_PLAYED, () => {
			nav.classList.remove('hidden');
		});

		this.navHome.addEventListener('click', () => this.display('home'));
		this.navAbout.addEventListener('click', () => this.display('about'));
		this.navContact.addEventListener('click', () => this.display('contact'));

		this.closeAboutSection.addEventListener('click', () => this.display('about'));
	}
}