import * as THREE from 'three';
import AbstractPostProcessing from './lib/core/PostProcessing.js';
import Engine from "./lib/core/Engine.js";
import {
	BlendFunction,
	BloomEffect,
	EffectPass, SMAAEffect,
	ToneMappingEffect,
	ToneMappingMode,
	VignetteEffect,
	VignetteTechnique
} from "postprocessing";
import {GodraysPass} from "./lib/effects/godrays/index.js";
import Light from "./Light.js";
import config from "./config/Conf.js";

type PostProcessingParams = {
	engine: Engine,
	light: Light,
}

type TweakValues = {
	bloomIntensity: number,
	godrays: boolean,
}

export default class PostProcessing extends AbstractPostProcessing {
	private readonly engine: Engine;
	private readonly light: Light;
	private readonly tweakValues: TweakValues;

	private godraysPass!: GodraysPass;
	private bloomEffect!: BloomEffect;
	private vignetteEffect!: VignetteEffect;
	private mainPass!: EffectPass;
	private toneMappingEffect!: ToneMappingEffect;

	constructor(
		{
			light,
			engine,
		}: PostProcessingParams
	) {
		super({
			scene: engine.scene,
			camera: engine.camera,
			sizes: engine.sizes,
			renderer: engine.renderer,
		});

		this.light = light;
		this.engine = engine;
		this.tweakValues = {
			bloomIntensity: 0.1,
			godrays: true,
		};

		this.init();
		this.configureTweaks();
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Scene.PostProcessing',
				godrays: {
					onChange: (value: boolean) => {
						if (value) {
							this.enableGodrays();
						} else {
							this.disableGodrays();
						}
					}
				},
				bloomIntensity: {
					params: {
						min: 0,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						this.bloomEffect.intensity = value;
					}
				}
			}
		)
	}

	public enableGodrays() {
		this.godraysPass.enabled = true;
	}

	public disableGodrays() {
		this.godraysPass.enabled = false;
	}

	private init() {
		this.light.once('ready', () => {

			this.bloomEffect = new BloomEffect({
				intensity          : this.tweakValues.bloomIntensity,
				luminanceThreshold : 1.0,
				mipmapBlur         : true,
				blendFunction      : BlendFunction.ADD,
			});

			// Default values are shown.  You can supply a sparse object or `undefined`.
			const params = {
				density: config.scene.godrays.density,
				maxDensity: 0.12,
				edgeStrength: 5,
				edgeRadius: 1,
				distanceAttenuation: 0,
				color: new THREE.Color(config.scene.godrays.color),
				raymarchSteps: 25,
				blur: true,
				gammaCorrection: false,
			};

			this.godraysPass = new GodraysPass(
				this.light.light,
				this.engine.camera.instance,
				params,
			);

			this.engine.on('global:config:changed', (event) => {
				const config = event?.detail?.config;
				if (!config) return;

				if (config.scene.godrays.color) {
					params.color = new THREE.Color(config.scene.godrays.color);
				}

				if (config.scene.godrays.density) {
					params.density = config.scene.godrays.density;
				}

				this.godraysPass.setParams(params);

				if ('enabled' in config.scene.godrays) {
					this.godraysPass.enabled = config.scene.godrays.enabled;
				}
			});

			this.vignetteEffect = new VignetteEffect({
				offset: 0.4,
				technique: VignetteTechnique.DEFAULT,
				darkness: 0.6,
			});

			this.toneMappingEffect = new ToneMappingEffect({
				mode: ToneMappingMode.ACES_FILMIC,
				resolution: this.engine.sizes.resolutionAsNumber,
			});

			this.mainPass = new EffectPass(
				this.engine.camera.instance,
				this.bloomEffect,
				this.vignetteEffect,
				...this.advisedEffectPasses,
				this.toneMappingEffect,
			);

			this.effectComposer.addPass(this.godraysPass);
			this.effectComposer.addPass(this.mainPass);

			this.engine.monitor.on('decline', (event) => {
				const declineLevel = event?.detail?.declineLevel;
				if (!declineLevel) return;

				switch(declineLevel) {
					case 1:
						this.disableGodRays();
						break;
					case 5:
						this.useMinimalEffects();
						break;
				}
			});
		});
	}

	private disableGodRays() {
		console.warn('Postprocessing: Low fps detected. Godrays disabled.');
		this.effectComposer.removePass(this.godraysPass);
	}

	private useMinimalEffects() {
		console.warn('Postprocessing: Low fps detected. Disabling antialiasing and vignette.');

		this.effectComposer.removePass(this.mainPass);
		this.effectComposer.addPass(
			new EffectPass(
				this.engine.camera.instance,
				this.bloomEffect,
				this.toneMappingEffect,
			),
		);
	}
}