import * as THREE from 'three';
import {GPUComputationRenderer, Variable} from 'three/examples/jsm/misc/GPUComputationRenderer.js';
import { Ground } from "../ground/Ground.js";
import Engine from "../../../lib/core/Engine.js";
import fragmentShader from './shaders/fragment.glsl';
import vertexShader from './shaders/vertex.glsl';

type TweakValues = {
	brushRadius  : number;
	fadingFactor : number;
}

type BenderParams = {
	ground: Ground;
	engine: Engine;
	initialTweaks : TweakValues,
};

/**
 * In seconds: the threshold beyond which we don't update the uniform
 * because we guess the chrome tab was IDLE to avoid visual glitches
 */
const DEFAULT_IDLE_THRESHOLD = 10;

export default class Bender {
	private readonly engine      : Engine;
	private readonly ground      : Ground;
	private readonly gpuCompute  : GPUComputationRenderer;
	private readonly textureSize : number;
	private readonly tweakValues : TweakValues;

	private readonly lastMouseWorldPosition    : THREE.Vector3;

	private readonly bendingVariable!: Variable;

	public readonly texture!: THREE.Texture;

	constructor({ ground, engine, initialTweaks }: BenderParams) {
		this.ground      = ground;
		this.engine      = engine;
		this.textureSize = 1024;
		this.tweakValues = initialTweaks;
		this.lastMouseWorldPosition = new THREE.Vector3(0, 0, 0);

		this.gpuCompute = new GPUComputationRenderer(
			this.textureSize,
			this.textureSize,
			this.engine.renderer.instance,
		);

		const initialTexture = this.gpuCompute.createTexture();
		this.fillInitialTexture(initialTexture);

		this.bendingVariable = this.gpuCompute.addVariable(
			"uTextureBending",
			fragmentShader,
			initialTexture
		);
		this.bendingVariable.material.vertexShader = vertexShader;

		this.gpuCompute.setVariableDependencies(this.bendingVariable, [this.bendingVariable]);

		const material = this.bendingVariable.material;
		material.uniforms.uMouseUv      = new THREE.Uniform(new THREE.Vector2(9999, 9999));
		material.uniforms.uDirection    = new THREE.Uniform(new THREE.Vector3(0, 0, 0));
		material.uniforms.uBrushRadius  = new THREE.Uniform(this.tweakValues.brushRadius);
		material.uniforms.uDelta        = new THREE.Uniform(0);
		material.uniforms.uFadingFactor = new THREE.Uniform(1);

		const error = this.gpuCompute.init();
		if (error) throw new Error(error);

		this.texture = this.gpuCompute.getCurrentRenderTarget(this.bendingVariable).texture;

		this.init();
		this.configureTweaks();
		// this.addDebugPlane();
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: `GrassField.Bender`,
				brushRadius: {
					params: {
						min: 0.001,
						max: 0.20,
						step: 0.001,
					},
					onChange: (value: number) => {
						this.bendingVariable.material.uniforms.uBrushRadius.value = value;
					}
				},
				fadingFactor: {
					params: {
						min: 0,
						max: 4,
						step: 0.25
					},
					onChange: (value: number) => {
						this.bendingVariable.material.uniforms.uFadingFactor.value = value;
					}
				}
			}
		)
	}

	private addDebugPlane() {
		const axesHelper = new THREE.AxesHelper( 5 );
		this.engine.scene.add( axesHelper );

		const material = new THREE.MeshBasicMaterial({
			map: this.texture,
			side: THREE.DoubleSide,
			transparent: true,
		});
		const mesh = new THREE.Mesh(this.ground.geometry, material);

		mesh.position.set(0.8, 0.8, -1);

		this.engine.scene.add(mesh);
	}

	private fillInitialTexture(texture: THREE.DataTexture) {
		const data = texture.image.data;

		if (data instanceof Float32Array) {
			// Normalized float values (0.0 - 1.0)
			for (let i = 0; i < data.length; i += 4) {
				data[i    ] = 0.0; // bending
				data[i + 1] = 0.51; // direction X
				data[i + 2] = 0.51; // direction Y
				data[i + 3] = 0.51; // direction Z
			}
		} else if (data instanceof Uint8Array) {
			// Integer range (0 - 255)
			for (let i = 0; i < data.length; i += 4) {
				data[i    ] = 0;     // bending
				data[i + 1] = 129;   // 0.5 * 255
				data[i + 2] = 129;
				data[i + 3] = 129;
			}
		} else {
			// fallback (tries float-like values)
			for (let i = 0; i < data.byteLength; i += 4) {
				// @ts-ignore
				data[i    ] = 0;
				// @ts-ignore
				data[i + 1] = 0.51;
				// @ts-ignore
				data[i + 2] = 0.51;
				// @ts-ignore
				data[i + 3] = 0.51;
			}
			console.warn('Unknown texture data type; fallback write performed.');
		}

		texture.needsUpdate = true;
	}

	private init() {
		this.ground.on("pointerMove", (event) => {
			if (!event) return;

			const uv = event.detail.intersect.uv as THREE.Vector2;
			const worldPos = event.detail.intersect.point as THREE.Vector3;

			const dir = new THREE.Vector3().subVectors(worldPos, this.lastMouseWorldPosition).normalize();

			this.bendingVariable.material.uniforms.uMouseUv.value.copy(uv);
			this.bendingVariable.material.uniforms.uDirection.value.copy(dir);
			this.lastMouseWorldPosition.copy(worldPos);
		});

		this.ground.on('pointerOut', () => {
			this.bendingVariable.material.uniforms.uMouseUv.value.set(9999, 9999);
			this.bendingVariable.material.uniforms.uDirection.value.set(0, 0, 0);
			this.lastMouseWorldPosition.copy(new THREE.Vector3(0, 0, 0));
		});
	}

	update() {
		const delta = this.engine.time.deltaSeconds;

		if (delta > DEFAULT_IDLE_THRESHOLD) {
			return;
		}

		this.bendingVariable.material.uniforms.uDelta.value = this.engine.time.deltaSeconds;
		this.gpuCompute.compute();
	}

	destroy() {
		this.texture.dispose();
		this.gpuCompute.dispose();
	}
}
