import * as THREE from 'three'
import {CatmullRomCurve3} from "three";

type CreateCurveParams = {
	points?    : THREE.Vector3[],
	length?    : number,
	amplitude? : number,
	directorPointsCount? : number,
}

type LineGeometryParams = CreateCurveParams & {
	samplePoints?: number,
}

export default class LineGeometry extends THREE.BufferGeometry{
	constructor(
		{
			samplePoints = 51,
			...curveParams
		}: LineGeometryParams = {}
	) {
		super();

		const curve = this.createCurve(curveParams);
		const sampledPoints = curve.getPoints(
			// Ensure we only have full quads
			samplePoints % 2 === 0
				? samplePoints + 1
				: samplePoints,
		);
		this.createPairOfVertices(curve, sampledPoints);
		this.generateGeometryIndexes(sampledPoints.length);
		this.computeVertexNormals();
	}

	private createPairOfVertices(
		curve: THREE.CatmullRomCurve3,
		sampledPoints: THREE.Vector3[],
	) {
		const sampledPointsCount = sampledPoints.length;

		const positions        = new Float32Array(sampledPointsCount * 2 * 3); // 2 vertices per point, 3 coords each
		const tangents         = new Float32Array(sampledPointsCount * 2 * 3);
		const curveProgression = new Float32Array(sampledPointsCount * 2);

		const vertexIds        = new Uint16Array(sampledPointsCount * 2);

		for (let i = 0; i < sampledPointsCount; i++) {
			const point           : THREE.Vector3 = sampledPoints[i];
			const positionOnCurve : number        = i / (sampledPointsCount - 1);
			const tangent         : THREE.Vector3 = curve.getTangent(positionOnCurve).normalize();

			const firstPointIndex = i * 2;

			vertexIds[firstPointIndex        ] = 0;
			curveProgression[firstPointIndex ] = i / sampledPoints.length;
			positions.set(point.toArray(),   firstPointIndex * 3);
			tangents .set(tangent.toArray(), firstPointIndex * 3);

			const secondPointIndex = i * 2 + 1;

			vertexIds[secondPointIndex]        = 1;
			curveProgression[secondPointIndex] = i / sampledPoints.length;
			positions.set(point.toArray(),   secondPointIndex * 3);
			tangents .set(tangent.toArray(), secondPointIndex * 3);
		}

		this.setAttribute('position',  new THREE.BufferAttribute(positions, 3));
		this.setAttribute('aVertexId', new THREE.BufferAttribute(vertexIds, 1));
		this.setAttribute('aTangent',  new THREE.BufferAttribute(tangents, 3));
		this.setAttribute('aCurveProgression', new THREE.BufferAttribute(curveProgression, 1));
	}

	private generateGeometryIndexes(sampledPointsCount: number) {
		const indices = new Uint16Array((sampledPointsCount - 1) * 6);

		for (let i = 0; i < sampledPointsCount - 1; i++) {
			const indexLeftTop     = i * 2;
			const indexRightTop    = i * 2 + 1;
			const indexLeftBottom  = (i + 1) * 2;
			const indexRightBottom = (i + 1) * 2 + 1;

			// Triangle 1
			indices[i * 6 + 0] = indexLeftTop;
			indices[i * 6 + 1] = indexRightTop;
			indices[i * 6 + 2] = indexLeftBottom;

			// Triangle 2
			indices[i * 6 + 3] = indexRightTop;
			indices[i * 6 + 4] = indexRightBottom;
			indices[i * 6 + 5] = indexLeftBottom;
		}

		this.setIndex(new THREE.BufferAttribute(indices, 1));
	}

	private createCurve(params: LineGeometryParams): THREE.CatmullRomCurve3 {
		const curve = new CatmullRomCurve3(
			this.extractOrGeneratePoints(params),
		);

		curve.curveType = 'centripetal';
		curve.closed = false;

		return curve;
	}

	private extractOrGeneratePoints({ points, ...rest }: LineGeometryParams = {}) {
		if (Array.isArray(points) && points.length > 0) {
			return points;
		}

		return this.generateRandomPoints(rest);
	}

	private generateRandomPoints(
		{
			length              = 2,
			amplitude           = 0.25,
			directorPointsCount = 4
		}: Omit<LineGeometryParams, 'points'>
	) {
		const halfExtent : number          = length / 2;
		const span       : number          = length / (directorPointsCount - 1);
		const points     : THREE.Vector3[] = [];

		for (let i = 0; i < directorPointsCount; i++) {
			points.push(new THREE.Vector3(
				0,
				(i % 2 - 0.5) * amplitude,
				-halfExtent + i * span,
			));
		}

		return points;
	}
}