function isDayTime() {
	const now = new Date();
	const hour = now.getHours();
	const month = now.getMonth(); // 0 = Jan, 11 = Dec

	// rough average sunrise/sunset times by season
	const seasonTimes = [
		{ sunrise: 7, sunset: 17 }, // Winter (Dec–Feb)
		{ sunrise: 6, sunset: 19 }, // Spring (Mar–May)
		{ sunrise: 5, sunset: 21 }, // Summer (Jun–Aug)
		{ sunrise: 6, sunset: 18 }, // Autumn (Sep–Nov)
	];

	const season = Math.floor(month / 3);
	const { sunrise, sunset } = seasonTimes[season];

	return hour >= sunrise && hour < sunset;
}

export default class DayTimeSwitch {
	private readonly experience: Experience;
	private readonly initialConf!: typeof config;
	private readonly switchElement: HTMLDivElement;

	private mode: MODE;
	private shouldCrossfade: boolean;

	constructor(
		experience: Experience,
		conf: typeof config = config,
	) {
		this.mode = MODE.NIGHT;
		this.shouldCrossfade = false;
		this.experience = experience;
		this.initialConf = JSON.parse(JSON.stringify(conf));
		this.switchElement = document.getElementById('dayNightSwitch')! as HTMLDivElement;

		this.init();
	}

	private init() {
		this.switchElement.addEventListener('pointerdown', () => {
			this.experience.engine.audio.items.button.stop();
			this.experience.engine.audio.items.button.play();

			this.toggleMode();
		});

		this.experience.cameraSpots.on(CAMERA_SPOTS_EVENTS.INTRO_STARTED, () => {
			this.shouldCrossfade = true;
		});

		this.experience.on('ready', () => {
			if (!isDayTime()) {
				this.toggleMode();
			}
		});
	}

	private isNight() {
		return this.mode === MODE.NIGHT;
	}

	private getNextMode(): MODE {
		return this.isNight() ? MODE.DAY : MODE.NIGHT;
	}

	private toggleMode() {
		this.mode = this.getNextMode();

		if (this.isNight()) {
			this.switchElement.classList.remove('active');
			this.switchToDay();
		} else {
			this.switchElement.classList.add('active');
			this.switchToNight();
		}
	}

	private applyConfig(conf: typeof nightConfig) {
		this.experience.engine.emit('global:config:changed', new CustomEvent(
			'global:config:changed',
			{
				detail: {
					config: conf,
					mode: this.mode === MODE.NIGHT ? MODE.DAY : MODE.NIGHT,
				},
			},
		));
	}

	private switchToDay() {
		this.applyConfig(this.initialConf);

		if (!this.shouldCrossfade) {
			return;
		}

		this.experience.engine.audio.crossfade(
			this.experience.engine.audio.items.ambientNightAudio,
			this.experience.engine.audio.items.ambientAudio,
		);

		this.experience.engine.audio.crossfade(
			this.experience.engine.audio.items.ambientNightMusic,
			this.experience.engine.audio.items.ambientMusic,
		);
	}

	private switchToNight() {
		this.applyConfig(nightConfig);

		if (!this.shouldCrossfade) {
			return;
		}

		this.experience.engine.audio.crossfade(
			this.experience.engine.audio.items.ambientAudio,
			this.experience.engine.audio.items.ambientNightAudio,
		);

		this.experience.engine.audio.crossfade(
			this.experience.engine.audio.items.ambientMusic,
			this.experience.engine.audio.items.ambientNightMusic,
		);
	}

	public isDay() {
		// A bit silly, but the current mode is expected to be the one that we will toggle
		// when we click on the switch...
		return this.getNextMode() === MODE.DAY;
	}
}
