import Experience from "../Experience.js";
import LoadingScreen from "./LoadingScreen.js";
import SoundIcon from "./SoundIcon.js";
import MainMenu from "./MainMenu.js";
import ContactSection from "./ContactSection.js";
import ViewPoints, { EVENTS as VIEW_POINT_EVENTS } from "./ViewPoints.js";
import DayTimeSwitch from "./DayTimeSwitch.js";
import HomeSection from "./HomeSection.js";

export default class Ui {
	private readonly experience: Experience;

	constructor(experience: Experience){
		this.experience = experience;

		this.init();
	}

	private init() {
		const dayTimeSwitch = new DayTimeSwitch(this.experience);
		const loading = new LoadingScreen(this.experience, dayTimeSwitch);

		new SoundIcon(this.experience, loading);
		new ContactSection(this.experience);
		const homeSection = new HomeSection(this.experience);
		const mainMenu = new MainMenu(this.experience);
		const viewPoint = new ViewPoints(
			this.experience,
			homeSection,
			mainMenu,
		);

		// @ts-ignore
		viewPoint.on(VIEW_POINT_EVENTS.REACHED, ({ detail: { point } }) => {
			if (point === 'contact') {
				mainMenu.display('contact');
			}
		});

		document.getElementById('about')!.addEventListener('touchmove', (e) => {
			e.stopPropagation();
		}, { passive: false });

		const wasAlreadyInstalled = Boolean(navigator.serviceWorker.controller);

		navigator.serviceWorker.addEventListener('controllerchange', () => {
			if (!wasAlreadyInstalled) return;

			const updateContainer = document.querySelector('.update')! as HTMLDivElement;
			const countDown = updateContainer.querySelector('.countdown')! as HTMLSpanElement;

			updateContainer.classList.remove('hidden');
			updateContainer.querySelector('button')?.addEventListener('pointerdown', () => {
				window.location.reload();
			});

			let counter = 30;
			const interval = setInterval(() => {
				counter--;
				countDown.textContent = String(counter);

				if (counter <= 0) {
					clearInterval(interval);
					window.location.reload();
				}
			}, 1000);
		});
	}
}