import * as THREE from 'three';
import gsap from 'gsap';
import Engine from "../../../lib/core/Engine.js";
import {mergeGeometries} from "three/examples/jsm/utils/BufferGeometryUtils.js";
import {MeshSurfaceSampler} from "three/examples/jsm/math/MeshSurfaceSampler.js";

import initializeVertexShader from './shaders/initialize/vertex.glsl';
import initializeFragmentShader from './shaders/initialize/fragment.glsl';

import updateVertexShader from './shaders/update/vertex.glsl';
import updateFragmentShader from './shaders/update/fragment.glsl';

import drawVertexShader from './shaders/draw/vertex.glsl';
import drawFragmentShader from './shaders/draw/fragment.glsl';
import Random from "../../../lib/utils/Random.js";
import {RAYCASTER_EVENTS} from "../../../lib/core/Raycaster.js";
import EventEmitter from "../../../lib/utils/EventEmitter.js";
import Light from "../../../Light.js";
import Resources from "../../../lib/core/Resources.js";
import sources from "../../../config/resources.config.js";
import {ExperienceAudioItems} from "../../../AudioItems.js";
import {MODE} from "../../../ui/DayTimeSwitch.js";
import {AudioUserData} from "../../../lib/core/Audio.js";

type SwarmParams = {
	engine    : Engine<ExperienceAudioItems>,
	resources : Resources<typeof sources>;
	light     : Light,
	islands   : THREE.Group,
	initialTweaks: TweakValues,
}

type TweakValues = {
	explosivness: number,
	lightColor: string,
	baseColor: string,
	count: number,
	particlesSize: number,
};

export enum SWARM_EVENTS {
	EXPLODE = 'swarm:explode',
	EXPLODED = 'swarm:exploded',
	EXPLOSIVENESS_CHANGE = 'swarm:explosivness:change',
	MORPHING = 'swarm:morphing',
}

function powerCurve(x: number, leftPower = 2, rightPower = 0.5) {
	if (x < 1) {
		const t = Math.min(Math.abs(x) / 100, 1);
		return 60 * (1 - Math.pow(t, leftPower));
	} else {
		const t = Math.min(x / 800, 1);
		return 60 * (1 - Math.pow(t, rightPower));
	}
}

type MeshesDataTextures = {
	positions: THREE.DataTexture,
	normals: THREE.DataTexture,
}

let alreadyScaled = false;

export default class Swarm extends EventEmitter {
	private readonly engine : Engine<ExperienceAudioItems>;
	private readonly light  : Light;
	private readonly group  : THREE.Group;
	private readonly tweakValues: TweakValues;
	private readonly resources: Resources<typeof sources>;

	private static readonly MIN_VALUE = -1000;
	private static readonly MAX_VALUE = 800;
	private static readonly RANGE = Swarm.MAX_VALUE - Swarm.MIN_VALUE;
	private readonly socialMediaTextures : {
		x: MeshesDataTextures,
		linkedin: MeshesDataTextures,
		youtube: MeshesDataTextures,
	};

	private initialized: boolean = false;
	private positionsDataTexture! : THREE.DataTexture;
	private normalsDataTexture!   : THREE.DataTexture;
	private particleBuffers!      : THREE.WebGLRenderTarget[];
	private particleBufferIndex!  : number;

	private fullscreenCamera! : THREE.OrthographicCamera;
	private fullscreenScene!  : THREE.Scene;
	private fullscreenQuad!   : THREE.Mesh;

	private initMaterial!   : THREE.ShaderMaterial;
	private updateMaterial! : THREE.ShaderMaterial;
	private drawMaterial!   : THREE.ShaderMaterial;

	private mesh! : THREE.Points;

	private raycasterSimplifiedMesh! : THREE.Mesh;
	private baseGeometry!        : THREE.BufferGeometry;
	private pointLight!          : THREE.PointLight;
	private displaysDefaultSwarm : boolean;
	private pendingExplosion     : boolean;
	private mysteriousAmbience!   : THREE.PositionalAudio;
	private shape: 'default' | 'x' | 'linkedin' | 'youtube';

	private currentDayTime: MODE;

	constructor(
		{
			light,
			engine,
			islands,
			resources,
			initialTweaks,
		}: SwarmParams
	) {
		super();

		this.light = light;
		this.engine = engine;
		this.group  = islands;
		this.shape = 'default';
		this.resources = resources;
		this.tweakValues = initialTweaks;
		this.displaysDefaultSwarm = true;
		this.pendingExplosion = false;
		this.currentDayTime = MODE.DAY;
		this.socialMediaTextures = {} as typeof this.socialMediaTextures;

		this.init();
		this.configureTweaks();

		this.engine.on('global:config:changed', (event) => {
			this.currentDayTime = event?.detail?.mode ?? MODE.DAY;
		});
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Islands.Swarm',
				buttons: {
					default: this.displayDefault.bind(this),
					x: this.displayX.bind(this),
					linkedIn: this.displayLinkedIn.bind(this),
					youtube: this.displayYoutube.bind(this),
				},
				lightColor: {
					onChange: (value: string) => {
						this.setColor(value);
					},
				},
				baseColor: {
					onChange: (value: string) => {
						this.setBaseColor(value);
					},
				},
				explosivness: {
					params: {
						min: -800,
						max: 800,
						step: 5,
					},
					onChange: (value: number) => {
						this.setExplosivness(value);
					}
				}
			},
		);
	}

	private morphed(to: 'default' | 'x' | 'linkedin' | 'youtube') {
		if (this.shape !== to) {
			const event = new CustomEvent(SWARM_EVENTS.MORPHING, {
				detail: {
					from: this.shape,
					to: to,
				},
			});

			this.emit(SWARM_EVENTS.MORPHING, event);
			this.engine.eventBus.dispatch('window', SWARM_EVENTS.MORPHING, event);

			this.shape = to;
		}
	}

	public displayDefault() {
		this.morphed('default');

		this.updateMaterial.uniforms.uDataTexture.value = this.positionsDataTexture;
		this.drawMaterial.uniforms.uNormalsTexture.value = this.normalsDataTexture;
		this.setExplosivness(this.tweakValues.explosivness);
		this.setBaseColor(this.tweakValues.baseColor);
		this.displaysDefaultSwarm = true;
		this.engine.audio.items.swap.stop();
		this.engine.audio.items.swap.play();
	}

	public displayX() {
		this.morphed('x');

		this.updateMaterial.uniforms.uDataTexture.value = this.socialMediaTextures.x.positions;
		this.drawMaterial.uniforms.uNormalsTexture.value = this.socialMediaTextures.x.normals;
		this.setExplosivness(1000);
		this.setBaseColor('#323232');
		this.displaysDefaultSwarm = false;
		this.engine.audio.items.swap.stop();
		this.engine.audio.items.swap.play();
	}

	public displayLinkedIn() {
		this.morphed('linkedin');

		this.updateMaterial.uniforms.uDataTexture.value = this.socialMediaTextures.linkedin.positions;
		this.drawMaterial.uniforms.uNormalsTexture.value = this.socialMediaTextures.linkedin.normals;
		this.setExplosivness(1000);
		this.setBaseColor('#29438f');
		this.displaysDefaultSwarm = false;
		this.engine.audio.items.swap.stop();
		this.engine.audio.items.swap.play();
	}

	public displayYoutube() {
		this.morphed('youtube');

		this.updateMaterial.uniforms.uDataTexture.value = this.socialMediaTextures.youtube.positions;
		this.drawMaterial.uniforms.uNormalsTexture.value = this.socialMediaTextures.youtube.normals;
		this.setExplosivness(1000);
		this.setBaseColor('#b11515');
		this.displaysDefaultSwarm = false;
		this.engine.audio.items.swap.stop();
		this.engine.audio.items.swap.play();
	}

	private normalizeExplosiveness(value: number): number {
		const v = Math.min(Math.max(value, Swarm.MIN_VALUE), Swarm.MAX_VALUE);
		// -1000 → 1 (most explosive), 800 → 0 (calmest)
		return (Swarm.MAX_VALUE - v) / Swarm.RANGE;
	}

	public get normalizedExplosiveness(): number {
		return this.normalizeExplosiveness(this.tweakValues.explosivness);
	}

	private setExplosivness(value: number, { updateLight = true } = {}) {
		const oldValue = this.updateMaterial.uniforms.uExplosivness.value;
		this.updateMaterial.uniforms.uExplosivness.value = value;

		if (updateLight) {
			this.pointLight.intensity = powerCurve(value);
		}

		if (value === oldValue) return;

		const normalized = this.normalizeExplosiveness(value);

		this.emit(SWARM_EVENTS.EXPLOSIVENESS_CHANGE, new CustomEvent(SWARM_EVENTS.EXPLOSIVENESS_CHANGE, {
			detail: {
				swarm: this,
				value,
				normalized,
			}
		}));
	}

	private setColor(value: string) {
		this.drawMaterial.uniforms.uVelocityColor.value = new THREE.Color(value);
		this.pointLight.color = new THREE.Color(value);
	}

	private setBaseColor(value: string) {
		this.drawMaterial.uniforms.uBaseColor.value = new THREE.Color(value);
	}

	private init() {
		this.initGeometry();
		this.initFullscreenRenderer();

		const {
			positions,
			dataPositions,
			dataNormals,
		} = this.sample();

		this.initDataTexture(dataPositions, dataNormals);
		this.initSocialDataTextures();
		this.initParticleBuffers();
		this.initUpdateMaterial();
		this.initDrawMaterial();

		this.initParticles(positions);

		this.resources.once('loaded:soundMysteriousAmbience', () => {
			this.mysteriousAmbience = this.engine.audio.createPositionalAudio(
				'mysteriousMusic',
				this.resources.items.soundMysteriousAmbience,
				{
					volume: 0.5,
					loop: true,
				}
			);

			this.mysteriousAmbience.position.copy(this.mesh.position);

			this.mysteriousAmbience.setRefDistance(2.5);
			this.mysteriousAmbience.setMaxDistance(4);
			this.mysteriousAmbience.setRolloffFactor(3);
			this.mysteriousAmbience.play();

			this.group.add(this.mysteriousAmbience);
		});

		this.resources.once('loaded:soundExplosion', () => {
			this.engine.audio.createAmbientAudio(
				'explosion',
				this.resources.items.soundExplosion,
				{
					volume: 0.5,
					loop: false,
				}
			);
		});

		this.resources.once('loaded:soundSwap', () => {
			this.engine.audio.createAmbientAudio(
				'swap',
				this.resources.items.soundSwap,
				{
					volume: 0.5,
					loop: false,
				}
			);
		});
	}

	private initSocialDataTextures() {
		const meshes: THREE.Mesh[] = [];
		const NUM_PARTICLES = this.tweakValues.count;

		this.group.traverse((obj) => {
			if (!obj.name.startsWith('social-media')) return;
			if (!(obj instanceof THREE.Mesh)) return;

			meshes.push(obj as THREE.Mesh);

			if (!alreadyScaled) {
				obj.geometry.scale(11,11,11);
			}
		});

		alreadyScaled = true;

		const position = new THREE.Vector3();
		const normal = new THREE.Vector3();
		meshes.forEach((mesh) => {
			const sampler = new MeshSurfaceSampler(mesh).build();
			const data = new Float32Array(NUM_PARTICLES * NUM_PARTICLES * 4);
			const normals = new Float32Array(NUM_PARTICLES * NUM_PARTICLES * 4);

			for (let i = 0; i < NUM_PARTICLES * NUM_PARTICLES; i++) {
				sampler.sample(position, normal);

				const i4 = i * 4;
				data[i4 + 0] = position.x;
				data[i4 + 1] = position.y;
				data[i4 + 2] = position.z;
				data[i4 + 3] = 1.0;

				normals[i4 + 0] = normal.x;
				normals[i4 + 1] = normal.y;
				normals[i4 + 2] = normal.z;
				normals[i4 + 3] = 1.0;
			}

			const positionsTexture = new THREE.DataTexture(data, NUM_PARTICLES, NUM_PARTICLES);
			positionsTexture.format = THREE.RGBAFormat;
			positionsTexture.type = THREE.FloatType;
			positionsTexture.needsUpdate = true;

			const normalsTexture = new THREE.DataTexture(normals, NUM_PARTICLES, NUM_PARTICLES);
			normalsTexture.format = THREE.RGBAFormat;
			normalsTexture.type = THREE.FloatType;
			normalsTexture.needsUpdate = true;

			this.socialMediaTextures[
				mesh.name.replace('social-media-','') as keyof typeof this.socialMediaTextures
			] = {
				positions: positionsTexture,
				normals: normalsTexture,
			};
		});
	}

	private initGeometry() {
		const geometries: THREE.BufferGeometry[] = [];
		const ONION_RADIUS = 0.4;
		const ONION_LAYERS_COUNT = 8;
		const ONION_LAYER_OFFSET = -0.1;

		let currentLayerRadius = ONION_RADIUS;
		for(let i = 0; i < ONION_LAYERS_COUNT; i++) {
			const layerGeometry = new THREE.SphereGeometry(currentLayerRadius, 16, 16);
			currentLayerRadius += ONION_LAYER_OFFSET;
			geometries.push(layerGeometry);
		}

		this.baseGeometry = mergeGeometries(geometries, false);
		geometries.forEach((geometry) => geometry.dispose());

		this.raycasterSimplifiedMesh = new THREE.Mesh(
			new THREE.SphereGeometry(ONION_RADIUS * 2.0, 4, 4),
			new THREE.MeshBasicMaterial({
				color: 0xffffff,
				transparent: true,
				opacity: 0.0,
				depthWrite: false,
				depthTest: false,
				colorWrite: false,
			}),
		);

		this.group.add(this.raycasterSimplifiedMesh);
	}

	private sample() {
		const NUM_PARTICLES = this.tweakValues.count;

		const positions = new Float32Array(NUM_PARTICLES * NUM_PARTICLES * 3);
		const dataPositions = new Float32Array(NUM_PARTICLES * NUM_PARTICLES * 4);
		const dataNormals = new Float32Array(NUM_PARTICLES * NUM_PARTICLES * 4);
		const samplingMesh = new THREE.Mesh(this.baseGeometry);

		const sampler = new MeshSurfaceSampler(samplingMesh).build();
		const position = new THREE.Vector3();
		const normal = new THREE.Vector3();

		for (let i = 0; i < NUM_PARTICLES * NUM_PARTICLES; i++) {
			sampler.sample(position, normal);

			const i3 = i * 3;
			positions[i3 + 0] = position.x;
			positions[i3 + 1] = position.y;
			positions[i3 + 2] = position.z;

			const i4 = i * 4;
			dataPositions[i4 + 0] = position.x;
			dataPositions[i4 + 1] = position.y;
			dataPositions[i4 + 2] = position.z;
			dataPositions[i4 + 3] = 1.0;

			dataNormals[i4 + 0] = normal.x;
			dataNormals[i4 + 1] = normal.y;
			dataNormals[i4 + 2] = normal.z;
			dataNormals[i4 + 3] = 1.0;
		}

		return {
			positions,
			dataPositions,
			dataNormals,
		};
	}

	private initDataTexture(dataPositions: Float32Array, dataNormals: Float32Array) {
		const NUM_PARTICLES = this.tweakValues.count;

		const dataPositionsTexture = new THREE.DataTexture(dataPositions, NUM_PARTICLES, NUM_PARTICLES);
		dataPositionsTexture.format = THREE.RGBAFormat;
		dataPositionsTexture.type = THREE.FloatType;
		dataPositionsTexture.needsUpdate = true;

		this.positionsDataTexture = dataPositionsTexture;

		const dataNormalsTexture = new THREE.DataTexture(dataNormals, NUM_PARTICLES, NUM_PARTICLES);
		dataNormalsTexture.format = THREE.RGBAFormat;
		dataNormalsTexture.type = THREE.FloatType;
		dataNormalsTexture.needsUpdate = true;

		this.normalsDataTexture = dataNormalsTexture;
	}

	private initParticles(positions: Float32Array) {
		this.mesh = this.createParticles(positions);

		this.group.add(this.mesh);

		if (this.mysteriousAmbience) {
			this.mysteriousAmbience.position.copy(this.mesh.position);
		}
	}

	private initFullscreenRenderer() {
		this.initFullscreenCamera();
		this.initFullscreenScene();
		this.initFullscreenQuad();
	}

	private initFullscreenCamera() {
		this.fullscreenCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
	}

	private initFullscreenScene() {
		this.fullscreenScene = new THREE.Scene();
	}

	private initFullscreenQuad() {
		const geometry = new THREE.PlaneGeometry(2, 2);
		const material = new THREE.MeshBasicMaterial();
		this.fullscreenQuad = new THREE.Mesh(geometry, material);
		this.fullscreenScene.add(this.fullscreenQuad);
	}

	private renderBuffer(buffer: THREE.WebGLRenderTarget) {
		this.engine.renderer.instance.setRenderTarget(buffer);
		this.engine.renderer.instance.render(
			this.fullscreenScene,
			this.fullscreenCamera);
		this.engine.renderer.instance.setRenderTarget(null);
	}

	private initParticleBuffers() {
		const NUM_PARTICLES = this.tweakValues.count;

		const opts = {
			minFilter: THREE.NearestFilter,
			magFilter: THREE.NearestFilter,
			format: THREE.RGBAFormat,
			type: THREE.FloatType,
		};

		this.particleBuffers = [
			new THREE.WebGLRenderTarget(NUM_PARTICLES, NUM_PARTICLES, opts),
			new THREE.WebGLRenderTarget(NUM_PARTICLES, NUM_PARTICLES, opts),
			new THREE.WebGLRenderTarget(NUM_PARTICLES, NUM_PARTICLES, opts),
		];

		this.initMaterial = new THREE.ShaderMaterial({
			uniforms: {
				uDataTexture: new THREE.Uniform(this.positionsDataTexture),
			},
			vertexShader: initializeVertexShader,
			fragmentShader: initializeFragmentShader,
			depthWrite: false,
			depthTest: false,
		});

		this.fullscreenQuad.material = this.initMaterial;

		this.particleBufferIndex = 0;
		this.particleBuffers.forEach((buffer, i) => {
			this.renderBuffer(buffer);
		});
	}

	private initUpdateMaterial() {
		this.updateMaterial = new THREE.ShaderMaterial({
			uniforms: {
				uDataTexture: new THREE.Uniform(this.positionsDataTexture),
				currentBuffer: new THREE.Uniform(null),
				previousBuffer: new THREE.Uniform(null),
				timeElapsed: new THREE.Uniform(0),
				time: new THREE.Uniform(0),
				uExplosivness: new THREE.Uniform(this.tweakValues.explosivness),
			},
			fragmentShader: updateFragmentShader,
			vertexShader: updateVertexShader,
			depthWrite: false,
			depthTest: false,
		});

		this.fullscreenQuad.material = this.updateMaterial;
		this.initialized = true;
	}

	private initDrawMaterial() {
		const NUM_PARTICLES = this.tweakValues.count;

		this.drawMaterial = new THREE.ShaderMaterial({
			lights: true,
			uniforms: {
				uDataTexture: new THREE.Uniform(this.particleBuffers[0].texture),
				uNormalsTexture: new THREE.Uniform(this.normalsDataTexture),
				uLightColor: new THREE.Uniform(this.light.mainLightColor),
				uResolution: new THREE.Uniform(new THREE.Vector2(NUM_PARTICLES, NUM_PARTICLES)),
				uCurrentBuffer: new THREE.Uniform(null),
				uPreviousBuffer: new THREE.Uniform(null),
				uVelocityColor: new THREE.Uniform(new THREE.Color(this.tweakValues.lightColor)),
				uBaseColor: new THREE.Uniform(new THREE.Color(this.tweakValues.baseColor)),
				uTime: new THREE.Uniform(0),
				uSize: new THREE.Uniform(this.tweakValues.particlesSize),
				uScreenResolution: new THREE.Uniform(new THREE.Vector2(...this.engine.sizes.resolution)),
				...THREE.UniformsLib.lights,
			},
			vertexShader: drawVertexShader,
			fragmentShader: drawFragmentShader,
			// blending: THREE.AdditiveBlending,
			transparent: true,
		});
	}

	private createParticles(positions: Float32Array) {
		const NUM_PARTICLES = this.tweakValues.count;

		const pointsGeometry = new THREE.BufferGeometry();
		const indices: number[] = [];
		const sizes: number[] = [];

		for (let i = 0; i < NUM_PARTICLES * NUM_PARTICLES; i++) {
			indices.push(i);
			sizes.push(Random.between(0.1, 1));
		}

		pointsGeometry.setAttribute('aIndex', new THREE.Float32BufferAttribute(indices, 1));
		pointsGeometry.setAttribute('aSize', new THREE.Float32BufferAttribute(sizes, 1));
		pointsGeometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));

		const points = new THREE.Points(pointsGeometry, this.drawMaterial);
		// @ts-ignore
		points.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1);
		// @ts-ignore
		points.boundingBox = null;

		points.scale.set(0.1, 0.1, 0.1);

		this.group.traverse((child) => {
			if (child.name === 'explosive-particles') {
				points.position.copy(child.position);
				points.scale.setScalar(
					(child.scale.x + child.scale.y + child.scale.z) / 3
				);

				const light = new THREE.PointLight('#58e0ff', 10, 5);
				light.position.copy(child.position);
				this.group.add(light);

				this.pointLight = light;

				this.setExplosivness(this.tweakValues.explosivness);
			}
		});

		this.raycasterSimplifiedMesh.position.copy(points.position);
		this.raycasterSimplifiedMesh.scale.copy(points.scale);
		this.raycasterSimplifiedMesh.scale.multiplyScalar(1.2);

		this.engine.raycaster.on(RAYCASTER_EVENTS.POINTER_IN, this.raycasterSimplifiedMesh, () => {
			this.engine.changeCursor('pointer');
		});

		this.engine.raycaster.on(RAYCASTER_EVENTS.POINTER_OUT, this.raycasterSimplifiedMesh, () => {
			this.engine.changeCursor('default');
		});

		this.engine.raycaster.on(RAYCASTER_EVENTS.POINTER_DOWN, this.raycasterSimplifiedMesh, () => {
			this.explode();
		});

		points.geometry.computeBoundingBox();

		return points;
	}

	private explode() {
		if (this.pendingExplosion) return;
		this.pendingExplosion = true;

		const originalExplosivness = this.tweakValues.explosivness;

		const tl = gsap.timeline({
			onComplete: () => {
				// Explosion cooldown
				setTimeout(() => {
					this.pendingExplosion = false;
				}, 2000);
			}
		});

		const animatedValue = {
			value: originalExplosivness,
		};

		const event = new CustomEvent(SWARM_EVENTS.EXPLODE, {
			detail: { shape: this.shape },
		});
		const eventAfter = new CustomEvent(SWARM_EVENTS.EXPLODED, {
			detail: { shape: this.shape },
		});

		tl.to(animatedValue, {
			value: -500,
			duration: 0.01,
			ease: "expo.out",
			onUpdate: () => {
				this.setExplosivness(animatedValue.value);
			}
		});

		if (this.displaysDefaultSwarm) {
			tl.to(animatedValue, {
				value: originalExplosivness,
				duration: 0.3,
				delay: 0.15,
				ease: "expo.in",
				onUpdate: () => {
					this.setExplosivness(animatedValue.value);
				},
				onStart: () => {
					this.engine.audio.items.explosion.stop();
					this.engine.audio.items.explosion.play();
					this.engine.camera.shake();
				},
				onComplete: () => {
					this.emit(SWARM_EVENTS.EXPLODED, eventAfter);
					this.engine.eventBus.dispatch('window', SWARM_EVENTS.EXPLODED, eventAfter);
				},
			});
		} else {
			tl.to(animatedValue, {
				value: 1000,
				duration: 1.0,
				delay: 0.15,
				ease: "expo.in",
				onUpdate: () => {
					this.setExplosivness(animatedValue.value, { updateLight: false });
				},
				onStart: () => {
					this.engine.audio.items.explosion.stop();
					this.engine.audio.items.explosion.play();
					this.engine.camera.shake();
				},
				onComplete: () => {
					this.emit(SWARM_EVENTS.EXPLODED, eventAfter);
					this.engine.eventBus.dispatch('window', SWARM_EVENTS.EXPLODED, eventAfter);
				},
			});
		}

		this.emit(SWARM_EVENTS.EXPLODE, event);
		this.engine.eventBus.dispatch('window', SWARM_EVENTS.EXPLODE, event);
	}

	private readonly frustum = new THREE.Frustum();
	private readonly projectScreenMatrix = new THREE.Matrix4();
	private readonly boundingBox = new THREE.Box3();

	private isFarFromCamera(threshold: number = 6) {
		return this.engine.camera.instance
			.getWorldPosition(
				new THREE.Vector3()
			).distanceTo(
				this.mesh.getWorldPosition(new THREE.Vector3())
			) > threshold;
	}

	private isInView() {
		this.projectScreenMatrix.multiplyMatrices(
			this.engine.camera.instance.projectionMatrix,
			this.engine.camera.instance.matrixWorldInverse
		);
		this.frustum.setFromProjectionMatrix(this.projectScreenMatrix);

		this.boundingBox.copy(this.mesh.geometry.boundingBox!).applyMatrix4(
			this.mesh.matrixWorld,
		);
		return this.frustum.intersectsBox(this.boundingBox);
	}

	private isCameraHighEnough() {
		return this.engine.camera.instance.position.y > 4.5;
	}

	private shouldUpdate(): boolean {
		const cameraIsHighEnough = this.isCameraHighEnough();
		if (!cameraIsHighEnough) {
			return false;
		}

		const isVeryFarFromCamera = this.isFarFromCamera(10);
		if (isVeryFarFromCamera) {
			return false;
		}

		const meshIsInView = this.isInView();

		if (!meshIsInView) {
			return false;
		}

		const meshIsFarFromCamera = this.isFarFromCamera();

		if (meshIsFarFromCamera && cameraIsHighEnough) {
			return true;
		}

		return !meshIsFarFromCamera;
	}

	update() {
		if (!this.initialized) return;

		this.syncAmbientMusic();

		if (!this.shouldUpdate()) {
			return;
		}

		const deltaTime = this.engine.time.deltaSeconds;
		const timeElapsed = this.engine.time.elapsedSeconds;

		const currentBufferIndex = this.particleBufferIndex;
		const previousBufferIndex = (this.particleBufferIndex + 2) % 3;
		const nextBufferIndex = (this.particleBufferIndex + 1) % 3;

		const currentBuffer = this.particleBuffers[currentBufferIndex];
		const previousBuffer = this.particleBuffers[previousBufferIndex];
		this.particleBufferIndex = nextBufferIndex;

		this.updateMaterial.uniforms.currentBuffer.value = currentBuffer.texture;
		this.updateMaterial.uniforms.previousBuffer.value = previousBuffer.texture;
		this.updateMaterial.uniforms.timeElapsed.value = deltaTime;
		this.updateMaterial.uniforms.time.value = timeElapsed;
		this.updateMaterial.needsUpdate = true;

		this.drawMaterial.uniforms.uCurrentBuffer.value = currentBuffer.texture;
		this.drawMaterial.uniforms.uPreviousBuffer.value = previousBuffer.texture;
		this.drawMaterial.uniforms.uTime.value = timeElapsed;
		this.drawMaterial.needsUpdate = true;

		this.renderBuffer(this.particleBuffers[this.particleBufferIndex]);
		this.drawMaterial.uniforms.uDataTexture.value = this.particleBuffers[this.particleBufferIndex].texture;

		this.mesh.rotation.y += 0.01;
	}

	private getCurrentAmbientMusic() {
		if (this.currentDayTime === MODE.NIGHT) {
			return this.engine.audio.items.ambientNightMusic;
		}

		return this.engine.audio.items.ambientMusic;
	}

	private syncAmbientMusic() {
		if (!this.engine.audio.items.ambientMusic) return;

		const ambientMusic = this.getCurrentAmbientMusic();
		const data = ambientMusic.userData as AudioUserData;

		if (data.initialVolume === undefined) {
			data.initialVolume = ambientMusic.getVolume();
		}

		const listenerWorldPos = new THREE.Vector3();
		this.engine.audio.listener.getWorldPosition(listenerWorldPos);

		const distance = listenerWorldPos.distanceTo(
			this.mesh.getWorldPosition(new THREE.Vector3())
		);

		let factor: number;

		if (distance <= 4) {
			factor = 0;
		} else if (distance >= 8) {
			factor = 1;
		} else {
			factor = (distance - 4) / (8 - 4);
		}

		data.spatialFactor = factor;
	}

	destroy() {
		this.baseGeometry.dispose();
		this.pointLight.dispose();
		this.mesh.geometry.dispose();

		this.initMaterial.dispose();
		this.updateMaterial.dispose();
		this.drawMaterial.dispose();

		this.positionsDataTexture.dispose();
		this.normalsDataTexture.dispose();
		this.particleBuffers.forEach((buffer) => {
			buffer.dispose();
		});

		this.fullscreenQuad.geometry.dispose();

		this.raycasterSimplifiedMesh.geometry.dispose();
		(
			this.raycasterSimplifiedMesh.material as THREE.MeshBasicMaterial
		).dispose();
		this.group.remove(this.raycasterSimplifiedMesh);
		this.group.remove(this.mesh);

		this.engine.raycaster.remove(this.raycasterSimplifiedMesh);
	}
}