import * as THREE from 'three';
import Engine from "../../../lib/core/Engine.js";
import fragmentShader from './shaders/fragment.glsl';
import vertexShader from './shaders/vertex.glsl';
import Foam from "./foam/Foam.js";
import WaterDrops from "./particles/WaterDrops.js";
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import config from "../../../config/Conf.js";
import ShaderBaker from "../../../lib/utils/baker/ShaderBaker.js";
import bakingVertexShader from '../../../scenes/islands/waterfalls/shaders/baking.vertex.glsl';

type TweaksValue = {
	topColor: string,
	midColor: string,
	baseColor: string,
};

type WaterfallParams = {
	group  : THREE.Group
	engine : Engine,
	resources: Resources<typeof sources>,
	initialTweaks: TweaksValue,
};

export default class Waterfalls {
	private readonly resources    : Resources<typeof sources>;
	private readonly group        : THREE.Group;
	private readonly waterfalls   : THREE.Mesh[];
	private readonly engine       : Engine;
	private readonly tweaksValue  : TweaksValue;

	private foam!     : Foam;
	private waterDrops!: WaterDrops;
	private material! : THREE.ShaderMaterial;
	private soundAnchorPoints : THREE.Object3D[];
	private bakedShaders: ShaderBaker[];

	constructor(
		{
			group,
			engine,
			resources,
			initialTweaks,
		}: WaterfallParams
	) {
		this.engine = engine;
		this.group = group;
		this.waterfalls = [];
		this.resources = resources;
		this.soundAnchorPoints = [];
		this.tweaksValue = initialTweaks;
		this.bakedShaders = [];

		this.init();
		this.configureTweaks();

		this.engine.on(
			'global:config:changed',
			(event) => {
				const conf = event?.detail?.config;
				if (!conf) return;

				this.configChanged(conf);
			}
		);
	}

	private configChanged(conf: typeof config) {
		if (conf.islands.waterfalls) {
			this.updateMidColor(conf.islands.waterfalls.midColor);
			this.updateTopColor(conf.islands.waterfalls.topColor);
			this.updateBaseColor(conf.islands.waterfalls.baseColor);
		}
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweaksValue,
			{
				folder: 'Islands.Waterfalls',
				topColor: {
					onChange: this.updateTopColor.bind(this),
				},
				midColor: {
					onChange: this.updateMidColor.bind(this),
				},
				baseColor: {
					onChange: this.updateBaseColor.bind(this),
				},
			},
		);
	}

	private updateTopColor(color: string) {
		this.material.uniforms.uTopColor.value = new THREE.Color(color);
	}

	private updateMidColor(color: string) {
		this.material.uniforms.uMidColor.value = new THREE.Color(color);
	}

	private updateBaseColor(color: string) {
		this.material.uniforms.uBaseColor.value = new THREE.Color(color);
	}

	private init() {
		this.extractMeshes();
		this.createMaterial();
		this.applyMaterialToMeshes();

		this.initFoam();
		this.initWaterDrops();

		this.resources.once('loaded:soundWaterfall', () => {
			this.soundAnchorPoints.forEach((anchorPoint, i) => {
				const audio = this.engine.audio.createPositionalAudio(
					`waterfall-${i}`,
					this.resources.items.soundWaterfall,
					{
						volume: 0.5,
						loop: true,
					}
				);

				audio.position.copy(anchorPoint.position);
				audio.setRefDistance(3);
				audio.setRolloffFactor(2);
				audio.setMaxDistance(5.5);

				this.group.add(audio);
			});
		});

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;
			if (!declineLevel) return;

			switch(declineLevel) {
				case 4:
					console.warn('Waterfalls: Low fps detected. Baking shaders...');
					this.bakeShaders();
					break;
				case 5:
					console.warn('Waterfalls: Low fps detected. Deleting water drops.');
					this.waterDrops.destroy();
					break;
			}
		});
	}

	private bakeShaders() {
		this.waterfalls.forEach((waterfall) => {
			const bakedShader = new ShaderBaker(
				bakingVertexShader,
				1024,
				this.engine,
				this.resources,
				waterfall,
				[
					{ uTime: 0 },
					{ uTime: 1 }
				],
			);

			try {
				const material = bakedShader.bake();
				this.bakedShaders.push(material);
				waterfall.material = material;
				console.log('Waterfalls: Shaders successfully baked for performance optimization');
			} catch (error) {
				console.error('Waterfalls: Failed to bake shaders:', error);
			}
		});
	}

	private initFoam() {
		this.foam = new Foam({
			engine: this.engine,
			group: this.group,
			initialTweaks: {
				lightPosition: {
					x: 66.55,
					y: 20.338,
					z: -68.20,
				},
				foamColor: config.islands.foam.color,
				foamShadowColor: config.islands.foam.shadow,
			}
		});
	}

	private initWaterDrops() {
		this.waterDrops = new WaterDrops({
			engine: this.engine,
			group: this.group,
			initialTweaks: {
				count: 500,
				size: 0.04,
			},
		});
	}

	private extractMeshes() {
		this.group.traverse((child) => {
			if (child.name?.startsWith('sound-waterfall')) {
				this.soundAnchorPoints.push(child as THREE.Object3D);
				return;
			}

			if (child.name?.match(/-waterfall$/)) {
				this.waterfalls.push(child as THREE.Mesh);
			}
		});
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			fragmentShader,
			vertexShader,
			fog: true,
			uniforms: {
				uTime      : new THREE.Uniform(0),
				uBaseColor : new THREE.Uniform(new THREE.Color(this.tweaksValue.baseColor)),
				uTopColor  : new THREE.Uniform(new THREE.Color(this.tweaksValue.topColor)),
				uMidColor  : new THREE.Uniform(new THREE.Color(this.tweaksValue.midColor)),
				...THREE.UniformsLib.fog
			}
		});
	}

	private applyMaterialToMeshes() {
		this.waterfalls.forEach((mesh) => {
			mesh.material = this.material;
			mesh.castShadow = true;
			mesh.receiveShadow = true;
		});
	}

	update() {
		this.foam?.update();
		this.waterDrops?.update();

		if (!this.material) {
			return;
		}

		this.material.transparent = this.engine.camera.isCloseEnough(25);

		if (this.material.uniforms.uTime) {
			this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
		}

		this.bakedShaders.forEach((shader) => {
			shader.uniforms.mixFactor.value = this.engine.time.elapsedSeconds;
		});
	}

	destroy() {
		this.foam?.destroy();
		this.waterDrops?.destroy();
		this.material?.dispose();
		this.waterfalls.forEach((mesh) => {
			mesh.geometry.dispose();
		});
	}
}