import * as THREE from 'three';
import Engine from "../../../../lib/core/Engine.js";
import fragmentShader from './shaders/fragment.glsl';
import vertexShader from './shaders/vertex.glsl';

type SparksParams = {
	engine: Engine,
	islands: THREE.Group,
	position: THREE.Vector3,
}

export default class Sparks {
	private readonly engine: Engine;
	private readonly position: THREE.Vector3;
	private readonly islands: THREE.Group;

	private material!: THREE.ShaderMaterial;
	private mesh!: THREE.Points;

	constructor(
		{
			engine,
			islands,
			position,
		}: SparksParams
	) {
		this.engine = engine;
		this.islands = islands;
		this.position = position;

		this.init();
	}

	private initMaterial() {
		this.material = new THREE.ShaderMaterial({
			vertexShader,
			fragmentShader,
			uniforms: {
				uTime: new THREE.Uniform(0),
				uColor: new THREE.Uniform(new THREE.Color('#ff0000')),
				uScale: { value: 1.0 },
				uScreenResolution: new THREE.Uniform(new THREE.Vector2(
					...this.engine.sizes.resolution,
				)),
			},
			transparent: true,
			depthWrite: false,
			blending: THREE.AdditiveBlending,
		});
	}

	private init() {
		this.initMaterial();
		this.initMesh();
	}

	private initMesh() {
		const SPARKS_COUNT = 50;
		const positions = new Float32Array(SPARKS_COUNT * 3);
		const speeds = new Float32Array(SPARKS_COUNT * 3);
		const lifetimes = new Float32Array(SPARKS_COUNT);
		const sizes = new Float32Array(SPARKS_COUNT);

		for (let i = 0; i < SPARKS_COUNT; i++) {
			positions[i * 3] = (Math.random() - 0.5) * 0.025;
			positions[i * 3 + 1] = 0.02;
			positions[i * 3 + 2] = (Math.random() - 0.5) * 0.025;

			speeds[i * 3] = (Math.random() - 0.5) * 0.5;
			speeds[i * 3 + 1] = 0.02 + Math.random() * 0.11;
			speeds[i * 3 + 2] = (Math.random() - 0.5) * 0.5;

			lifetimes[i] = Math.random() * 1.0;

			sizes[i] = Math.min(Math.random() * 0.5, 0.1);
		}

		const geometry = new THREE.BufferGeometry();
		geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
		geometry.setAttribute('aSpeed', new THREE.BufferAttribute(speeds, 3));
		geometry.setAttribute('aLifetime', new THREE.BufferAttribute(lifetimes, 1));
		geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));

		this.mesh = new THREE.Points(
			geometry,
			this.material,
		);

		this.mesh.position.copy(this.position);

		this.islands.add(this.mesh);
	}

	update() {
		if (!this.material) {
			return;
		}

		this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
	}

	destroy() {
		this.material.dispose();
		this.mesh.geometry.dispose();
		this.mesh.removeFromParent();
	}
}