import * as THREE from 'three';
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import Engine from "../../../lib/core/Engine.js";
import grassVertexShader from "./shaders/vertex.glsl";
import grassFragmentShader from "./shaders/fragment.glsl";
import Bender from "../bender/Bender.js";
import GrassChunks from "./GrassChunks.js";
import ChunkedInstancedMeshLod from "../../../lib/utils/chunked/ChunkedInstancedMeshLod.js";
import {debugBoundingBox} from "../../../lib/dev/debug/TheoreticalObjectDisplay.js";

type TweakValues = {
	count         : number,
	height        : number,
	width         : number,
	bendingFactor : number,
	bendingColorIntensity : number,
};

type ColorParams = {
	lightColor : string,
	darkColor  : string,
}

type GrassParams = {
	engine         : Engine,
	group          : THREE.Group,
	parentGeometry : THREE.BufferGeometry,
	resources      : Resources<typeof sources>,
	grass          : ColorParams,
	dirt           : ColorParams,
	lightDirection : THREE.Vector3,
	shadowColor    : string,
	initialTweaks  : TweakValues,
	bender         : Bender,
}

type Geometries = {
	high   : THREE.BufferGeometry,
	medium : THREE.BufferGeometry,
	low    : THREE.BufferGeometry,
}

export default class Grass{
	private readonly engine         : Engine;
	private readonly group          : THREE.Group;
	private readonly resources      : Resources<typeof sources>;
	private readonly parentGeometry : THREE.BufferGeometry;
	private readonly tweakValues    : TweakValues;
	private readonly bender         : Bender;
	private readonly initParams     : Pick<GrassParams, 'dirt' | 'grass' | 'lightDirection' | 'shadowColor'>;
	private readonly grassGeometries! : Geometries;

	private material!        : THREE.ShaderMaterial;
	private mesh!            : THREE.InstancedMesh;
	private chunks!          : GrassChunks;

	constructor(
		{
			engine,
			group,
			bender,
			resources,
			parentGeometry,
			dirt,
			grass,
			shadowColor,
			lightDirection,
			initialTweaks,
		}: GrassParams
	) {
		this.engine          = engine;
		this.group           = group;
		this.bender          = bender;
		this.resources       = resources;
		this.parentGeometry  = parentGeometry;
		this.tweakValues     = initialTweaks;
		this.grassGeometries = {} as Geometries;
		this.initParams      = {
			dirt,
			grass,
			shadowColor,
			lightDirection,
		};

		this.init();
		this.configureTweaks();
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder : 'GrassField.Grass',
				height : {
					params : {
						min  : 2,
						max  : 15,
						step : 0.5
					},
					onChange: () => {
						if (!this.material) return;

						this.rebuild();
					}
				},
				bendingFactor : {
					params : {
						min  : 0.01,
						max  : 1,
						step : 0.01,
					},
					onChange: (value: number) => {
						if (!this.material) return;

						this.material.uniforms.uBendingFactor.value = value;
					},
				},
				bendingColorIntensity : {
					params: {
						min  : 0.01,
						max  : 1,
						step : 0.01
					},
					onChange: (value: number) => {
						if (!this.material) return;

						this.material.uniforms.uBendingColorIntensity.value = value;
					}
				},
				count : {
					params : {
						min  : 3_000,
						max  : 250_000,
						step : 1_000,
					},
					onChange: () => {
						this.rebuild();
					},
				},
			},
		);
	}

	private init() {
		this.resources.onceAll(
			[
				'loaded:grassModel',
				'loaded:grassFieldDisplacementMap',
				'loaded:grassFieldWindNoiseTexture',
				'loaded:smoothWind',
			],
			() => {
				this.initGrassGeometryFromModel();
				this.createMaterial();
				this.createChunks();

				this.engine.monitor.on('decline', (event) => {
					const declineLevel = event?.detail?.declineLevel;
					if (!declineLevel) return;

					switch (declineLevel) {
						case 2:
							console.warn('Grassfield.Grass: Low fps detected. Reducing grass count by 50%.');
							this.divideCountBy(1.5);
							break;
						case 3:
							console.warn('Grassfield.Grass: Low fps detected. Dividing grass count by 2.');
							this.divideCountBy(2);
							break;
						case 5:
							// console.warn('Grassfield.Grass: Low fps detected. Disabling grass.');
							// this.destroy();
							break;
					}
				});
			}
		);
	}

	private divideCountBy(factor: number) {
		this.chunks.divideLodCountBy(factor);
	}

	private createMaterial() {
		const {
			dirt,
			grass,
			lightDirection,
			shadowColor,
		} = this.initParams;

		this.material = new THREE.ShaderMaterial({
			vertexShader   : grassVertexShader,
			fragmentShader : grassFragmentShader,
			fog: true,
			lights: true,
			defines: {
				USE_SHADOWMAP: '',
			},
			uniforms : {
				uTime          : new THREE.Uniform(0),

				uLightGreen    : new THREE.Uniform(new THREE.Color(grass.lightColor)),
				uDarkGreen     : new THREE.Uniform(new THREE.Color(grass.darkColor)),
				uLightDirt     : new THREE.Uniform(new THREE.Color(dirt.lightColor)),
				uDarkDirt      : new THREE.Uniform(new THREE.Color(dirt.darkColor)),
				uBendingFactor : new THREE.Uniform(this.tweakValues.bendingFactor),
				uShadowColor   : new THREE.Uniform(new THREE.Color(shadowColor)),
				uLightDirection        : new THREE.Uniform(lightDirection),
				uBendingColorIntensity : new THREE.Uniform(this.tweakValues.bendingColorIntensity),

				uColorTexture     : new THREE.Uniform(this.resources.items.grassFieldWindNoiseTexture),
				uDisplacementMap  : new THREE.Uniform(this.resources.items.grassFieldDisplacementMap),
				uBendingTexture   : new THREE.Uniform(this.bender.texture),
				uWindTexture      : new THREE.Uniform(this.resources.items.smoothWind),
				...THREE.UniformsLib.fog,
				...THREE.UniformsLib.lights,
			},
			side: THREE.FrontSide,
		});

		// It seems like we have a bug in threeJs regarding material update when setting directly
		// the side: DoubleSide. Lights uniforms are not updated and are messing up everything.
		// Without this, the light is only properly set up when the camera moves far enough.
		setTimeout(() =>  {
			this.material.side = THREE.DoubleSide;
		}, 0);
	}

	private createChunks() {
		const lod = new ChunkedInstancedMeshLod();

		lod.addLevel(0, { geometry: this.grassGeometries.medium });
		lod.addLevel(7.5, { geometry: this.grassGeometries.low, count: 0.2 });
		lod.addLevel(12.5, { geometry: this.grassGeometries.low, count: 0.1 });
		lod.addLevel(17, { geometry: this.grassGeometries.low, count: 0 });

		this.chunks = new GrassChunks({
			chunkSize       : new THREE.Vector3(1.0, 2.0, 1.0),
			sampledGeometry : this.parentGeometry,
			total           : this.tweakValues.count,
			geometry        : this.grassGeometries.high,
			material        : this.material,
			lod,
		});

		this.chunks.sample();

		this.chunks.entries().forEach(([, chunk]) => {
			chunk.frustumCulled = true;
			chunk.receiveShadow = true;
			// this.group.add(debugBoundingBox(chunk.boundingBox));

			this.group.add(chunk);
		});
	}

	private initGrassGeometryFromModel() {
		this.resources.items.grassModel.scene.traverse((child) => {
			if (child instanceof THREE.Mesh) {
				const geometry = child.geometry.clone();
				geometry.scale(
					this.tweakValues.width  / 1_000,
					this.tweakValues.height / 1_000,
					this.tweakValues.width  / 1_000,
				);

				this.grassGeometries[child.name as keyof Geometries] = geometry;
			}
		});
	}

	updateShadowColor(color: string) {
		if (!this.material) return;

		this.material.uniforms.uShadowColor.value = new THREE.Color(color);
	}

	updateLightDirection(value: THREE.Vector3) {
		if (!this.material) return;

		this.material.uniforms.uLightDirection.value = value;
	}

	updateGrassLightColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uLightGreen.value = new THREE.Color(newColor);
	}

	updateGrassDarkColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uDarkGreen.value = new THREE.Color(newColor);
	}

	updateDirtLightColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uLightDirt.value = new THREE.Color(newColor);
	}

	updateDirtDarkColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uDarkDirt.value = new THREE.Color(newColor);
	}

	update() {
		if (!this.material) return;

		this.chunks.frustumCull(this.engine.camera);
		this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
	}

	rebuild() {
		this.destroy();
		this.init();
	}

	destroy() {
		this.chunks.entries().forEach(([, chunk]) => this.group.remove(chunk));
		this.chunks.dispose();

		this.material.dispose();
		Object.values(this.grassGeometries).forEach((geometry) => {
			geometry.dispose();
		});
		this.mesh?.geometry.dispose();
	}
}