import Experience from "../Experience.js";
import LoadingScreen, {LOADING_EVENTS} from "./LoadingScreen.js";
import * as THREE from "three";

export default class SoundIcon {
	private readonly experience : Experience;
	private readonly loading    : LoadingScreen;

	constructor(experience: Experience, loading: LoadingScreen) {
		this.experience = experience;
		this.loading    = loading;

		this.init();
	}

	private init() {
		let buttonAudio: THREE.Audio;
		this.experience.resources.once('loaded:soundButton', () => {
			buttonAudio = this.experience.engine.audio.createAmbientAudio(
				'button',
				this.experience.resources.items.soundButton,
				{
					loop: false,
					volume: 0.5,
				},
			);
		});

		const soundIcon = document.querySelector('.sound-icon')!;
		this.loading.on(LOADING_EVENTS.START_BUTTON_CLICKED, () => {
			soundIcon.classList.remove('hidden');
		});

		soundIcon.addEventListener('click', () => {
			buttonAudio?.stop();
			buttonAudio?.play();

			if (soundIcon.getAttribute('data-sound') === 'on') {
				soundIcon.setAttribute('data-sound', 'off');
				this.experience.engine.audio.disable();
			} else {
				soundIcon.setAttribute('data-sound', 'on');
				this.experience.engine.audio.enable();
			}
		});

		document.addEventListener('visibilitychange', () => {
			const isSoundEnabled = soundIcon.getAttribute('data-sound') === 'on';

			if (!isSoundEnabled) return;

			if (document.visibilityState === 'visible') {
				this.experience.engine.audio.enable();
			} else {
				this.experience.engine.audio.disable();
			}
		});

		if (document.visibilityState !== 'visible') {
			this.experience.engine.audio.disable();
		}
	}
}