import * as THREE from 'three';

export const BlueNoiseTextureDataURI: string =
  'data:image/png;base64,';

/**
 * Loads the texture without relying on any DOM-related classes like TextureLoader.
 * It allows the pass to be used in a worker with an offscreen canvas.
 *
 * Fallback using the DOM anyway if OffscreenCanvas is not supported by the client.
 */
async function loadBlueNoiseTexture() {
	const loader = new THREE.ImageBitmapLoader();

	const imageBitmap = await new Promise<ImageBitmap>((resolve, reject) => {
		loader.load(
			BlueNoiseTextureDataURI,
			resolve,
			undefined,
			reject
		);
	});

	const canvas = self.OffscreenCanvas
		? new OffscreenCanvas(imageBitmap.width, imageBitmap.height)
		: self.document.createElement('canvas');

	canvas.width = imageBitmap.width;
	canvas.height = imageBitmap.height;

	const ctx = canvas.getContext('2d');
	if (!ctx) throw new Error('Failed to get canvas context');

	ctx.drawImage(imageBitmap, 0, 0);

	return new THREE.CanvasTexture(canvas);
}

export const getBlueNoiseTexture = async (): Promise<THREE.Texture> => {
	const texture = await loadBlueNoiseTexture();

	texture.wrapS = THREE.RepeatWrapping;
	texture.wrapT = THREE.RepeatWrapping;
	texture.magFilter = THREE.NearestFilter;
	texture.minFilter = THREE.NearestFilter;
	texture.generateMipmaps = false;
	texture.needsUpdate = true;

	return texture;
};
