import * as THREE from 'three';
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import Engine from "../../../lib/core/Engine.js";
import grassGroundVertexShader from "./shaders/vertex.glsl";
import grassGroundFragmentShader from "./shaders/fragment.glsl";
import EventEmitter from '../../../lib/utils/EventEmitter.js';
import {RAYCASTER_EVENTS} from "../../../lib/core/Raycaster.js";
import Bender from "../bender/Bender.js";

type ColorParams = {
	lightColor : string,
	darkColor  : string,
}

type TweakValues = {
	scale: number,
	bendingFactor: number,
	bendingColorIntensity: number,
}

type GroundParams = {
	engine         : Engine,
	resources      : Resources<typeof sources>,
	parentGeometry : THREE.BufferGeometry,
	dirt           : ColorParams,
	grass          : ColorParams,
	shadowColor    : string,
	lightDirection : THREE.Vector3,
	group          : THREE.Group,
	initialTweaks  : TweakValues,
}

export class Ground extends EventEmitter {
	private readonly engine         : Engine;
	private readonly resources      : Resources<typeof sources>;
	private readonly parentGeometry : THREE.BufferGeometry;
	private readonly group          : THREE.Group;
	private readonly tweakValues    : TweakValues;
	private readonly grasslessGrounds : THREE.Mesh[];

	private bender!   : Bender;
	private material! : THREE.ShaderMaterial;
	private moveLastFrame : number;
	private outLastFrame : number;

	#mesh! : THREE.Mesh;

	constructor(
		{
			engine,
			resources,
			parentGeometry,
			dirt,
			grass,
			shadowColor,
			lightDirection,
			group,
			initialTweaks,
		}: GroundParams
	) {
		super();

		this.group          = group;
		this.moveLastFrame  = -1;
		this.outLastFrame   = -1;
		this.engine         = engine;
		this.resources      = resources;
		this.parentGeometry = parentGeometry;
		this.tweakValues    = initialTweaks;
		this.grasslessGrounds = [];

		this.init({ dirt, grass, shadowColor, lightDirection });
	}

	get geometry() : THREE.BufferGeometry {
		return this.parentGeometry;
	}

	configureBender(bender: Bender) {
		this.bender = bender;

		if (!this.material) return;

		this.material.uniforms.uBendingTexture.value = this.bender.texture;
	}

	private init(
		{
			dirt,
			grass,
			lightDirection,
			shadowColor,
		}: Pick<
			GroundParams,
			'dirt' | 'grass' | 'lightDirection' | 'shadowColor'
		>
		) {
		this.resources.onceAll(
			[
				'loaded:testIsland',
				'loaded:grassFieldDisplacementMap',
				'loaded:grassFieldWindNoiseTexture',
				'loaded:smoothWind',
			],
			() => {
				this.createMaterial({ dirt, grass, lightDirection, shadowColor });
				this.createMesh();
				this.applyMaterialToTopIslandSurfaces();
			},
		);
	}

	private createMaterial(
		{
			dirt,
			grass,
			lightDirection,
			shadowColor,
		}: Pick<
			GroundParams,
			'dirt' | 'grass' | 'lightDirection' | 'shadowColor'
		>,
	) {
		this.material = new THREE.ShaderMaterial({
			vertexShader: grassGroundVertexShader,
			fragmentShader: grassGroundFragmentShader,
			fog: true,
			lights: true,
			defines: {
				USE_SHADOWMAP: '',
			},
			uniforms: {
				uTime : new THREE.Uniform(0),

				uTextureScale : new THREE.Uniform(new THREE.Vector2()),
				uLightGreen : new THREE.Uniform(new THREE.Color(grass.lightColor)),
				uDarkGreen  : new THREE.Uniform(new THREE.Color(grass.darkColor)),
				uLightDirt  : new THREE.Uniform(new THREE.Color(dirt.lightColor)),
				uDarkDirt   : new THREE.Uniform(new THREE.Color(dirt.darkColor)),
				uLightDirection : new THREE.Uniform(lightDirection),
				uShadowColor    : new THREE.Uniform(new THREE.Color(shadowColor)),
				uBendingFactor  : new THREE.Uniform(this.tweakValues.bendingFactor),
				uBendingColorIntensity : new THREE.Uniform(this.tweakValues.bendingColorIntensity),

				uDisplacementMap  : new THREE.Uniform(this.resources.items.grassFieldDisplacementMap),
				uColorTexture     : new THREE.Uniform(this.resources.items.grassFieldWindNoiseTexture),
				uWindTexture      : new THREE.Uniform(this.resources.items.smoothWind),
				uBendingTexture   : new THREE.Uniform(
					this.bender
						? this.bender.texture
						: new THREE.Texture()
				),
				...THREE.UniformsLib.fog,
				...THREE.UniformsLib.lights,
			},
		});
	}

	private moveAlreadyCaughtOnceThisFrame(): boolean {
		return this.engine.renderer.instance.info.render.frame === this.moveLastFrame;
	}

	private outAlreadyCaughtOnceThisFrame(): boolean {
		return this.engine.renderer.instance.info.render.frame === this.outLastFrame;
	}

	private updateMoveFrameNumber() {
		this.moveLastFrame = this.engine.renderer.instance.info.render.frame;
	}

	private updateOutFrameNumber() {
		this.outLastFrame = this.engine.renderer.instance.info.render.frame;
	}

	private createMesh() {
		this.#mesh = new THREE.Mesh(
			this.parentGeometry,
			this.material,
		);

		this.#mesh.castShadow = true;
		this.#mesh.receiveShadow = true;

		const box = new THREE.Box3().setFromObject(this.#mesh);
		const size = box.getSize(new THREE.Vector3());
		this.material.uniforms.uTextureScale.value.set(size.x, size.y);

		this.engine.raycaster.on(
			RAYCASTER_EVENTS.POINTER_MOVE,
			this.#mesh,
			(event) => {
				if (this.moveAlreadyCaughtOnceThisFrame()) {
					return;
				}

				this.emit('pointerMove', event);
				this.updateMoveFrameNumber();
			}
		);

		this.engine.raycaster.on(
			RAYCASTER_EVENTS.POINTER_OUT,
			this.#mesh,
			(event) => {
				if (this.outAlreadyCaughtOnceThisFrame()) {
					return;
				}

				this.emit('pointerOut', event);
				this.updateOutFrameNumber();
			},
		);

		this.group.add(this.#mesh);
	}

	private applyMaterialToTopIslandSurfaces() {
		let childsToRemove : THREE.Object3D[] = [];

		this.resources.items.testIsland.scene.traverse((child) => {
			if (
				child instanceof THREE.Mesh
				&& [
					'top-island-grass-surface',
					'top-island-south-grass-surface',
					'top-island-north-grass-surface',
				].includes(child.name)
			) {
				child.geometry.computeTangents();
				child.geometry.scale(
					this.tweakValues.scale,
					this.tweakValues.scale,
					this.tweakValues.scale,
				);

				const mesh = new THREE.Mesh(
					child.geometry,
					this.material,
				);

				child.material.dispose();
				childsToRemove.push(child);

				this.grasslessGrounds.push(mesh);
				this.group.add(mesh);
			}
		});

		childsToRemove.forEach((child) => child.removeFromParent());
	}

	updateLightDirection(direction: THREE.Vector3) {
		if (!this.material) return;

		this.material.uniforms.uLightDirection.value = direction;
	}

	updateShadowColor(color: string) {
		if (!this.material) return;

		this.material.uniforms.uShadowColor.value = new THREE.Color(color);
	}

	updateDirtLightColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uLightDirt.value = new THREE.Color(newColor);
	}

	updateDirtDarkColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uDarkDirt.value = new THREE.Color(newColor);
	}

	updateGrassLightColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uLightGreen.value = new THREE.Color(newColor);
	}

	updateGrassDarkColor(newColor: string) {
		if (!this.material) return;

		this.material.uniforms.uDarkGreen.value = new THREE.Color(newColor);
	}

	update() {
		if (!this.material) return;

		this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
	}

	destroy() {
		this.grasslessGrounds.forEach((child) => {
			this.group.remove(child);
		});
		this.group.remove(this.#mesh);
		this.material.dispose();
	}
}