import * as THREE from 'three';
import Camera from "./Camera.js";

type AudioParams = {
	camera: Camera,
};

export type AudioUserData = {
	initialVolume    : number,
	crossfadeFactor  : number,
	spatialFactor    : number,
	crossfadeTarget? : number,
	crossfadeSpeed?  : number,
};

type AudioCreationConfig = {
	volume? : number,
	loop?   : boolean,
};

type KeysOfType<T, V> = {
	[K in keyof T]: T[K] extends V ? K : never
}[keyof T];

export type AudioItems = Record<string, THREE.Audio | THREE.PositionalAudio>;

export default class Audio<T extends AudioItems> {
	private readonly _listener: THREE.AudioListener;
	private readonly camera: Camera;

	private readonly audios: T;

	constructor({ camera }: AudioParams) {
		this._listener = new THREE.AudioListener();
		this.camera = camera;
		this.camera.instance.add(this._listener);

		this.audios = {} as T;
	}

	public get listener() {
		return this._listener;
	}

	get items(): T {
		return this.audios;
	}

	private configure(audio: THREE.Audio<any>, config: AudioCreationConfig) {
		const {
			volume,
			loop,
		} = config;

		audio.userData = {
			...audio.userData,
			initialVolume   : volume ?? 1,
			crossfadeFactor : 1,
			spatialFactor   : 1,
		};

		audio.setLoop(loop ?? false);
	}

	createAmbientAudio(
		name: KeysOfType<T, THREE.Audio>,
		buffer: AudioBuffer,
		config: AudioCreationConfig = {},
	) {
		const audio = new THREE.Audio(this._listener);

		audio.setBuffer(buffer);
		this.configure(audio, config);

		this.audios[name] = audio as T[KeysOfType<T, THREE.Audio>];

		return audio;
	}

	createPositionalAudio(
		name: KeysOfType<T, THREE.PositionalAudio>,
		buffer: AudioBuffer,
		config : AudioCreationConfig = {},
	) {
		const audio = new THREE.PositionalAudio(this._listener);

		audio.setBuffer(buffer);
		this.configure(audio, config);

		this.audios[name] = audio as T[KeysOfType<T, THREE.PositionalAudio>];

		return audio;
	}

	disable() {
		this._listener.setMasterVolume(0);
	}

	enable() {
		this._listener.setMasterVolume(1);
	}

	crossfade(
		audioOut: THREE.Audio,
		audioIn: THREE.Audio,
		{ duration = 2, inVolume = 1, outVolume = 0 } = {}
	) {
		const outUserData = audioOut.userData as AudioUserData;
		const inUserData  = audioIn.userData as AudioUserData;

		outUserData.crossfadeTarget = outVolume;
		inUserData.crossfadeTarget  = inVolume;

		outUserData.crossfadeSpeed = Math.abs(outUserData.crossfadeTarget - outUserData.crossfadeFactor) / duration;
		inUserData.crossfadeSpeed  = Math.abs(inUserData.crossfadeTarget - inUserData.crossfadeFactor) / duration;

		if (!audioIn.isPlaying) {
			audioIn.play();
		}
	}

	update(delta: number) { // pass elapsed time in seconds
		for (const key in this.audios) {
			const audio = this.audios[key];
			if (!audio) continue;

			const data = audio.userData as AudioUserData;

			if (data.crossfadeTarget !== undefined && data.crossfadeSpeed !== undefined) {
				const dir = Math.sign(data.crossfadeTarget - data.crossfadeFactor);
				data.crossfadeFactor += dir * data.crossfadeSpeed * delta;

				if ((dir > 0 && data.crossfadeFactor >= data.crossfadeTarget) ||
					(dir < 0 && data.crossfadeFactor <= data.crossfadeTarget)) {
					data.crossfadeFactor = data.crossfadeTarget;
					data.crossfadeTarget = undefined;
					data.crossfadeSpeed = undefined;
				}
			}

			const base = data.initialVolume ?? 1;
			const fade = data.crossfadeFactor ?? 1;
			const spatial = data.spatialFactor ?? 1;

			audio.setVolume(base * fade * spatial);
		}
	}
}