import * as THREE from 'three';
import Engine from "../../../../lib/core/Engine.js";
import Random from "../../../../lib/utils/Random.js";
import fragmentShader  from './shaders/fragment.glsl';
import vertexShader  from './shaders/vertex.glsl';

type TweakValues = {
	count : number,
	size  : number,
}

type WaterSplashesParams = {
	group: THREE.Group,
	engine: Engine,
	initialTweaks: TweakValues,
}

export default class WaterDrops {
	private readonly engine: Engine;
	private readonly group: THREE.Group;
	private readonly tweakValues: TweakValues;

	private particles!: THREE.Points;
	private material!: THREE.ShaderMaterial;

	constructor(
		{
			group,
			engine,
			initialTweaks,
		}: WaterSplashesParams
	) {
		this.group = group;
		this.engine = engine;
		this.tweakValues = initialTweaks;

		this.init();
	}

	private init() {
		this.createMaterial();
		this.createParticles();
		this.addParticlesToTheGroup();
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			fragmentShader,
			vertexShader,
			transparent: true,
			uniforms: {
				uTime       : new THREE.Uniform(0),
				uResolution : new THREE.Uniform(this.resolution),
				uSize       : new THREE.Uniform(this.tweakValues.size),
			}
		});
	}

	get resolution() {
		return new THREE.Vector2(...this.engine.sizes.resolution);
	}

	private createParticles() {
		const geometry = new THREE.BufferGeometry();

		const positions = new Float32Array(this.tweakValues.count * 3);
		const colors = new Float32Array(this.tweakValues.count * 3);
		const impulses = new Float32Array(this.tweakValues.count * 3);
		const sizes = new Float32Array(this.tweakValues.count);
		const lifeCycles = new Float32Array(this.tweakValues.count);
		const delays = new Float32Array(this.tweakValues.count);

		for (let i = 0; i < this.tweakValues.count; i++) {
			const i3 = i * 3;

			positions.set([
				-0.23,
				0.0,
				(Math.random() - 0.5) * 0.22 + 0.05,
			], i3);

			sizes.set([
				Math.max(Math.random(), 0.1),
			], i);
			delays.set([
				Math.random(),
			], i);
			lifeCycles.set([
				Math.max(Math.random(), 0.2) * 5,
			], i);

			colors.set(Random.color().toArray(), i3);

			impulses.set([
				(Math.random() - 0.5) * 1.5,
				Math.max(Math.random(), 0.1) * 1.2,
				(Math.random() - 0.5) * 1.5,
			], i3);
		}

		geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
		geometry.setAttribute('aColor', new THREE.BufferAttribute(colors, 3));
		geometry.setAttribute('aImpulse', new THREE.BufferAttribute(impulses, 3));
		geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
		geometry.setAttribute('aLifeCycle', new THREE.BufferAttribute(lifeCycles, 1));
		geometry.setAttribute('aDelay', new THREE.BufferAttribute(delays, 1));

		this.particles = new THREE.Points(
			geometry,
			this.material,
		);
	}

	private addParticlesToTheGroup() {
		this.group.add(this.particles);
	}

	update() {
		if (!this.material) {
			return;
		}

		this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds * 0.4;
	}

	destroy() {
		this.group.remove(this.particles);
		this.material.dispose();
		this.particles.geometry.dispose();
	}
}