import Experience from "../Experience.js";
import {SWARM_EVENTS} from "../scenes/islands/swarm/Swarm.js";

export default class ContactSection {
	private readonly experience: Experience;

	constructor(experience: Experience) {
		this.experience = experience;

		this.init();
	}

	private init() {
		const experience = this.experience;

		const prevMainButton = document.querySelector('.swarm-switch .left')!;
		const prevSecondaryButton = document.querySelector('.social-media .left-arrow')!;

		const nextMainButton = document.querySelector('.swarm-switch .right')!;
		const nextSecondaryButton = document.querySelector('.social-media .right-arrow')!;

		function getCurrentContactStep() {
			return document.querySelector(
				'.social-media ul li.active a'
			)! as HTMLLinkElement;
		}

		function getAllContactSteps() {
			return document.querySelectorAll(
				'.social-media ul li a'
			) as NodeListOf<HTMLLinkElement>;
		}

		function getNextStep() {
			const currentContactStep = getCurrentContactStep();
			const allSteps = getAllContactSteps();

			const currentStepIndex = Array.from(allSteps).indexOf(currentContactStep);
			if (currentStepIndex === allSteps.length - 1) {
				return allSteps[0];
			}

			return allSteps[currentStepIndex + 1];
		}

		function getPrevStep() {
			const currentContactStep = getCurrentContactStep();
			const allSteps = getAllContactSteps();

			const currentStepIndex = Array.from(allSteps).indexOf(currentContactStep);

			if (currentStepIndex === 0) {
				return allSteps[allSteps.length - 1];
			}

			return allSteps[currentStepIndex - 1];
		}

		function moveActiveClass(nextStep: HTMLLinkElement) {
			const currentStep = getCurrentContactStep();

			currentStep.parentNode?.classList.remove('active');
			nextStep.parentNode?.classList.add('active');
		}

		function next() {
			const step = getNextStep();
			const stepName = step.getAttribute('data-social-media');

			switch(stepName) {
				case 'youtube':
					experience.world.islands.swarm.displayYoutube();
					break;
				case 'x':
					experience.world.islands.swarm.displayX();
					break;
				case 'linkedin':
					experience.world.islands.swarm.displayLinkedIn();
					break;
				default:
					experience.world.islands.swarm.displayDefault();
					break;
			}

			moveActiveClass(step);
		}

		function prev() {
			const step = getPrevStep();
			const stepName = step.getAttribute('data-social-media');

			switch(stepName) {
				case 'youtube':
					experience.world.islands.swarm.displayYoutube();
					break;
				case 'x':
					experience.world.islands.swarm.displayX();
					break;
				case 'linkedin':
					experience.world.islands.swarm.displayLinkedIn();
					break;
				default:
					experience.world.islands.swarm.displayDefault();
					break;
			}

			moveActiveClass(step);
		}

		prevMainButton.addEventListener('click', prev);
		prevSecondaryButton.addEventListener('click', prev);

		nextMainButton.addEventListener('click', next);
		nextSecondaryButton.addEventListener('click', next);


		window.addEventListener(SWARM_EVENTS.EXPLODED, next);
	}
}