import * as THREE from 'three';
import Chunked3D, { Chunked3DEntry } from "./Chunked3D.js";
import {MeshSurfaceSampler} from "three/examples/jsm/math/MeshSurfaceSampler.js";
import Camera from "../../core/Camera.js";
import ChunkedInstancedMeshLod from "./ChunkedInstancedMeshLod.js";

export type ChunkedInstancedMeshParams = {
	chunkSize? : THREE.Vector3,
	/**
	 * Total number of instances (all chunks)
	 */
	total     : number,
	geometry  : THREE.BufferGeometry,
	material  : THREE.Material,
	lod       : ChunkedInstancedMeshLod,
	cameraMoveThreshold? : number,
}

export type Instance = {
	matrix: THREE.Matrix4,
	attributes: Record<string, Float32Array>,
}

type InstancedMeshChunk = {
	mesh : THREE.InstancedMesh,
	objectCenter : THREE.Vector3,
	lod  : ChunkedInstancedMeshLod,
	attributes : Record<string, THREE.InstancedBufferAttribute>
}

export default abstract class ChunkedInstancedMesh {
	private readonly chunks   : Chunked3D<Instance[]>;
	private readonly total    : number;
	private readonly upVector : THREE.Vector3;
	private readonly material : THREE.Material;
	private readonly cameraMoveThreshold : number;
	private readonly cameraToObject: THREE.Vector3;
	private readonly cameraWorldPosition : THREE.Vector3;
	private readonly boundingBox : THREE.Box3;

	private lastCameraPosition : THREE.Vector3;
	private accumulatedCameraDistance : number = 0;

	protected readonly dummy      : THREE.Object3D;
	protected readonly normal     : THREE.Vector3;
	protected readonly position   : THREE.Vector3;
	protected readonly color      : THREE.Color;
	protected readonly uv         : THREE.Vector2;
	protected readonly quaternion : THREE.Quaternion;
	protected readonly instancedMeshes : Record<string, InstancedMeshChunk>;

	public readonly lod : ChunkedInstancedMeshLod;

	protected constructor(
		{
			total,
			chunkSize,
			material,
			lod,
			cameraMoveThreshold,
		}: ChunkedInstancedMeshParams
	) {
		this.material   = material;
		this.total      = total;
		this.chunks     = new Chunked3D({ size: chunkSize });
		this.quaternion = new THREE.Quaternion();
		this.dummy      = new THREE.Object3D();
		this.normal     = new THREE.Vector3();
		this.position   = new THREE.Vector3();
		this.uv         = new THREE.Vector2();
		this.color      = new THREE.Color();
		this.upVector   = new THREE.Vector3(0, 1, 0);
		this.lod        = lod;

		this.cameraToObject      = new THREE.Vector3();
		this.boundingBox         = new THREE.Box3();
		this.cameraMoveThreshold = cameraMoveThreshold ?? 0.1;
		this.cameraWorldPosition = new THREE.Vector3();
		this.lastCameraPosition  = new THREE.Vector3();
		this.instancedMeshes     = {};

		this.accumulatedCameraDistance = 0;
	}

	abstract getSampler()       : MeshSurfaceSampler;
	abstract sampleAttributes() : Record<string, Float32Array>;
	abstract postSample()       : void;

	updateChunk(_instancedMesh: THREE.InstancedMesh, _index: THREE.Vector3) : void {};

	sample(): void {
		const sampler = this.getSampler();

		for (let i = 0; i < this.total; i++) {
			sampler.sample(
				this.position,
				this.normal,
				this.color,
				this.uv,
			);

			this.dummy.position.copy(this.position);
			this.quaternion.setFromUnitVectors(this.upVector, this.normal);
			this.dummy.setRotationFromQuaternion(this.quaternion);

			const sampledAttributes = this.sampleAttributes();

			if (!this.chunks.existsByPosition(this.position)) {
				this.chunks.setByPosition(this.position, []);
			}

			const chunk = this.chunks.getByPosition(this.position)!;
			chunk.push({
				matrix: this.dummy.matrix.clone(),
				attributes: sampledAttributes,
			});
		}

		this.postSample();

		this.chunks.entries().forEach(this.createChunk.bind(this));
	}

	private createChunk({ key, value }: Chunked3DEntry<Instance[]>) {
		const compiledAttributes = this.generateInstancedBufferAttributes(value);
		const lod = this.lod.cloneWithAttributes(compiledAttributes);

		const geometry = lod.getDefaultGeometry();

		const mesh = new THREE.InstancedMesh(
			geometry,
			this.material,
			value.length,
		);

		value.forEach(({ matrix }, index) => {
			mesh.setMatrixAt(index, matrix);
		});

		mesh.instanceMatrix.needsUpdate = true;
		mesh.computeBoundingBox();
		mesh.computeBoundingSphere();

		const objectCenter = new THREE.Vector3();
		mesh.boundingBox!.getCenter(objectCenter);

		this.instancedMeshes[this.indexToKey(key)] = {
			mesh,
			lod,
			objectCenter,
			attributes : compiledAttributes,
		};
	}

	private generateInstancedBufferAttributes(
		instances : Instance[],
	): Record<string, THREE.InstancedBufferAttribute> {
		const compiledAttributes: Record<string, Float32Array> = {};

		instances.forEach(({ attributes }, i) => {
			Object.entries(attributes).forEach(([ attributeName, attributeValues ]) => {
				if (!(attributeName in compiledAttributes)) {
					compiledAttributes[attributeName] = new Float32Array(instances.length * attributeValues.length);
				}

				compiledAttributes[attributeName].set(attributeValues, i * attributeValues.length);
			});
		});

		return Object.fromEntries(Object.entries(compiledAttributes).map(([key, value]) => {
			return [
				key,
				new THREE.InstancedBufferAttribute(
					value,
					value.length / instances.length,
				),
			]
		}));
	}

	entries(): [THREE.Vector3, THREE.InstancedMesh][]{
		return Object.entries(this.instancedMeshes).map(([key, value]) => {
			return [
				this.keyToIndex(key),
				value.mesh,
			];
		});
	}

	private indexToKey(index: THREE.Vector3): string {
		return `${index.x};${index.y};${index.z}`;
	}

	private keyToIndex(key: string): THREE.Vector3 {
		return new THREE.Vector3(
			...key.split(';').map(Number)
		);
	}

	frustumCull(
		camera: Camera,
		{
			bottomCullAngleFarThreshold = 5,
			bottomCullAngleNearThreshold = 25,
			interpolationDistance = 7.5
		}: {
			bottomCullAngleFarThreshold?: number
			bottomCullAngleNearThreshold?: number
			interpolationDistance?: number
		} = {}
	) {
		const frameDelta = this.lastCameraPosition.distanceTo(camera.instance.getWorldPosition(this.cameraWorldPosition));
		this.accumulatedCameraDistance += frameDelta;
		this.lastCameraPosition.copy(this.cameraWorldPosition);

		if (this.accumulatedCameraDistance < this.cameraMoveThreshold) {
			return;
		}
		this.accumulatedCameraDistance = 0;

		const angleFarThresholdRad = THREE.MathUtils.degToRad(bottomCullAngleFarThreshold);
		const angleNearThresholdRad = THREE.MathUtils.degToRad(bottomCullAngleNearThreshold);

		Object.values(this.instancedMeshes).forEach(({ mesh: instancedMesh, lod, objectCenter }) => {
			instancedMesh.updateMatrixWorld(true);
			this.boundingBox.setFromObject(instancedMesh);

			if (!camera.frustum.intersectsBox(this.boundingBox)) {
				instancedMesh.visible = false;
				return;
			}

			if (this.cameraWorldPosition.y < this.boundingBox.min.y) {
				this.cameraToObject.subVectors(objectCenter, this.cameraWorldPosition);
				const len = this.cameraToObject.length();

				if (len !== 0) {
					const threshold = THREE.MathUtils.lerp(
						angleNearThresholdRad,
						angleFarThresholdRad,
						len / interpolationDistance,
					);

					const verticalAngle = Math.asin(this.cameraToObject.y / len);

					instancedMesh.visible = verticalAngle < threshold;
				}
			} else {
				instancedMesh.visible = true;
			}

			if (instancedMesh.visible) {
				this.applyLod(instancedMesh, lod);
			}
		});
	}

	public divideLodCountBy(factor: number) {
		Object.values(this.instancedMeshes).forEach(({ lod }) => {
			lod.divideCountsBy(factor);
		});
	}

	private applyLod(
		instancedMesh : THREE.InstancedMesh,
		lod           : ChunkedInstancedMeshLod,
	) {
		this.boundingBox.getCenter(this.position);
		const level = lod.getLod(this.position, this.cameraWorldPosition);

		instancedMesh.count = instancedMesh.instanceMatrix.count;

		if (level.count !== undefined) {
			instancedMesh.count = Math.round(instancedMesh.count * level.count);
			instancedMesh.visible = level.count > 0;
		}

		if (level.geometry) {
			instancedMesh.geometry = level.geometry;
		}
	}

	public updateLod() {
		Object.values(this.instancedMeshes).forEach((value) => {
			this.applyLod(value.mesh, value.lod);
		});
	}

	update() {
		Object.entries(this.instancedMeshes).forEach(([key, value]) => {
			this.updateChunk(value.mesh, this.keyToIndex(key));
		});
	}

	dispose() {
		Object.entries(this.instancedMeshes).forEach(([key, value]) => {
			value.mesh.dispose();
			value.lod.dispose();

			delete this.instancedMeshes[key];
		});
	}
}