import * as THREE from 'three';
import Engine from "../../../../lib/core/Engine.js";
import fragmentShader from './shaders/fragment.glsl';
import vertexShader from './shaders/vertex.glsl';

type FireParams = {
	engine: Engine,
	islands: THREE.Group,
	position: THREE.Vector3,
}

export default class Fire {
	private readonly engine: Engine;
	private readonly islands: THREE.Group;
	private readonly position: THREE.Vector3;

	private material!: THREE.ShaderMaterial;
	private mesh!: THREE.Mesh;

	constructor(
		{
			engine,
			islands,
			position,
		}: FireParams,
	) {
		this.engine = engine;
		this.islands = islands;
		this.position = position;

		this.init();
	}

	private init() {
		this.initMaterial();
		this.initMesh();

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;
			if (!declineLevel) return;

			switch(declineLevel) {
				case 1:
					this.mesh.geometry.dispose();
					this.mesh.geometry = this.createGeometry(75);
					break;
				case 2:
					this.mesh.geometry.dispose();
					this.mesh.geometry = this.createGeometry(50);
					break;
				case 5:
					this.mesh.geometry.dispose();
					this.mesh.geometry = this.createGeometry(25);
					break;
			}
		});
	}

	private createGeometry(segments = 100) {
		const geometry = new THREE.PlaneGeometry(1, 1, segments, segments);
		geometry.translate(0, 0.5, 0);

		return geometry;
	}

	private initMaterial() {
		this.material = new THREE.ShaderMaterial({
			fragmentShader,
			vertexShader,
			uniforms: {
				uTime: new THREE.Uniform(0),
			},
			// blending: THREE.AdditiveBlending,
			depthWrite: false,
			transparent: true,
		});
	}

	private initMesh() {
		this.mesh = new THREE.Mesh(
			this.createGeometry(100),
			this.material,
		);

		this.mesh.position.copy(this.position);
		this.mesh.position.y -= 0.005;
		// this.mesh.scale.set(0.05, 0.05, 0.05);
		const xScale = 0.10 * 1.05;
		const yScale = 0.15 * 1.05;
		const zScale = xScale;

		this.mesh.scale.set(xScale, yScale, zScale);

		this.islands.add(this.mesh);
	}

	update() {
		if (!this.material) {
			return;
		}

		this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
	}

	destroy() {
		this.material.dispose();
		this.mesh.geometry.dispose();
		this.mesh.removeFromParent();
	}
}