import * as THREE from 'three';
import fragmentShader from './shaders/fragment.glsl';
import vertexShader from './shaders/vertex.glsl';
import Engine from "../../core/Engine.js";

import Resources from "../../core/Resources.js";
import sources from "../../../config/resources.config.js";

type BakedUniforms = Record<string, any>;

export default class ShaderBaker {
	private readonly engine     : Engine;
	private readonly resources  : Resources<typeof sources>;
	private readonly resolution : number;
	private readonly meshToBake : THREE.Mesh;
	private readonly bakingVertexShader: string;

	private readonly bakedTextures : THREE.WebGLRenderTarget[];
	private bakingScene!  : THREE.Scene;
	private bakingCamera! : THREE.OrthographicCamera;
	private bakingQuad!   : THREE.Mesh;
	private readonly bakingSnapshots! : [BakedUniforms, BakedUniforms];
	private readonly customBakedFragmentShader? : string;
	constructor(
		bakingVertexShader: string,
		resolution: number,
		engine: Engine,
		resources: Resources<typeof sources>,
		mesh: THREE.Mesh,
		bakingSnapshots: [BakedUniforms, BakedUniforms],
		customBakedFragmentShader?: string,
	) {
		this.bakingVertexShader = bakingVertexShader;
		this.resources = resources;
		this.engine = engine;
		this.resolution = resolution;
		this.meshToBake = mesh;
		this.bakedTextures = [];
		this.bakingSnapshots = bakingSnapshots;
		this.customBakedFragmentShader = customBakedFragmentShader;

		this.init();
	}

	private renderBuffer(buffer: THREE.WebGLRenderTarget, bakedUniforms: BakedUniforms) {
		Object.entries(bakedUniforms).forEach(([key, value]) => {
			this.meshToBake.material.uniforms[key].value = value;
		});

		this.engine.renderer.instance.setRenderTarget(buffer);
		this.engine.renderer.instance.render(
			this.bakingScene,
			this.bakingCamera
		);
		this.engine.renderer.instance.setRenderTarget(null);
	}

	private setupRendering() {
		this.bakingScene = new THREE.Scene();
		this.bakingCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

		const shader: THREE.ShaderMaterial = this.meshToBake.material as THREE.ShaderMaterial;
		shader.vertexShader = this.bakingVertexShader;
		shader.needsUpdate = true;
		this.bakingQuad = new THREE.Mesh(
			this.createGeometry(),
			shader,
		);

		this.bakingScene.add(this.bakingQuad);
	}

	private createGeometry(): THREE.PlaneGeometry {
		const subdivisions = Math.ceil(
			Math.sqrt(this.meshToBake.geometry.attributes.position.count / 3),
		) * 1.5;
		return new THREE.PlaneGeometry(2, 2, subdivisions, subdivisions);
	}

	private initBuffers() {
		const opts = {
			minFilter: THREE.NearestFilter,
			magFilter: THREE.NearestFilter,
			wrapS: THREE.RepeatWrapping,
			wrapT: THREE.RepeatWrapping,
			format: THREE.RGBAFormat,
			type: THREE.FloatType,
		};

		this.bakedTextures.push(
			new THREE.WebGLRenderTarget(this.resolution, this.resolution, opts),
		);
	}

	private init() {
		this.setupRendering();
		this.initBuffers();
	}

	bake() {
		this.renderBuffer(this.bakedTextures[0], this.bakingSnapshots[0]);

		return new THREE.ShaderMaterial({
			fragmentShader: this.customBakedFragmentShader ?? fragmentShader,
			vertexShader,
			uniforms: {
				noise: new THREE.Uniform(this.resources.items.grassFieldWindNoiseTexture),
				colorTexture0: new THREE.Uniform(this.bakedTextures[0].texture),
				mixFactor: new THREE.Uniform(0),
			}
		});
	}
}