import * as THREE from "three";
import gsap from "gsap";
import Engine from "./lib/core/Engine.js";
import EventEmitter from "./lib/utils/EventEmitter.js";

type CameraSpotsParams = {
	engine: Engine;
}

type MoveFromToParams = {
	position: {
		from: THREE.Vector3,
		to: THREE.Vector3,
	},
	direction: {
		from: THREE.Vector3,
		to: THREE.Vector3,
	},
};

type MoveFromToOptions = {
	duration?: number,
	ease?: gsap.EaseString,
	onComplete?: () => void,
	intermediatePoints?: {
		position: THREE.Vector3,
		direction: THREE.Vector3,
	}[],
}

const SWITCH_POSITION_TIME = 5;

export enum EVENTS {
	INTRO_STARTED = 'cameraSpot:intro-started',
	INTRO_PLAYED = 'cameraSpot:intro-played',
	TRAVEL_STARTED = 'cameraSpot:travel:started',
	TRAVEL_ENDED = 'cameraSpot:travel:ended',
}

function smoothstep(edge0: number, edge1: number, x: number) {
	// Clamp x to [0, 1] based on the edges
	let t = Math.min(Math.max((x - edge0) / (edge1 - edge0), 0), 1);
	// Apply the smoothstep polynomial
	return t * t * (3 - 2 * t);
}

export default class CameraSpots extends EventEmitter {
	private readonly engine: Engine;

	public readonly intro = {
		start: {
			position: new THREE.Vector3(51.38, 14.71, 7.37),
			direction: new THREE.Vector3(-0.97, -0.20, -0.13),
		},
		end: {
			position: new THREE.Vector3(5.75, 1.34, 5.27),
			direction: new THREE.Vector3(-0.76, -0.05, -0.65),
		},
		easing: 'power1.inOut',
		time: 6,
	};

	public readonly points = {
		start: this.intro.end,
		contact: {
			position: new THREE.Vector3(-6.26, 5.04 ,4.45),
			direction: new THREE.Vector3(0.17, 0.10, -0.98),
		},
		campfire: {
			position: new THREE.Vector3(4.70, 0.49, 0.01),
			direction: new THREE.Vector3(-0.96, 0.24, 0.16),
		},
		swarmViewFromTree: {
			position: new THREE.Vector3(1.72, 5.80, 2.13),
			direction: new THREE.Vector3(-0.99, -0.07, -0.13),
		},
		farOverview: {
			position: new THREE.Vector3(10.08, 0.46, 7.58),
			direction: new THREE.Vector3(-0.83, 0.17, -0.52),
		},
		westWaterfall: {
			position: new THREE.Vector3(-3.20, 1.97, 5.12),
			direction: new THREE.Vector3(0.50, 0.01, -0.87),
		},
		eastWaterfall: {
			position: new THREE.Vector3(-2.85, 0.87, -6.86),
			direction: new THREE.Vector3(0.38, 0.19, 0.90),
		},
		south: {
			position: new THREE.Vector3(4.59, 1.30, -7.15),
			direction: new THREE.Vector3(-0.67, 0.09, 0.74),
		},
		behindWaterfall: {
			position: new THREE.Vector3(-3.62, 1.31, -0.63),
			direction: new THREE.Vector3(0.50, -0.10, -0.86),
		},
		topNorth: {
			position: new THREE.Vector3(-7.92, 5.53, -4.97),
			direction: new THREE.Vector3(0.40, -0.03, 0.91),
		},
		contactIntermediatePoint: {
			invisible: true,
			position: new THREE.Vector3(1.29, 5.29, -1.08),
			direction: new THREE.Vector3(-0.77, -0.09, 0.64),
		}
	};

	constructor({ engine }: CameraSpotsParams) {
		super();

		this.engine = engine;

		this.init();
	}

	private init() {
		const { position, direction } = this.intro.start;

		// Copy camera position
		this.engine.camera.instance.position.copy(position);

		// Compute target like moveFromTo
		const target = new THREE.Vector3()
			.copy(position)
			.add(direction.clone().normalize());

		this.engine.camera.instance.lookAt(target);

		// Update controls target
		if (this.engine.camera.controls) {
			this.engine.camera.controls.target.copy(target);
			this.engine.camera.controls.update();
		}

		// Update matrices and frustum
		this.engine.camera.instance.updateMatrixWorld(true);
		this.engine.camera.instance.matrixWorldInverse.copy(this.engine.camera.instance.matrixWorld).invert();
		this.engine.camera.instance.updateProjectionMatrix();
		this.engine.camera.updateFrustum();
	}

	playIntro() {
		this.emit(EVENTS.INTRO_STARTED);

		this.moveFromTo(
			{
				position: {
					from: this.intro.start.position,
					to: this.intro.end.position,
				},
				direction: {
					from: this.intro.start.direction,
					to: this.intro.end.direction,
				},
			},
			{
				duration: this.intro.time,
				ease: this.intro.easing,
				onComplete: () => {
					this.emit(EVENTS.INTRO_PLAYED);
				}
			}
		);
	}

	private moveFromTo(
		{
			position: { from: fromPosition, to: toPosition },
			direction: { from: fromDirection, to: toDirection },
		}: MoveFromToParams,
		{
			duration = SWITCH_POSITION_TIME,
			ease = "power2.inOut",
			onComplete,
			intermediatePoints = [],
		}: MoveFromToOptions,
	) {
		this.emit(EVENTS.TRAVEL_STARTED);

		const path = [
			{ position: fromPosition, direction: fromDirection },
			...intermediatePoints,
			{ position: toPosition, direction: toDirection },
		];

		const hasIntermediates = intermediatePoints.length > 0;
		const segmentDuration = duration / (path.length - 1);

		const getSegmentEase = (index: number): gsap.EaseString => {
			if (!hasIntermediates) return ease; // no intermediates → just use ease

			if (index === 0) return ease.replace(/\.inOut$/, ".in") as gsap.EaseString;
			if (index === path.length - 2) return ease.replace(/\.inOut$/, ".out") as gsap.EaseString;
			return ease;
		};

		const animateSegment = (index: number) => {
			if (index >= path.length - 1) {
				// Reset camera group to origin for parallax effect
				this.engine.camera.group.position.set(0, 0, 0);

				this.emit(EVENTS.TRAVEL_ENDED);
				onComplete?.();
				return;
			}

			const start = path[index];
			const end = path[index + 1];

			const animatedValue = { value: 0 };
			const directionLerp = new THREE.Vector3();
			const newTarget = new THREE.Vector3();

			gsap.to(animatedValue, {
				duration: segmentDuration,
				ease: getSegmentEase(index),
				value: 1,
				onUpdate: () => {
					const t = animatedValue.value;

					this.engine.camera.instance.position.lerpVectors(
						start.position,
						end.position,
						t,
					);

					directionLerp
						.lerpVectors(
							start.direction.clone().normalize(),
							end.direction.clone().normalize(),
							smoothstep(0.7, 1, t),
						)
						.normalize();

					newTarget
						.copy(this.engine.camera.instance.position)
						.add(directionLerp);

					this.engine.camera.instance.lookAt(newTarget);
					this.engine.camera.controls.target.copy(newTarget);
					this.engine.camera.controls.update();
				},
				onComplete: () => animateSegment(index + 1),
			});
		};

		animateSegment(0);
	}

	goTo(
		position: keyof typeof this.points,
		options: MoveFromToOptions = {}
	) {
		const {
			position: targetPosition,
			direction: targetDirection,
		} = this.points[position];

		// Get current world position (instance + group offset from parallax)
		const currentWorldPosition = this.engine.camera.instance.position.clone()
			.add(this.engine.camera.group.position);

		// Get current direction
		const startDirection = this.engine.camera.instance.getWorldDirection(new THREE.Vector3());

		if (currentWorldPosition.equals(targetPosition)) {
			options?.onComplete?.();
			return;
		}

		// Before starting animation, consolidate the position:
		// Set camera instance to world position and reset group
		this.engine.camera.instance.position.copy(currentWorldPosition);
		this.engine.camera.group.position.set(0, 0, 0);

		const intermediatePoints: typeof this.points[typeof position][] = [];

		if (
			position === 'contact'
			&& currentWorldPosition.y < 5
		) {
			intermediatePoints.push(this.points.contactIntermediatePoint);
		}

		this.moveFromTo(
			{
				position: {
					from: currentWorldPosition,
					to: targetPosition,
				},
				direction: {
					from: startDirection,
					to: targetDirection,
				},
			},
			{
				duration: SWITCH_POSITION_TIME,
				ease: 'power2.inOut',
				intermediatePoints,
				...options
			}
		);
	}
}