import Renderer from "../core/Renderer.js";
import EventEmitter from "../utils/EventEmitter.js";
import Monitor from './Monitor.js';
import GpuPerfCollector from "./GpuPerfCollector.js";
import PerfsGuiCapabilities from "./PerfsGuiCapabilities.js";

type PerfsOptions = {
	renderer: Renderer,
	monitor: Monitor,
	gui: PerfsGuiCapabilities,
};

export type FpsMetrics = {
	fps: number,
	cpuTimePerFrame: number,
	fullFrameTime: number,
	gpuTimePerFrame: number,
}

export default class Perfs extends EventEmitter{
	private readonly gui?             : PerfsGuiCapabilities;
	private readonly renderer         : Renderer;
	private readonly gpuPerfCollector : GpuPerfCollector;
	private readonly fpsAlpha         : number = 0.4;
	private readonly cpuAlpha         : number = 0.4;

	private lastFrameTime    : number;
	private startFrameTime   : number;
	private smoothedFps      : number = 60;
	private smoothedCpuDelta : number = 0;

	readonly #monitor      : Monitor;

	constructor(
		{
			/*parent,*/
			renderer,
			monitor,
			gui,
		}: PerfsOptions
	) {
		super();

		this.gui              = gui;
		this.#monitor         = monitor;
		this.renderer         = renderer;
		this.lastFrameTime    = performance.now();
		this.startFrameTime   = 0;
		this.gpuPerfCollector = new GpuPerfCollector(renderer);

		this.renderer.instance.info.autoReset = false;

		if (!this.shouldBeVisible()) {
			this.disable();
		}
	}

	get monitor() {
		return this.#monitor;
	}

	enable() {
		this.gui?.enable();
	}

	disable() {
		this.gui?.disable();
	}

	private shouldBeVisible() {
		const queryString = window.location.search;

		const urlParams = new URLSearchParams(queryString);
		const debugParam = urlParams.get('monitor');

		return debugParam === 'true';
	}

	private gatherFpsMetrics() {
		const now = performance.now();

		const fullFrameDelta = Math.max(0.0001, now - this.lastFrameTime);
		const cpuDelta       = Math.max(0.0001, now - this.startFrameTime);
		const currentFps     = 1000 / fullFrameDelta;

		this.smoothedFps      = this.fpsAlpha * currentFps + (1 - this.fpsAlpha) * this.smoothedFps;
		this.smoothedCpuDelta = this.cpuAlpha * cpuDelta   + (1 - this.cpuAlpha) * this.smoothedCpuDelta;


		this.lastFrameTime = now;

		return {
			fps             : Math.round(this.smoothedFps),
			cpuTimePerFrame : this.smoothedCpuDelta,
			fullFrameTime   : fullFrameDelta,
		};
	}

	preRender() {
		this.startFrameTime = performance.now();
		this.gpuPerfCollector.begin();
	}

	postRender() {
		const fpsMetrics      = this.gatherFpsMetrics();
		const gpuTimePerFrame = this.gpuPerfCollector.end();

		this.gui?.update(
			this.renderer.instance.info,
			{
				...fpsMetrics,
				gpuTimePerFrame: gpuTimePerFrame ?? (fpsMetrics.fullFrameTime - fpsMetrics.cpuTimePerFrame),
			},
		);
		this.monitor?.addSample(fpsMetrics.fps);

		this.renderer.instance.info.reset();
	}

	destroy() {
		this.gui?.destroy();
	}
}