import * as THREE from 'three';

type Chunked3DParams = {
	size?: THREE.Vector3,
	origin?: THREE.Vector3
}

export type Chunked3DEntry<T> = {
	key   : THREE.Vector3,
	value : T,
}

export default class Chunked3D<ChunkedObject> {
	private chunkMap = new Map<string, ChunkedObject>();
	public readonly size   : THREE.Vector3;

	constructor(
		{
			size = new THREE.Vector3(1,1,1),
		}: Chunked3DParams = {}
	) {
		this.size = size;
	}

	positionToChunkIndex(position: THREE.Vector3): THREE.Vector3 {
		return new THREE.Vector3(
			Math.round(position.x / this.size.x),
			Math.round(position.y / this.size.y),
			Math.round(position.z / this.size.z)
		);
	}

	private coordToKey(pos: THREE.Vector3): string {
		return `${pos.x};${pos.y};${pos.z}`;
	}

	private keyToCoord(key: string): THREE.Vector3 {
		const [x,y,z] = key.split(';').map(Number);
		return new THREE.Vector3(x,y,z);
	}

	set(index: THREE.Vector3, value: ChunkedObject) {
		this.chunkMap.set(this.coordToKey(index), value);
	}

	setByPosition(position: THREE.Vector3, value: ChunkedObject) {
		this.set(this.positionToChunkIndex(position), value);
	}

	get(index: THREE.Vector3): ChunkedObject | undefined {
		return this.chunkMap.get(this.coordToKey(index));
	}

	getByPosition(position: THREE.Vector3) {
		return this.get(this.positionToChunkIndex(position));
	}

	exists(index: THREE.Vector3): boolean {
		return Boolean(this.get(index));
	}

	existsByPosition(position: THREE.Vector3) {
		return this.exists(this.positionToChunkIndex(position));
	}

	entries(): Chunked3DEntry<ChunkedObject>[] {
		return Array.from(this.chunkMap.entries()).map(([key, value]) => ({
			key: this.keyToCoord(key),
			value
		}));
	}
}
