import * as THREE from 'three';
import Engine from "./lib/core/Engine.js";
import sources from "./config/resources.config.js";
import Resources from "./lib/core/Resources.js";
import { Lensflare, LensflareElement } from 'three/addons/objects/Lensflare.js';
import EventEmitter from "./lib/utils/EventEmitter.js";
import Random from "./lib/utils/Random.js";
import gsap from "gsap";
import config from "./config/Conf.js";

type TweakValues = {
	sunColor: string,
	sunIntensity: number,
}

type LightParams = {
	engine: Engine,
	initialTweaks: TweakValues,
	resources: Resources<typeof sources>
}

function flicker(light: THREE.PointLight) {
	const nextIntensity = Random.between(10, 20);
	const nextDuration = Random.between(0.1, 0.25);

	gsap.to(light, {
		intensity: nextIntensity,
		duration: nextDuration,
		ease: 'power1.inOut',
		onComplete: () => flicker(light)
	});
}

export default class Light extends EventEmitter{
	private readonly engine: Engine;
	private readonly tweakValues: TweakValues;
	private readonly resources: Resources<typeof sources>;

	private mainLight!: THREE.DirectionalLight;
	private lensflare!: Lensflare;
	private sunAnchor!: THREE.Object3D;

	constructor(
		{
			engine,
			resources,
			initialTweaks,
		}: LightParams
	) {
		super();

		this.tweakValues = initialTweaks;
		this.engine    = engine;
		this.resources = resources;

		this.init();
		this.configureTweaks();
		this.engine.on(
			'global:config:changed',
			(event) => this.configChanged(event?.detail?.config),
		);
	}

	private configChanged(conf: typeof config) {
		if (!conf) return;

		if (conf.scene.light.sunColor) {
			this.changeSunColor(conf.scene.light.sunColor);
		}

		if (conf.scene.light.lensflare) {
			this.lensflare.visible = conf.scene.light.lensflare.enabled;
		}
	}

	private changeSunColor(color: string) {
		if (!this.mainLight) return;

		this.mainLight.color = new THREE.Color(color);
	}

	private changeSunIntensity(intensity: number) {
		if (!this.mainLight) return;

		this.mainLight.intensity = intensity;
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Scene.Light',
				sunColor: {
					params: {
						type: 'color',
					},
					onChange: this.changeSunColor.bind(this),
				},
				sunIntensity: {
					params: {
						type: 'number',
						min: 0,
						max: 10,
						step: 0.1,
					},
					onChange: this.changeSunIntensity.bind(this),
				}
			}
		)
	}

	get light(): THREE.DirectionalLight {
		return this.mainLight;
	}

	private init() {
		this.resources.onceAll(
			[
				'loaded:lensFlare0',
				'loaded:lensFlare1',
			],
			() => {
				this.initLights();
				this.emit('ready');
			}
		)
	}

	private initLights() {
		const mainLightPosition = (
			new THREE.Vector3(-47, 40, 0)
		);

		this.mainLight = new THREE.DirectionalLight(
			this.tweakValues.sunColor,
			this.tweakValues.sunIntensity,
		);
		this.mainLight.position.copy(mainLightPosition);
		this.mainLight.target.position.set(0, 0, 0);
		this.mainLight.castShadow = true;

		const d = 50;
		this.mainLight.shadow.mapSize.set(2048, 2048);
		this.mainLight.shadow.camera.left = -d;
		this.mainLight.shadow.camera.right = d + 5.5;
		this.mainLight.shadow.camera.top = d - 4;
		this.mainLight.shadow.camera.bottom = -d + 3;
		this.mainLight.shadow.camera.near = 0;
		this.mainLight.shadow.camera.far = 100;
		this.mainLight.shadow.autoUpdate = false;

		// this.mainLight.shadow.radius = 3
		// this.mainLight.shadow.blurSamples = 4

		let pointLight = new THREE.PointLight('#ff6a00', 20, 3, 4);
		pointLight.position.set(3.1, 0.35, -0.4);
		flicker(pointLight);

		this.engine.scene.add(pointLight);

		// const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.1);
		// this.engine.scene.add(pointLightHelper);

		this.initLensFlare();

		this.engine.scene.add(this.mainLight);
		this.engine.scene.add(this.mainLight.target);
	}

	public get mainLightDirection(): THREE.Vector3 {
		return this.mainLight.position.clone().sub(
			this.mainLight.target.position,
		).normalize();
	}

	public get mainLightColor(): THREE.Color {
		return this.mainLight.color;
	}

	private initLensFlare() {
		this.sunAnchor = new THREE.Object3D();
		this.sunAnchor.position.copy(this.mainLight.position);

		const textureFlare0 = this.resources.items.lensFlare0;
		const textureFlare3 = this.resources.items.lensFlare1;

		this.lensflare = new Lensflare();
		this.lensflare.layers.enable(1);
		this.lensflare.addElement( new LensflareElement( textureFlare0, 700, 0, this.mainLight.color ) );
		this.lensflare.addElement( new LensflareElement( textureFlare3, 60, 0.6 ) );
		this.lensflare.addElement( new LensflareElement( textureFlare3, 70, 0.7 ) );
		this.lensflare.addElement( new LensflareElement( textureFlare3, 120, 0.9 ) );
		this.lensflare.addElement( new LensflareElement( textureFlare3, 70, 1 ) );

		this.sunAnchor.add(this.lensflare);
		this.sunAnchor.frustumCulled = false;
		this.engine.scene.add(this.sunAnchor);
	}

	updateShadows() {
		if (!this.mainLight) return;

		this.mainLight.shadow.needsUpdate = true;
	}

	update() {
		if (!this.sunAnchor) return;

		const camera = this.engine.camera.instance;
		const sunDir = this.mainLight.position.clone().normalize();

		const distance = 30;
		this.sunAnchor.position.copy(camera.position).add(sunDir.multiplyScalar(distance));
	}

	destroy() {
		this.mainLight?.dispose();
		this.lensflare?.dispose();
	}
}