import * as THREE from "three";
import {FpsMetrics} from "./Perfs.js";
import Graph from "./graph/Graph.js";
import PerfsGuiCapabilities from "./PerfsGuiCapabilities.js";

export default class PerfsGui implements PerfsGuiCapabilities {
	private readonly parent         : HTMLElement;
	private readonly state          : Record<string, number>;
	private readonly updateInterval : number;

	private enabled!   : boolean;
	private lastUpdate : number;
	private	graph!     : Graph;

	constructor(
		{
			parent,
			enabled
		}: {
			parent  : HTMLElement,
			enabled : boolean
		}
	) {
		this.parent         = parent;
		this.lastUpdate     = performance.now();
		this.updateInterval = 200;

		this.parent.classList.add('stats');

		this.state = {
			fps            : 0,
			cpu            : 0,
			gpu            : 0,
			lines          : 0,
			points         : 0,
			shaders        : 0,
			textures       : 0,
			triangles      : 0,
			geometries     : 0,
			draw_calls     : 0,
			time_per_frame : 0,
		};

		this.initDetailedInfosPanel();

		if (enabled) {
			this.enable();
		}
	}

	enable() {
		this.enabled = true;
		this.parent.classList.remove('hidden');
	}

	disable() {
		this.enabled = false;
		this.parent.classList.add('hidden');
	}

	toggleMode() {
		if (this.parent.classList.contains('expanded')) {
			this.parent.classList.remove('expanded');
		} else {
			this.parent.classList.add('expanded');
		}
	}

	private initDetailedInfosPanel() {
		const parent = this.parent;

		this.parent.classList.add('expanded');

		parent.addEventListener('click', () => {
			this.toggleMode();
		});

		this.insertNumber(parent, { key: 'geometries' });
		this.insertNumber(parent, { key: 'textures'   });
		this.insertNumber(parent, { key: 'shaders'    });
		this.insertNumber(parent, { key: 'lines'      });
		this.insertNumber(parent, { key: 'points'     });
		this.insertNumber(parent, { key: 'triangles'  });
		this.insertNumber(parent, { key: 'fps'        });

		this.insertNumber(parent, { key: 'cpu'           , label: 'Cpu (ms)'});
		this.insertNumber(parent, { key: 'gpu'           , label: 'Gpu (ms)'});
		this.insertNumber(parent, { key: 'time_per_frame', label: 'Frame (ms)' });
		this.insertNumber(parent, { key: 'draw_calls'    , label: 'Draw calls' });

		this.graph = new Graph(parent);
		this.graph.addCurve('fps', '#ff0000', 60);
		this.graph.addCurve('cpu', '#00ff00', 10);
		this.graph.addCurve('gpu', '#ffae00', 10);
	}

	private insertNumber(
		parent: HTMLElement,
		{
			key,
			label,
		}: {
			key: string,
			label?: string,
		}
	) {
		const div = document.createElement('div');
		div.classList.add('number');
		div.dataset.key    = key;
		div.style.gridArea = key;

		const labelDiv = document.createElement('div');
		labelDiv.className = 'label';
		labelDiv.innerText = label ?? key;

		const valueSpan = document.createElement('span');
		valueSpan.innerText = '0';

		const valueDiv = document.createElement('div');
		valueDiv.className = 'value';
		valueDiv.appendChild(valueSpan);

		div.appendChild(labelDiv);
		div.appendChild(valueDiv);

		parent.appendChild(div);
	}

	private updateNumber(key: string, value: number | string) {
		if (!(key in this.state)) {
			throw new Error(`Perf key ${key} not found !`);
		}

		if (this.state[key] === value) {
			return;
		}

		const numberValueElement = this.parent.querySelector(`[data-key=${key}] .value`);

		if (!numberValueElement) {
			throw new Error(`Perf element ${key} to update not found !`);
		}

		numberValueElement.innerHTML = value.toString();
	}

	private fixTo(nb: number, precision?: number) {
		return nb.toFixed(precision ?? 4);
	}

	update(info: THREE.WebGLInfo, fpsStats: FpsMetrics) {
		if (!this.enabled) return;

		const now = performance.now();
		if (now - this.lastUpdate < this.updateInterval) return;

		this.lastUpdate = now;

		this.updateNumber('geometries', info.memory.geometries    );
		this.updateNumber('textures',   info.memory.textures      );
		this.updateNumber('shaders',    info.programs?.length ?? 0);
		this.updateNumber('draw_calls', info.render.calls         );
		this.updateNumber('lines',      info.render.lines         );
		this.updateNumber('points',     info.render.points        );
		this.updateNumber('triangles',  info.render.triangles     );

		this.updateNumber('fps',            Math.round(fpsStats.fps));
		this.updateNumber('cpu',            this.fixTo(fpsStats.cpuTimePerFrame, 3));
		this.updateNumber('gpu',            this.fixTo(fpsStats.gpuTimePerFrame, 3));
		this.updateNumber('time_per_frame', this.fixTo(fpsStats.fullFrameTime, 2));

		this.graph.push('fps', fpsStats.fps            );
		this.graph.push('gpu', fpsStats.gpuTimePerFrame);
		this.graph.push('cpu', fpsStats.cpuTimePerFrame);

		this.graph.render();
	}

	destroy() {
		this.graph.destroy();
		this.parent.remove();
	}
}