import * as THREE from "three";
import Experience from "../Experience.js";
import {Object3D} from "three";
import EventEmitter from "../lib/utils/EventEmitter.js";
import { EVENTS as CAMERA_SPOTS_EVENTS } from '../CameraSpots.js';
import HomeSection, { EVENTS as HOME_SECTION_EVENTS } from "./HomeSection.js";
import MainMenu, {EVENTS as MAIN_MENU_EVENTS} from "./MainMenu.js";

export enum EVENTS {
	REACHED = "ViewPoints:reached",
}

export default class ViewPoints extends EventEmitter {
	private readonly experience: Experience;
	private readonly pointTemplate: HTMLTemplateElement;
	private readonly points: Record<string, HTMLDivElement>;
	private readonly position: THREE.Vector3;
	private readonly raycaster: THREE.Raycaster;
	private readonly homeSection: HomeSection;
	private readonly mainMenu: MainMenu;
	private readonly viewPointsProgress: HTMLDivElement;
	private readonly viewPointsProgressText: HTMLSpanElement;

	private occluder!: Object3D;
	private hintContainer: HTMLDivElement;
	private hasSelectedPoint = false;
	private hintTarget = new THREE.Vector2();
	private hintCurrent = new THREE.Vector2();
	private hintLerpFactor = 0.2;
	private hintCanBeShown = false;
	private visitedCount = 1;

	constructor(
		experience: Experience,
		homeSection: HomeSection,
		mainMenu: MainMenu,
	) {
		super();
		this.homeSection = homeSection;
		this.experience = experience;
		this.mainMenu = mainMenu;
		this.pointTemplate = document.getElementById('point-template')! as HTMLTemplateElement;
		this.points = {};
		this.position = new THREE.Vector3();
		this.raycaster = new THREE.Raycaster();

		this.viewPointsProgress = document.querySelector('.viewpoints-progress') as HTMLDivElement;
		this.viewPointsProgressText = document.querySelector('.viewpoints-progress span') as HTMLSpanElement;
		this.hintContainer = document.querySelector('.explore-hint') as HTMLDivElement;

		this.init();
	}

	private updateVisitedCount() {
		this.viewPointsProgressText.innerText = `${this.visitedCount}/${Object.values(this.points).length}`;
	}

	private createPoints() {
		const root = document.getElementById('home')!;

		Object.entries(this.experience.cameraSpots.points).forEach(([key, value], i) => {
			// @ts-ignore
			if (value.invisible) return;

			const point = this.pointTemplate.content.cloneNode(true) as DocumentFragment;
			const pointElement = point.querySelector('.circle-container') as HTMLDivElement;

			if (i === 0) {
				pointElement.classList.add('current', 'visited');
			}

			this.points[key] = pointElement;
			root.appendChild(point);

			pointElement.addEventListener('click', (e) => {
				e.stopPropagation();

				this.hasSelectedPoint = true;

				if (!pointElement.classList.contains('visited')) {
					this.visitedCount++;
					this.updateVisitedCount();
				}

				pointElement.classList.add('visited');

				Object.values(this.points).forEach((point) => {
					point.classList.remove('current');
				});

				this.experience.cameraSpots.goTo(key as keyof typeof this.experience.cameraSpots.points, {
					onComplete: () => {
						this.emit(EVENTS.REACHED, new CustomEvent(
							EVENTS.REACHED,
							{ detail: { point: key } },
						));

						this.points[key].classList.add('current');

						this.hintContainer.classList.add('hidden');
					},
				});
			});
		});

		this.updateVisitedCount();
	}

	private isPointOccluded(pointWorldPosition: THREE.Vector3): boolean {
		const cameraPosition = this.experience.engine.camera.instance.position;

		const direction = new THREE.Vector3()
			.subVectors(pointWorldPosition, cameraPosition)
			.normalize();

		const distanceToPoint = cameraPosition.distanceTo(pointWorldPosition);

		this.raycaster.set(cameraPosition, direction);
		this.raycaster.far = distanceToPoint - 0.1;

		const intersections = this.raycaster.intersectObjects([this.occluder]);

		return intersections.length > 0;
	}

	private init() {
		this.createPoints();

		this.mainMenu.on(MAIN_MENU_EVENTS.CHOOSED_CONTACT, () => {
			const contactPoint = Object.values(this.points)[1];

			if (contactPoint.classList.contains('visited')) {
				return;
			}

			Object.values(this.points)[1].classList.add('visited');
			this.visitedCount++;
			this.updateVisitedCount();
			this.hasSelectedPoint = true;
			this.hintContainer.classList.remove('show');
		});

		this.homeSection.on(HOME_SECTION_EVENTS.LOOK_AROUND_HINT_HIDDEN, () => {
			setTimeout(() => {
				this.hintContainer.classList.add('show');
				this.hintCanBeShown = true;
				this.viewPointsProgress.classList.remove('hidden');
			}, 1000);
		});

		this.experience.cameraSpots.on(CAMERA_SPOTS_EVENTS.TRAVEL_STARTED, () => {
			this.experience.world.islands.clouds?.disableSorting();
		});

		this.experience.cameraSpots.on(CAMERA_SPOTS_EVENTS.TRAVEL_ENDED, () => {
			this.experience.world.islands.clouds?.enableSorting();
			this.experience.world.islands.clouds?.sort();
		});

		this.experience.resources.once('loaded:testIsland', () => {
			this.occluder = this.experience.world.islands.simplifiedScene;

			this.experience.engine.time.on('tick', () => {
				let closestPoint: { x: number; y: number; dist: number } | null = null;

				Object.entries(this.points).forEach(([key, point]) => {
					if (point.classList.contains('current')) return;

					const { position } = this.experience.cameraSpots.points[key as keyof typeof this.experience.cameraSpots.points];

					const distance = this.experience.engine.camera.instance.position.distanceTo(position);
					if (distance > 20) {
						point.classList.add('too-far');
						return;
					}

					const isOccluded = this.isPointOccluded(position);

					this.position.copy(position);
					this.position.project(this.experience.engine.camera.instance);

					const isVisible =
						this.position.z > 0 && this.position.z < 1 &&
						this.position.x >= -1 && this.position.x <= 1 &&
						this.position.y >= -1 && this.position.y <= 1;

					if (!isVisible || isOccluded) {
						point.classList.add('occluded');
						return;
					}

					point.classList.remove('occluded');
					point.classList.remove('too-far');

					const translateX = (this.position.x * 0.5 + 0.5) * this.experience.engine.sizes.width;
					const translateY = (-this.position.y * 0.5 + 0.5) * this.experience.engine.sizes.height;

					const baseScale = 1.0;
					const referenceDistance = 10;
					const minScale = 0.1;
					const maxScale = 2.0;

					const scale = THREE.MathUtils.clamp(
						baseScale * (referenceDistance / distance),
						minScale,
						maxScale
					);

					point.style.transform = `translate(${translateX}px, ${translateY}px) scale(${scale})`;

					// SCREEN-WISE distance to center
					const dx = this.position.x;
					const dy = this.position.y;
					const distToCenter = Math.sqrt(dx * dx + dy * dy);

					if (!closestPoint || distToCenter < closestPoint.dist) {
						closestPoint = { x: translateX, y: translateY, dist: distToCenter };
					}
				});

				if (!this.hasSelectedPoint && closestPoint) {
					if (this.hintCanBeShown) {
						this.hintContainer.classList.add('show');
					}

					this.hintTarget.set(closestPoint.x + 20, closestPoint.y);

					this.hintCurrent.lerp(this.hintTarget, this.hintLerpFactor);

					this.hintContainer.style.transform = `translate(${this.hintCurrent.x}px, ${this.hintCurrent.y}px)`;
				} else {
					this.hintContainer.classList.remove('show');
				}
			});
		});
	}
}
