import TweaksCapabilities, {ConfigOptions} from "./TweaksCapabilities.js";
import EventBusCapabilities from "../core/events/EventBusCapabilities.js";
import Tweaks from "./Tweaks.js";

export default class TweaksBridge implements TweaksCapabilities {
	public static configure() {
		const tweaks = new Tweaks();

		self.window.addEventListener('tweaks:update', () => {
			tweaks.update();
		});

		self.window.addEventListener('tweaks:destroy', () => {
			tweaks.destroy();
		});

		self.window.addEventListener('tweaks:configure', (event) => {
			const customEvent = event as CustomEvent<{
				params: Record<string, any>,
				options: ConfigOptions<any>
			}>;

			const { params, options } = customEvent.detail;
			const { folder, ...bindings } = options;

			Object.entries(bindings ?? {}).forEach(([key, binding]) => {
				if (binding?.onChange) {
					binding.onChange = (value) => {
						self.window.dispatchEvent(new CustomEvent(
							'tweaks:change',
							{
								detail: {
									key: `${folder}:${key}`,
									value,
								},
							},
						));
					};
				}
			});

			tweaks.configure(params, options);
		});
	}

	private readonly eventBus: EventBusCapabilities;
	private readonly listeners: Record<string, (value: unknown) => void>;

	constructor(eventBus: EventBusCapabilities) {
		this.eventBus  = eventBus;
		this.listeners = {};

		eventBus.subscribe('window', 'tweaks:change', (event: unknown) => {
			const customEvent = event as CustomEvent;
			const { key, value } = customEvent.detail;

			if (!(key in this.listeners)) {
				throw new Error(`Unknown property update on key ${key} with value ${JSON.stringify(value)}`);
			}

			this.listeners[key](value);
		});
	}

	configure<T extends Record<string, unknown>>(
		params: T,
		{
			folder,
			...bindingParams
		}: ConfigOptions<T> = {}
	): void {
		Object.entries(bindingParams).forEach(([key, config]) => {
			if (typeof config.onChange === 'function') {
				this.listeners[`${folder}:${key}`] = config.onChange;
				config.onChange = true;
			}
		});

		this.eventBus.dispatch('window', 'tweaks:configure', {
			params,
			options: {
				folder,
				...bindingParams,
			},
		});
	}

	update(): void {
		this.eventBus.dispatch('window', 'tweaks:update');
	}

	destroy(): void {
		this.eventBus.dispatch('window', 'tweaks:destroy');
	}
}