import * as THREE from 'three';
import sources from "../../config/resources.config.js"
import Resources from "../../lib/core/Resources.js";
import Engine from "../../lib/core/Engine.js";
import GrassField from "../grassField/GrassField.js";
import Cliffs from "./Cliffs.js";
import Waterfalls from "./waterfalls/Waterfalls.js";
import MainWater from "./water/MainWater.js";
import Environment from '../../environment/Environment.js';
import Trees from "./trees/Trees.js";
import Foliage from "./foliage/Foliage.js";
import BasaltRocks from "./BasaltRocks.js";
import Swarm, { SWARM_EVENTS as SWARM_EVENTS } from "./swarm/Swarm.js";
import Light from "../../Light.js";
import Campfire from "./campfire/Campfire.js";
import Clouds from "../clouds/Clouds.js";
import {ExperienceAudioItems} from "../../AudioItems.js";
import config from "../../config/Conf.js";

type TweakValues = {
	scale: number,
}

type IslandsParams = {
	engine        : Engine<ExperienceAudioItems>,
	light         : Light,
	group         : THREE.Group,
	environment   : Environment,
	resources     : Resources<typeof sources>,
	initialTweaks : TweakValues,
}

export default class MainIslands {
	private readonly engine      : Engine<ExperienceAudioItems>;
	private readonly group       : THREE.Group;
	private readonly resources   : Resources<typeof sources>;
	private readonly tweakValues : TweakValues;
	private readonly environment : Environment;

	private light!              : Light;
	private islands!            : THREE.Group;
	private grassFieldGeometry! : THREE.BufferGeometry;
	private grassField!         : GrassField;
	private cliffs!             : Cliffs;
	private waterfalls!         : Waterfalls;
	private mainWater!          : MainWater;
	private trees!              : Trees;
	private foliage!            : Foliage;
	private basalt!             : BasaltRocks;
	private campfire!           : Campfire;

	public clouds!              : Clouds;
	public swarm!               : Swarm;
	public simplifiedScene!     : THREE.Object3D;

	constructor(
		{
			group,
			light,
			engine,
			resources,
			environment,
			initialTweaks,
		}: IslandsParams
	) {
		this.light     = light;
		this.group     = group;
		this.engine    = engine;
		this.resources = resources;
		this.environment = environment;
		this.tweakValues  = initialTweaks;

		this.init();
		this.configureTweaks();
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Islands',
				scale: {
					onChange: () => {
						console.warn('Scale change not implemented yet');
					}
				}
			}
		);
	}

	private init() {
		this.resources.onceAll(
			[
				'loaded:testIsland',
				'loaded:cliffsColor',
				'loaded:cliffsAo',
				'loaded:cliffsNormal',
			],
			() => {
				this.islands = this.resources.items.testIsland.scene.children[0].children[0] as THREE.Group;

				this.islands.scale.set(
					this.tweakValues.scale,
					this.tweakValues.scale,
					this.tweakValues.scale,
				);

				this.initClouds();
				this.initCliffs();
				this.initBasaltRocks();
				this.initWaterfalls();
				this.initMainWater();
				this.initTrees();
				this.initFoliage();
				this.initCampfire();
				this.initSwarm();
				this.initGrassField();

				this.group.add(this.islands);

				this.islands.traverse((obj) => {
					if(
						obj instanceof THREE.Mesh
						&& obj.name.startsWith('godrays-occluder')
					) {
						obj.position.z = 0.8;
						obj.castShadow = true;
						obj.material.side = THREE.BackSide;
						obj.material.depthWrite = false;
						obj.material.colorWrite = false;
					}  else if( obj.name === 'simplified-scene-occluder') {
						this.simplifiedScene = obj;
					}
				});

				this.engine.monitor.on('decline', (event) => {
					const declineLevel = event?.detail?.declineLevel;
					if (!declineLevel) return;

					switch(declineLevel) {
						case 4:
							this.recreateSwarm();
							break;
					}
				});
			},
		);
	}

	private recreateSwarm() {
		console.warn('Islands: Low fps detected. Recreating Swarm with fewer particles.');
		this.swarm.destroy();
		this.initSwarm({
			...config.islands.swarm,
			count: 160,
			particlesSize: config.islands.swarm.particlesSize * 3.0,
		});
	}

	private initClouds() {
		this.clouds = new Clouds({
			engine: this.engine,
			resources: this.resources,
			islands: this.islands,
			initialTweaks: config.clouds,
		});
	}

	private initFoliage() {
		this.foliage = new Foliage({
			group         : this.islands,
			engine        : this.engine,
			resources     : this.resources,
			initialTweaks : config.islands.foliage,
		});
	}

	private initTrees() {
		this.trees = new Trees({
			engine    : this.engine,
			resources : this.resources,
			group     : this.islands,
		});
	}

	private initGrassField() {
		this.extractGrassFieldGeometry();
		this.grassField = new GrassField({
			group     : this.group,
			engine    : this.engine,
			resources : this.resources,
			geometry  : this.grassFieldGeometry,
			islands   : this.islands,
			initialTweaks : this.tweakValues,
		});
	}

	private initWaterfalls() {
		this.waterfalls = new Waterfalls({
			group     : this.islands,
			engine    : this.engine,
			resources : this.resources,
			initialTweaks : config.islands.waterfalls,
		});
	}

	private initMainWater() {
		this.mainWater = new MainWater({
			group  : this.islands,
			engine : this.engine,
			resources : this.resources,
			initialTweaks : config.islands.water,
		});
	}

	private extractGrassFieldGeometry() {
		let mesh: THREE.Mesh;

		this.islands.traverse((child) => {
			if (child.name !== 'main-island-grass-surface') return;

			this.grassFieldGeometry = (child as THREE.Mesh).geometry;
			mesh = child as THREE.Mesh;
		});

		this.grassFieldGeometry.scale(
			this.tweakValues.scale,
			this.tweakValues.scale,
			this.tweakValues.scale,
		);

		mesh!.removeFromParent();
	}

	private initCliffs() {
		this.cliffs = new Cliffs({
			engine      : this.engine,
			resources   : this.resources,
			environment : this.environment,
			group       : this.islands,
		});
	}

	private initBasaltRocks() {
		this.basalt = new BasaltRocks({
			engine: this.engine,
			islands: this.islands,
			initialTweaks: config.islands.basalRocks,
		});
	}

	private initSwarm(conf?: typeof config.islands.swarm) {
		this.swarm = new Swarm({
			engine: this.engine,
			islands: this.islands,
			resources: this.resources,
			light : this.light,
			initialTweaks: conf ?? config.islands.swarm,
		});

		this.swarm.on(SWARM_EVENTS.EXPLODE, () => {
			this.basalt?.throwFloatingRocksAway();
		});

		this.swarm.on(SWARM_EVENTS.EXPLOSIVENESS_CHANGE, (event) => {
			this.basalt?.changeFloatingRocksSpeed(event?.detail?.normalized);
		});

		this.basalt?.changeFloatingRocksSpeed(this.swarm.normalizedExplosiveness);
	}

	private initCampfire() {
		this.campfire = new Campfire({
			engine: this.engine,
			islands: this.islands,
			resources: this.resources,
		});
	}

	update() {
		this.grassField?.update();
		this.waterfalls?.update();
		this.mainWater?.update();
		this.trees?.update();
		this.foliage?.update();
		this.basalt?.update();
		this.swarm?.update();
		this.campfire?.update();
		this.clouds?.update();
	}

	destroy() {
		this.grassField?.destroy();
		this.grassFieldGeometry?.dispose();
		this.cliffs?.destroy();
		this.waterfalls?.destroy();
		this.mainWater?.destroy();
		this.trees?.destroy();
		this.foliage?.destroy();
		this.basalt?.destroy();
		this.swarm?.destroy();
		this.campfire?.destroy();
		this.clouds?.destroy();
	}
}