import {SizesType} from "../core/Sizes.js";

export function isWindowAvailable(): boolean {
	return Boolean(self.window);
}

export function getSizesRelatedInfo(): SizesType | null {
	if (isWindowAvailable()) {
		return {
			width: window.innerWidth,
			height: window.innerHeight,
			devicePixelRatio: window.devicePixelRatio,
		};
	}

	return null;
}

export type ResizeEventListenerData = {
	height: number,
	width: number,
	devicePixelRatio: number,
}

export function addSizesPropertiesToEvent(event: Event): ResizeEventListenerData {
	const sizes = getSizesRelatedInfo();
	const result = event as Event & ResizeEventListenerData;

	if (sizes) {
		result.width = sizes.width;
		result.height = sizes.height;
		result.devicePixelRatio = sizes.devicePixelRatio;
	}

	return result;
}
