import Engine from "../core/Engine.js";
import * as THREE from "three";

export default class ParallaxEffect {
	private readonly engine: Engine;
	private readonly currentCameraDirection: THREE.Vector3;
	private readonly currentCameraRight: THREE.Vector3;
	private readonly currentCameraUp: THREE.Vector3;
	private readonly cameraGroupOffset: THREE.Vector3;
	private enabled: boolean;

	constructor(engine: Engine) {
		this.engine = engine;

		this.enabled = true;
		this.currentCameraDirection = new THREE.Vector3();
		this.currentCameraRight = new THREE.Vector3();
		this.cameraGroupOffset = new THREE.Vector3();
		this.currentCameraUp = new THREE.Vector3();
	}

	enable() {
		this.enabled = true;
	}

	disable() {
		this.enabled = false;
	}

	update() {
		if (!this.enabled) {
			return;
		}

		this.engine.camera.instance.getWorldDirection(this.currentCameraDirection);
		this.currentCameraRight.crossVectors(this.currentCameraDirection, this.engine.camera.instance.up);
		this.currentCameraUp.copy(this.engine.camera.instance.up).normalize();

		this.cameraGroupOffset
			.set(0,0,0)
			.addScaledVector(this.currentCameraRight, -this.engine.pointer.normalizedPosition.x * 0.05)
			.addScaledVector(this.currentCameraUp, -this.engine.pointer.normalizedPosition.y * 0.05);

		this.engine.camera.group.position.lerp(this.cameraGroupOffset, 0.1);
	}
}