import * as THREE from 'three';
import Engine from "../lib/core/Engine.js";
import Resources from "../lib/core/Resources.js";
import sources from "../config/resources.config.js";
import config from "../config/Conf.js";

type EnvironmentMap = {
	intensity: number,
	texture: THREE.Texture,
	background?: string,
	backgroundIntensity: number,
	map: 'environmentMap' | 'nightEnvironmentMap',
}

type EnvironmentParams = {
	group     : THREE.Group,
	engine    : Engine,
	resources : Resources<typeof sources>
}

export default class Environment {
	private readonly group           : THREE.Group;
	private readonly engine          : Engine;
	private readonly resources       : Resources<typeof sources>;
	private readonly environmentMap! : EnvironmentMap;

	private mesh!: THREE.Mesh<THREE.BufferGeometry, THREE.MeshBasicMaterial>;

	constructor(
		{
			engine,
			resources,
			group,
		}: EnvironmentParams,
	) {
		this.group     = group;
		this.engine    = engine;
		this.resources = resources;
		this.environmentMap = {
			background : '',
			map: config.scene.environment.map,
			intensity  : config.scene.environment.intensity,
			backgroundIntensity : config.scene.environment.backgroundIntensity,
		} as EnvironmentMap;

		this.initEnvironmentMap();
		this.configureTweaks();

		this.engine.on(
			'global:config:changed',
			(event) => {
				const config = event?.detail?.config;
				if (!config) return;

				this.configChanged(config);
			}
		)
	}

	private configChanged(conf: typeof config) {
		if (!conf) return;

		if (conf.scene.environment.intensity) {
			this.environmentMap.intensity = conf.scene.environment.intensity;
		}

		if (conf.scene.environment.backgroundIntensity) {
			this.environmentMap.backgroundIntensity = conf.scene.environment.backgroundIntensity;
			this.engine.scene.backgroundIntensity = conf.scene.environment.backgroundIntensity;
		}

		if (conf.scene.environment.map) {
			this.environmentMap.map = conf.scene.environment.map;
			this.engine.scene.background = this.resources.items[conf.scene.environment.map];
			// this.engine.scene.environment = this.resources.items[conf.scene.environment.map];
			this.environmentMap.texture = this.resources.items[conf.scene.environment.map];
		}

		this.updateMaterials();
	}

	private configureTweaks() {
		this.tweaks.configure(
			this.environmentMap,
			{
				folder: 'Scene',
				intensity: {
					params: {
						min: 0,
						max: 10,
						step: 0.1,
					},
					onChange: (value: number) => {
						this.engine.scene.environmentIntensity = value;
						this.updateMaterials();
					},
				},
				backgroundIntensity: {
					params: {
						min: 0,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						this.engine.scene.backgroundIntensity = value;
						this.updateMaterials();
					}
				}
			},
		);
	}

	initEnvironmentMap(): void {
		this.resources.on('loaded:environmentMap', () => {
			this.environmentMap.texture = this.resources.items[this.environmentMap.map];

			this.lightSceneWithEnvironmentMap();
		});
	}

	private lightSceneWithEnvironmentMap(): void {
		this.engine.scene.environment = this.environmentMap.texture;

		this.engine.scene.background = this.environmentMap.texture;
		this.engine.scene.backgroundIntensity = this.environmentMap.backgroundIntensity;
		this.engine.scene.backgroundRotation.set(0, Math.PI * 0.11, 0);
		this.engine.scene.environmentRotation.copy(this.engine.scene.backgroundRotation);
		this.updateMaterials();
	}

	public updateMaterials() {
		this.engine.scene.traverse((child) => {
			if(this.childIsAffectedByEnvironment(child)) {
				if (child.material instanceof THREE.ShaderMaterial) {
					// For custom shader materials, update the uniforms directly
					if (child.material.uniforms.envMap) {
						console.log(child);
						child.material.uniforms.envMap.value = this.environmentMap.texture;
					}
					if (child.material.uniforms.envMapIntensity) {
						child.material.uniforms.envMapIntensity.value = this.environmentMap.intensity;
					}
					if (child.material.uniforms.flipEnvMap) {
						child.material.uniforms.flipEnvMap.value = -1; // or 1 depending on your setup
					}
				} else {
					// For standard materials
					child.material.envMap = this.engine.scene.environment;
					child.material.envMapIntensity = this.environmentMap.intensity;
					child.material.envMapRotation = this.engine.scene.environmentRotation;
				}
				child.material.needsUpdate     = true;
			}
		});
	}

	private childIsAffectedByEnvironment(child: any): child is THREE.Mesh<any, THREE.MeshStandardMaterial> {
		return (
					child.material
					&& (
						child.material instanceof THREE.MeshStandardMaterial
						|| child.material instanceof THREE.MeshPhysicalMaterial
						|| child.material instanceof THREE.MeshPhongMaterial
						|| child.material instanceof THREE.ShaderMaterial
						|| ('USE_ENVMAP' in (child.material.defines ?? {}))
					)
			);
	}

	private get tweaks() {
		return this.engine.tweaks;
	}

	update() {}

	destroy() {
		if (!this.mesh) return;

		this.group.remove(this.mesh);
		this.mesh.material.dispose();
		this.mesh.geometry.dispose();
	}
}