import * as THREE from "three";
import Sizes from "./Sizes.js";

export default class Pointer {
	private readonly sizes: Sizes;

	public readonly screenPosition: THREE.Vector2;
	public readonly normalizedPosition: THREE.Vector2;

	constructor(sizes: Sizes) {
		this.sizes = sizes;
		this.screenPosition = new THREE.Vector2();
		this.normalizedPosition = new THREE.Vector2();

		this.init();
	}

	private init() {
		const isMouseDevice = window.matchMedia("(hover: hover) and (pointer: fine)").matches;

		if (!isMouseDevice) {
			return;
		}

		document.addEventListener('pointermove', (event) => {
			this.screenPosition.x = event.clientX;
			this.screenPosition.y = event.clientY;

			this.normalizedPosition.x = (event.clientX / this.sizes.width - 0.5) * 2;
			this.normalizedPosition.y = -(event.clientY / this.sizes.height - 0.5) * 2;
		});
	}
}