import {BufferGeometry, Texture} from "three";
import * as THREE from "three";

export const CHANNEL_TO_INDEX_MAP = {
	r: 0,
	g: 1,
	b: 2,
	a: 3,
};

export type RGBAChannel = 'r' | 'g' | 'b' | 'a';

export default class TextureUtils {
	static getImageDataFromTexture(texture: Texture) {
		// Assuming texture.image is an HTMLImageElement, ImageBitmap, or Canvas
		const canvas = typeof OffscreenCanvas !== "undefined"
			? new OffscreenCanvas(texture.image.width, texture.image.height)
			: document.createElement('canvas');

		canvas.width = texture.image.width;
		canvas.height = texture.image.height;

		const ctx = canvas.getContext('2d');
		ctx.drawImage(texture.image, 0, 0);
		return ctx.getImageData(0, 0, canvas.width, canvas.height);
	}

	static getBrightnessAtUV(
		imageData: ImageData,
		u: number,
		v: number,
		channel: RGBAChannel,
	) {
		const x = Math.floor(u * (imageData.width - 1));
		const y = Math.floor((1 - v) * (imageData.height - 1)); // Flip Y for canvas coords

		const offset = (y * imageData.width + x) * 4;

		return imageData.data[offset + CHANNEL_TO_INDEX_MAP[channel]] / 255;
	}

	static createVertexWeightsFromTexture(
		geometry: BufferGeometry,
		imageData: ImageData,
		channel: RGBAChannel,
	) {
		const uvs = geometry.attributes.uv.array;
		const count = geometry.attributes.position.count;
		const weights = new Float32Array(count);

		for (let i = 0; i < count; i++) {
			const u = uvs[i * 2];
			const v = uvs[i * 2 + 1];
			weights[i] = TextureUtils.getBrightnessAtUV(imageData, u, v, channel);
		}

		return new THREE.Float32BufferAttribute(weights, 1);
	}

	private readonly imageData: ImageData;

	constructor(texture: THREE.Texture) {
		this.imageData = TextureUtils.getImageDataFromTexture(texture);
	}

	public createVertexWeightsFromTexture(geometry: BufferGeometry, channel: RGBAChannel) {
		return TextureUtils.createVertexWeightsFromTexture(geometry, this.imageData, channel);
	}
}