import * as THREE from "three";
import {mergeGeometries} from "three/examples/jsm/utils/BufferGeometryUtils.js";
import Random from "../../../lib/utils/Random.js";
import {Object3D} from "three";

export type FoliageMarker = {
	position      : THREE.Vector3,
	radius        : number,
	leavesCount   : number,
	foliageHeight : number,
	foliageWidth  : number,
	channelMask   : THREE.Vector3,

	colors : {
		light : THREE.Color,
		dark  : THREE.Color,
	}
}

enum FOLIAGE_TYPE {
	BUSH = 'BUSH',
	TREE = 'TREE',
	MAIN_TREE = 'MAIN_TREE',
}

enum FOLIAGE_TYPE_PATTERN {
	MAIN_TREE = 'tree-foliage-main',
	TREE = 'tree-foliage',
	BUSH = 'bush-foliage',
}

const FOLIAGE_CHANNEL = {
	[FOLIAGE_TYPE.MAIN_TREE]: new THREE.Vector3(0, 1, 0),
	[FOLIAGE_TYPE.TREE]: new THREE.Vector3(1, 0, 0),
	[FOLIAGE_TYPE.BUSH]: new THREE.Vector3(0, 0, 1),
};

enum FOLIAGE_DIMENSION {
	WIDTH  = 'Width',
	HEIGHT = 'Height',
	LIGHT_COLOR  = 'LightColor',
	DARK_COLOR   = 'DarkColor',
}

const FOLIAGE_TYPE_MAP = {
	[FOLIAGE_TYPE_PATTERN.MAIN_TREE]: FOLIAGE_TYPE.MAIN_TREE,
	[FOLIAGE_TYPE_PATTERN.TREE]: FOLIAGE_TYPE.TREE,
	[FOLIAGE_TYPE_PATTERN.BUSH]: FOLIAGE_TYPE.BUSH,
};

/**
 * Used to adjust the meaning of numbers to the imported model scale
 */
const DENSITY_ADJUSTMENT_FACTOR = 10;

function snakeToCamel(str: string) {
	return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

export default class FoliageMarkers {
	private readonly markers     : FoliageMarker[];
	private readonly group       : THREE.Group;
	private readonly tweakValues : Record<string, any>;
	private readonly scale       : number;

	private mesh! : THREE.Mesh;

	constructor(
		group       : THREE.Group,
		tweakValues : Record<string, any>
	) {
		this.markers     = [];
		this.group       = group;
		this.tweakValues = tweakValues;
		this.scale       = 0.15;

		this.collect();
	}

	private collect() {
		this.group.traverse((obj) => {
			if (obj instanceof THREE.Mesh) return;
			if (obj.children.length > 0)   return;

			if (this.isFoliageMarker(obj)) {
				const foliageType = this.getFoliageType(obj);

				const radius = Math.abs(obj.scale.x * this.scale);
				this.markers.push({
					radius,
					position      : obj.position,

					channelMask   : FOLIAGE_CHANNEL[foliageType],
					foliageHeight : this.getFoliageHeight(foliageType) * radius,
					foliageWidth  : this.getFoliageWidth(foliageType)  * radius,

					leavesCount   : this.getFoliageLeavesCount(
						obj.scale.x,
						this.tweakValues.density,
					),

					colors : {
						light : this.getFoliageLightColor(foliageType),
						dark  : this.getFoliageDarkColor(foliageType),
					}
				});
			}
		});
	}

	private getFoliageLightColor(foliageType: FOLIAGE_TYPE): THREE.Color {
		return new THREE.Color(
			this.getFoliageDimension(foliageType, FOLIAGE_DIMENSION.LIGHT_COLOR),
		);
	}

	private getFoliageDarkColor(foliageType: FOLIAGE_TYPE): THREE.Color {
		return new THREE.Color(
			this.getFoliageDimension(foliageType, FOLIAGE_DIMENSION.DARK_COLOR),
		);
	}

	private getFoliageLeavesCount(radius: number, density: number) {
		return Math.abs(
			Math.round(radius * density * DENSITY_ADJUSTMENT_FACTOR),
		);
	}

	private isFoliageMarker(obj: THREE.Object3D): boolean {
		return Boolean(
			Object.keys(FOLIAGE_TYPE_MAP)
				.find((pattern) => obj.name.startsWith(pattern)),
		);
	}

	private getFoliageType(obj: THREE.Object3D): FOLIAGE_TYPE | never {
		const type = Object.entries(FOLIAGE_TYPE_MAP).find(
			([ pattern ]) => obj.name.startsWith(pattern)
		)?.[1];

		if (!type) {
			console.error(obj);
			throw new Error(`Unable to convert foliage marker name '${obj.name}' into a foliage type.`);
		}

		return type;
	}

	private getFoliageHeight(foliageType: FOLIAGE_TYPE): number {
		return this.getFoliageDimension(foliageType, FOLIAGE_DIMENSION.HEIGHT);
	}

	private getFoliageWidth(foliageType: FOLIAGE_TYPE) : number {
		return this.getFoliageDimension(foliageType, FOLIAGE_DIMENSION.WIDTH);
	}

	private getFoliageDimension(
		foliageType: FOLIAGE_TYPE,
		dimension: FOLIAGE_DIMENSION
	) : number {
		const key = `${snakeToCamel(foliageType.toLowerCase())}${dimension}`;

		if (!(key in this.tweakValues)) {
			throw new Error(`Property ${key} not found in tweakValues !`);
		}

		const tweakValue = this.tweakValues[key as keyof typeof this.tweakValues];

		if (typeof tweakValue === 'number') {
			return Math.abs(tweakValue);
		}

		if (
			foliageType === FOLIAGE_TYPE.BUSH
			&& dimension === FOLIAGE_DIMENSION.LIGHT_COLOR
		) {
			return Random.inArray(this.tweakValues.bushLightColors);
		}

		return tweakValue;
	}

	get(): FoliageMarker[] {
		return this.markers;
	}

	private createOcclusionGeometry() {
		const geometries: THREE.SphereGeometry[] = [];

		this.markers.forEach(({ position, radius }) => {
			const geometry = new THREE.SphereGeometry(radius * 1.1 / this.scale);
			geometry.translate(position.x, position.y, position.z);

			geometries.push(geometry);
		});

		const merged = mergeGeometries(geometries);

		geometries.forEach((g) => g.dispose());

		return merged;
	}

	public enableOcclusion() {
		const material = new THREE.MeshStandardMaterial();
		material.colorWrite = false;
		material.depthWrite = false;

		this.mesh = new THREE.Mesh(
			this.createOcclusionGeometry(),
			material,
		);

		this.mesh.name = 'foliage-occlusion';
		this.mesh.receiveShadow = true;
		this.mesh.castShadow    = true;

		this.group.add(this.mesh);
	}

	public destroy() {
		this.group.remove(this.mesh);
		(this.mesh.material as THREE.MeshStandardMaterial).dispose();
		this.mesh.geometry.dispose();
	}
}