import * as THREE from "three";

type CurvedPathUtilsParams = {
	/**
	 * total number of computed points along the curve to compute the speed
	 */
	nbOfPoints?: number,
	/**
	 * Precision of the the sampling
	 */
	arcSamples?: number,
	/**
	 * In points per seconds
	 */
	speed?: number,
	/**
	 * Points to create the curve
	 */
	points: THREE.Vector3[],
}

export default class CurvedPathUtils {
	private readonly speed            : number;
	private readonly nbOfPoints       : number;
	private readonly arcSamples       : number;
	private readonly uniformPoints    : THREE.Vector3[];
	private readonly uniformTangents  : THREE.Vector3[];
	private readonly totalCurveLength : number;

	private index: number = 0;
	private curve: THREE.CatmullRomCurve3;

	constructor(
		{
			speed,
			nbOfPoints,
			arcSamples,
			points,
		}: CurvedPathUtilsParams
	) {
		this.speed           = speed      ?? 0.125;
		this.nbOfPoints      = nbOfPoints ?? 1000;
		this.arcSamples      = arcSamples ?? 5000;
		this.uniformPoints   = [];
		this.uniformTangents = [];

		this.curve = new THREE.CatmullRomCurve3(points);
		this.curve.closed = true;

		this.totalCurveLength = this.curve.getLength();

		this.buildUniformPoints();
	}

	getUniformPoint(index: number) {
		const i     : number = Math.floor(index) % this.uniformPoints.length;
		const next  : number = (i + 1) % this.uniformPoints.length;
		const alpha : number = index - Math.floor(index);

		return new THREE.Vector3().lerpVectors(this.uniformPoints[i], this.uniformPoints[next], alpha);
	}

	getUniformTangent(index: number) {
		const i     : number = Math.floor(index) % this.uniformTangents.length;
		const next  : number = (i + 1) % this.uniformTangents.length;
		const alpha : number = index - Math.floor(index);

		return new THREE.Vector3().lerpVectors(this.uniformTangents[i], this.uniformTangents[next], alpha).normalize();
	}

	getPositionAndTangent(deltaTime: number): { position: THREE.Vector3, tangent: THREE.Vector3 } {
		this.index += (this.speed * deltaTime) / this.totalCurveLength * this.nbOfPoints;

		return {
			position : this.getUniformPoint(this.index),
			tangent  : this.getUniformTangent(this.index)
		};
	}

	private buildUniformPoints() {
		this.uniformPoints.splice(0);
		this.uniformTangents.splice(0);

		// Sample the curve at very high resolution first
		const highResPoints   = [];
		const highResTangents = [];

		for (let i = 0; i <= this.arcSamples; i++) {
			const t = i / this.arcSamples;
			highResPoints.push(this.curve.getPoint(t));
			highResTangents.push(this.curve.getTangent(t).normalize());
		}

		// Calculate cumulative distances
		const distances = [0];
		for (let i = 1; i < highResPoints.length; i++) {
			const dist = highResPoints[i-1].distanceTo(highResPoints[i]);
			distances.push(distances[distances.length - 1] + dist);
		}

		const totalLength = distances[distances.length - 1];

		// Now create uniformly spaced points and tangents
		for (let i = 0; i < this.nbOfPoints; i++) {
			const targetDistance = (i / this.nbOfPoints) * totalLength;

			// Find the segment containing this distance
			let segmentIndex = 0;
			for (let j = 1; j < distances.length; j++) {
				if (distances[j] >= targetDistance) {
					segmentIndex = j - 1;
					break;
				}
			}

			// Interpolate between the two points
			const t1    = distances[segmentIndex];
			const t2    = distances[segmentIndex + 1];
			const alpha = (targetDistance - t1) / (t2 - t1);

			const point = new THREE.Vector3()
				.lerpVectors(highResPoints[segmentIndex], highResPoints[segmentIndex + 1], alpha);

			const tangent = new THREE.Vector3()
				.lerpVectors(highResTangents[segmentIndex], highResTangents[segmentIndex + 1], alpha)
				.normalize();

			this.uniformPoints.push(point);
			this.uniformTangents.push(tangent);
		}
	}
}