import * as THREE from 'three';
import Engine from "../../../lib/core/Engine.js";
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import fragmentShader from "./shaders/fragment.glsl";
import vertexShader from "./shaders/vertex.glsl";
import FoliageMarkers, {FoliageMarker} from "./FoliageMarkers.js";
import Random from "../../../lib/utils/Random.js";
import config from "../../../config/Conf.js";

type TweakValues = {
	density        : number,

	lightContrast  : number,
	lightOffset    : number,
	colorVariation : number,

	treeHeight     : number,
	treeWidth      : number,
	treeLightColor : string,
	treeDarkColor  : string,

	mainTreeHeight : number,
	mainTreeWidth  : number,
	mainTreeLightColor : string,
	mainTreeDarkColor  : string,

	bushHeight     : number,
	bushWidth      : number,
	bushLightColor : string,
	bushDarkColor  : string,
	bushLightColors : string[],
}

type FoliageParams = {
	group         : THREE.Group,
	engine        : Engine,
	resources     : Resources<typeof sources>,
	initialTweaks : TweakValues,
}

export default class Foliage {
	private readonly group       : THREE.Group;
	private readonly engine      : Engine;
	private readonly resources   : Resources<typeof sources>;
	private readonly tweakValues : TweakValues;

	private material!      : THREE.ShaderMaterial;
	private depthMaterial! : THREE.ShaderMaterial;

	private mesh!     : THREE.InstancedMesh;
	private geometry! : THREE.PlaneGeometry;
	private foliageMarkers! : FoliageMarkers;

	constructor(
		{
			group,
			engine,
			resources,
			initialTweaks,
		}: FoliageParams,
	) {
		this.group       = group;
		this.engine      = engine;
		this.resources   = resources;
		this.tweakValues = initialTweaks;

		this.init();
		this.configureTweaks();
		this.engine.on(
			'global:config:changed',
			(event) => {
				const conf = event?.detail?.config;
				if (!conf) return;

				this.configChanged(conf);
			}
		)
	}

	private configChanged(conf: typeof config) {
		if (conf.islands.foliage.treeLightColor) {
			this.updateTreeLightColor(conf.islands.foliage.treeLightColor, false);
		}

		if (conf.islands.foliage.mainTreeLightColor) {
			this.updateMainTreeLightColor(conf.islands.foliage.mainTreeLightColor, false);
		}

		if (conf.islands.foliage.bushLightColors) {
			this.tweakValues.bushLightColors = conf.islands.foliage.bushLightColors;
		}

		this.rebuild();
	}

	private init() {
		this.resources.onceAll(
			[
				'loaded:foliage',
			],
			() => {
				this.createMaterial();
				this.createGeometry();
				this.createInstancedFoliage();
			}
		);
	}

	private createMaterial() {
		const materialParams = {
			vertexShader,
			fragmentShader,
			uniforms: {
				time           : new THREE.Uniform(0),
				windStrength   : new THREE.Uniform(5),
				aoStrength     : new THREE.Uniform(0.5),
				alphaMap       : new THREE.Uniform(this.resources.items.foliage),
				lightDirection : new THREE.Uniform(new THREE.Vector3(0.5, -0.2, 0.2)),
				lightColor     : new THREE.Uniform(new THREE.Color(0xffffff)),
				ambientColor   : new THREE.Uniform(new THREE.Color(0x404080))
			},
		};

		this.material = new THREE.ShaderMaterial(materialParams);
		this.depthMaterial = new THREE.ShaderMaterial(materialParams);
	}

	private createGeometry() {
		this.geometry = new THREE.PlaneGeometry(0.02, 0.02);
	}

	private createInstancedFoliage() {
		this.foliageMarkers = new FoliageMarkers(this.group, this.tweakValues);
		this.foliageMarkers.enableOcclusion();

		const markers = this.foliageMarkers.get();

		const totalLeaves  = markers.reduce(
			(acc, marker) => acc + marker.leavesCount,
			0,
		);

		this.mesh = new THREE.InstancedMesh(
			this.geometry,
			this.material,
			totalLeaves,
		);
		this.mesh.customDepthMaterial = this.depthMaterial;
		this.mesh.castShadow = true;
		this.mesh.receiveShadow = true;

		this.generateFoliage(markers);
		this.group.add(this.mesh);
	}

	private generateFoliage(markers: FoliageMarker[]) {
		const totalCount = this.mesh.count;

		const dummy = new THREE.Object3D();

		const baseLightingValues = new Float32Array(totalCount);
		const textureRotations   = new Float32Array(totalCount);
		const scaleVariations    = new Float32Array(totalCount);
		const bushCenters        = new Float32Array(totalCount * 3);
		const leafPhases         = new Float32Array(totalCount);
		const bushPhases         = new Float32Array(totalCount);
		const channelMasks       = new Float32Array(totalCount * 3);

		let index = 0;

		markers.forEach((markers) => {
			const {
				position,
				leavesCount,
				foliageHeight,
				foliageWidth,
				channelMask,
				colors: {
					light,
					dark,
				},
			} = markers;

			const baseBushColor = Random.colorBetween(light, dark, 0.1);
			const bushPhaseOffset = Math.random() * Math.PI * 2;

			for (let l = 0; l < leavesCount; l++) {
				// Generate random point in sphere with bias towards outside
				let x, y, z, radius;
				do {
					x = (Math.random() - 0.5) * 2;
					y = (Math.random() - 0.5) * 2;
					z = (Math.random() - 0.5) * 2;
					radius = Math.sqrt(x * x + y * y + z * z);
				} while (radius > 1.0);

				// Bias towards shell of sphere for more realistic foliage distribution
				const biasedRadius = Math.pow(radius, 0.6); // Push points towards surface
				const scale = biasedRadius / radius;
				x *= scale;
				y *= scale;
				z *= scale;

				const leafPosition = new THREE.Vector3(
					position.x + x * foliageWidth,
					position.y + y * foliageHeight,
					position.z + z * foliageWidth,
				);

				const bushCenterVec = position.clone();

				dummy.position.copy(leafPosition);
				dummy.rotation.set(0, 0, 0);
				dummy.updateMatrix();

				this.mesh.setMatrixAt(index, dummy.matrix);

				// Enhanced color variation based on position
				const leafColor = this.createColorVariation(
					baseBushColor,
					dark,
					0.4
				);
				this.mesh.setColorAt(index, leafColor);

				textureRotations[index] = Math.random() * Math.PI * 2;
				scaleVariations[index] = 0.7 + Math.random() * 0.6;

				bushCenters[index * 3] = position.x;
				bushCenters[index * 3 + 1] = position.y;
				bushCenters[index * 3 + 2] = position.z;

				channelMasks[index * 3] = channelMask.x;
				channelMasks[index * 3 + 1] = channelMask.y;
				channelMasks[index * 3 + 2] = channelMask.z;

				leafPhases[index] = Math.random() * Math.PI * 2;
				bushPhases[index] = bushPhaseOffset + (Math.random() - 0.5) * 0.5;

				// Pre-calculate base lighting for this leaf
				baseLightingValues[index] = this.calculateBaseLighting(
					leafPosition,
					bushCenterVec,
					foliageWidth,
				);

				index++;
			}
		});

		this.mesh.geometry.setAttribute('textureRotation', new THREE.InstancedBufferAttribute(textureRotations, 1));
		this.mesh.geometry.setAttribute('scaleVariation',  new THREE.InstancedBufferAttribute(scaleVariations, 1));
		this.mesh.geometry.setAttribute('bushCenter',      new THREE.InstancedBufferAttribute(bushCenters, 3));
		this.mesh.geometry.setAttribute('leafPhase',       new THREE.InstancedBufferAttribute(leafPhases, 1));
		this.mesh.geometry.setAttribute('bushPhase',       new THREE.InstancedBufferAttribute(bushPhases, 1));
		this.mesh.geometry.setAttribute('baseLighting',    new THREE.InstancedBufferAttribute(baseLightingValues, 1));
		this.mesh.geometry.setAttribute('channelMask',     new THREE.InstancedBufferAttribute(channelMasks, 3));

		this.mesh.instanceMatrix.needsUpdate = true;
		this.mesh.frustumCulled = true;
	}

	private createColorVariation(
		baseColor: THREE.Color,
		darkColor: THREE.Color,
		variationAmount: number,
	) {
		const hsl = { h: 0, s: 0, l: 0 };
		baseColor.getHSL(hsl);

		const lightVar = (Math.random() - 0.5) * variationAmount * this.tweakValues.colorVariation;

		const newColor = new THREE.Color();
		newColor.setHSL(
			hsl.h,
			hsl.s,
			Math.max(0, hsl.l + lightVar)
		);

		return newColor.lerp(darkColor, lightVar);
	}

	private calculateBaseLighting(
		leafPos: THREE.Vector3,
		bushCenter: THREE.Vector3,
		bushRadius: number
	) {
		const distanceFromCenter = leafPos.distanceTo(bushCenter) / bushRadius;
		const heightFactor = Math.max(0, (leafPos.y - bushCenter.y) / bushRadius + 0.5);

		// Leaves on the outside and higher up get more base lighting
		const baseLighting = this.tweakValues.lightOffset
			+ distanceFromCenter * this.tweakValues.lightContrast
			+ heightFactor * this.tweakValues.lightContrast * 0.5;

		return baseLighting;
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Islands.Foliage',
				density: {
					onChange: (density: number) => {
						this.tweakValues.density = density;
						this.rebuild();
					},
				},
				treeLightColor: {
					onChange: this.updateTreeLightColor.bind(this)
				},
				treeDarkColor: {
					onChange: (color: string) => {
						this.tweakValues.treeDarkColor = color;
						this.rebuild();
					},
				},
				mainTreeLightColor: {
					onChange: this.updateMainTreeLightColor.bind(this),
				},
				mainTreeDarkColor: {
					onChange: (color: string) => {
						this.tweakValues.mainTreeDarkColor = color;
						this.rebuild();
					},
				},
				lightContrast: {
					params: {
						min: 0,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						this.tweakValues.lightContrast = value;
						this.rebuild();
					}
				},
				lightOffset: {
					params: {
						min: 0,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						this.tweakValues.lightContrast = value;
						this.rebuild();
					}
				},
				colorVariation: {
					params: {
						min: 0,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						this.tweakValues.colorVariation = value;
						this.rebuild();
					}
				}
			}
		);
	}

	private updateTreeLightColor(color: string, rebuild = true) {
		this.tweakValues.treeLightColor = color;
		if(rebuild) this.rebuild();
	}

	private updateMainTreeLightColor(color: string, rebuild = true) {
		this.tweakValues.mainTreeLightColor = color;
		if (rebuild) this.rebuild();
	}

	private rebuild() {
		this.destroy();
		this.init();
	}

	update() {
		if (!this.material) return;

		this.material.uniforms.time.value = this.engine.time.elapsedSeconds;
		this.depthMaterial.uniforms.time.value = this.engine.time.elapsedSeconds;
	}

	destroy() {
		this.foliageMarkers.destroy();
		this.group.remove(this.mesh);
		this.material.dispose();
		this.geometry.dispose();
		this.mesh.geometry.dispose();
	}
}