import * as THREE from 'three';
import WindLine, {EVENTS} from "./WindLine.js";
import Engine from "../../../../lib/core/Engine.js";
import Random from "../../../../lib/utils/Random.js";

type Pair<T = number> = [T, T];

type WindLinePoolParams = {
	group       : THREE.Group,
	engine      : Engine,
	boundingBox : THREE.Box3,
	count?             : number,
	idleTimeThreshold? : number,
	delayRange?        : Pair,
	durationRange?     : Pair,
	amplitudeRange?    : Pair,
	lengthRange?       : Pair,
	thicknessRange?    : Pair,
	rotationRange?     : Pair,
	scaleRange?        : Pair,
	directorPointsCountRange? : Pair,
}

enum WindLineState {
	PLAYING,
	READY
}

type ScheduledLine = {
	state        : WindLineState,
	/**
	 * In ms: the timestamp from which the wind line animation can be played.
	 */
	canStartFrom : number,
};

const DEFAULT_COUNT = 25;
const DEFAULT_IDLE_TIME_THRESHOLD = 1000;
const DEFAULT_DIRECTOR_POINTS_COUNT_RANGE : Pair = [3, 5];
const DEFAULT_DELAY_RANGE     : Pair = [0    , 30 * 1000];
const DEFAULT_DURATION_RANGE  : Pair = [4    , 10];
const DEFAULT_AMPLITUDE_RANGE : Pair = [0.1  , 0.25];
const DEFAULT_LENGTH_RANGE    : Pair = [1    , 2.5];
const DEFAULT_THICKNESS_RANGE : Pair = [0.02 , 0.04];
const DEFAULT_ROTATION_RANGE  : Pair = [20   , 24];
const DEFAULT_SCALE_RANGE     : Pair = [0.6  , 1.6];;

export default class WindLinePool {
	private readonly engine : Engine;
	private readonly group  : THREE.Group;
	private readonly lines  : Map<WindLine, ScheduledLine>;

	private readonly idleTimeThreshold : number;
	private readonly delayRange        : Pair;
	private readonly durationRange     : Pair;
	private readonly amplitudeRange    : Pair;
	private readonly lengthRange       : Pair;
	private readonly thicknessRange    : Pair;
	private readonly rotationRange     : Pair;
	private readonly scaleRange        : Pair;
	private readonly boundingBox       : THREE.Box3;
	private readonly directorPointsCountRange : Pair;

	constructor(
		{
			count             = DEFAULT_COUNT,
			delayRange        = DEFAULT_DELAY_RANGE,
			idleTimeThreshold = DEFAULT_IDLE_TIME_THRESHOLD,
			durationRange     = DEFAULT_DURATION_RANGE,
			amplitudeRange    = DEFAULT_AMPLITUDE_RANGE,
			lengthRange       = DEFAULT_LENGTH_RANGE,
			thicknessRange    = DEFAULT_THICKNESS_RANGE,
			rotationRange     = DEFAULT_ROTATION_RANGE,
			scaleRange        = DEFAULT_SCALE_RANGE,
			directorPointsCountRange = DEFAULT_DIRECTOR_POINTS_COUNT_RANGE,
			boundingBox,
			engine,
			group,
		}: WindLinePoolParams
	) {
		this.engine   = engine;
		this.group    = group;
		this.lines    = new Map();
		this.delayRange        = delayRange;
		this.idleTimeThreshold = idleTimeThreshold;
		this.durationRange     = durationRange;
		this.amplitudeRange    = amplitudeRange;
		this.lengthRange       = lengthRange;
		this.thicknessRange    = thicknessRange;
		this.rotationRange     = rotationRange;
		this.scaleRange        = scaleRange;
		this.boundingBox       = boundingBox;
		this.directorPointsCountRange = directorPointsCountRange;

		this.init(count);
	}

	private init(count: number) {
		for(let i = 0; i < count; i++) {
			const line = this.randomizeWindLine();

			this.lines.set(
				line,
				{
					state: WindLineState.READY,
					canStartFrom: this.randomNextStart(),
				},
			);
		}
	}

	private randomNextStart(): number {
		return this.engine.time.elapsedMs + Random.between(...this.delayRange);
	}

	private randomizeWindLine(): WindLine {
		const randomDuration = Random.between(...this.durationRange);

		const line = new WindLine({
			engine : this.engine,
			group  : this.group,
			initialTweaks: {
				duration  : randomDuration,
				amplitude : Random.between(...this.amplitudeRange),
				length    : Random.between(...this.lengthRange),
				thickness : Random.between(...this.thicknessRange),
				directorPointsCount : Random.betweenInt(...this.directorPointsCountRange),
			}
		});

		const mesh = line.getMesh();

		this.setRandomPositionTo(mesh);
		this.setRandomScaleTo(mesh);
		this.setRandomRotationTo(mesh);
		this.setupLineEventListeners(line);

		return line;
	}

	private setRandomPositionTo(mesh: THREE.Mesh) {
		mesh.position.copy(Random.pointInBox(this.boundingBox));
	}

	private setRandomScaleTo(mesh: THREE.Mesh) {
		const randomScale = Random.between(...this.scaleRange);
		mesh.scale.set(randomScale, randomScale, randomScale);
	}

	private setRandomRotationTo(mesh: THREE.Mesh) {
		mesh.rotation.set(
			Random.sign() * Math.PI / Random.between(...this.rotationRange),
			Random.sign() * Math.PI / Random.between(...this.rotationRange),
			Random.sign() * Math.PI / Random.between(...this.rotationRange),
		);
	}

	private setupLineEventListeners(line: WindLine) {
		line.on(EVENTS.COMPLETE, () => {
			line.reset();
		});

		line.on(EVENTS.START, () => {
			const params = this.lines.get(line)!;

			params.state = WindLineState.PLAYING;
		});

		line.on(EVENTS.RESET, () => {
			const params = this.lines.get(line)!;

			params.canStartFrom = this.randomNextStart();
			this.setRandomPositionTo(line.getMesh());
			params.state = WindLineState.READY;
		});
	}

	update() {
		const now: number      = this.engine.time.elapsedMs;

		if (this.detectedIdleTab()) {
			this.reschedule();
		}

		for (const [line, params] of this.lines) {
			line.update();

			if (params!.state === WindLineState.READY && now >= params!.canStartFrom) {
				line.start();
			}
		}
	}

	private detectedIdleTab(): boolean {
		return this.engine.time.deltaMs > this.idleTimeThreshold;
	}

	private reschedule() {
		for (let [, params] of this.lines) {
			if (params.state === WindLineState.READY) {
				params.canStartFrom = this.randomNextStart();
			}
		}
	}

	destroy() {
		for (const line of this.lines.keys()) {
			line.destroy();
		}

		this.lines.clear();
	}
}