import * as THREE from 'three';
import Engine from "../../../lib/core/Engine.js";
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";
import createLightStandardMaterial from "../../../lib/materials/light/LightStandardMaterial.js";

type TreesParams = {
	engine: Engine,
	group: THREE.Group,
	resources: Resources<typeof sources>,
}

export default class Trees {
	private readonly engine: Engine;
	private readonly group: THREE.Group;
	private readonly resources: Resources<typeof sources>;

	private barkMaterial!: THREE.MeshStandardMaterial | THREE.ShaderMaterial;
	private trees: THREE.Mesh[];

	constructor(
		{
			group,
			engine,
			resources,
		}: TreesParams
	) {
		this.trees = [];
		this.group = group;
		this.engine = engine;
		this.resources = resources;

		this.init();
	}

	private init() {
		this.resources.onceAll([
			'loaded:barkColor',
			'loaded:barkArm',
			'loaded:barkNormal',
		], () => {
			this.initBarkMaterial();
			this.initTrees();
		});
	}

	private initBarkMaterial() {
		this.barkMaterial = new THREE.MeshStandardMaterial();

		this.barkMaterial.map = this.resources.items.barkColor;
		this.barkMaterial.normalMap = this.resources.items.barkNormal;
		this.barkMaterial.aoMap = this.resources.items.barkArm;
		this.barkMaterial.aoMapIntensity = 1;
		this.barkMaterial.roughnessMap = this.resources.items.barkArm;

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;

			if (declineLevel === 2) {
				this.flipStandardForShaderMaterial();
			}
		});
	}

	private flipStandardForShaderMaterial() {
		console.warn('Trees: Low fps detected. Switching to light material');
		this.barkMaterial.dispose();

		this.barkMaterial = createLightStandardMaterial(
			this.resources.items.barkColor,
			this.resources.items.environmentMap,
			new THREE.Color('#bfb9b6')
		);

		this.trees.forEach((tree) => tree.material = this.barkMaterial);

	}

	private initTrees() {
		this.group.traverse((obj) => {
			if (!(obj instanceof THREE.Mesh)) return;

			if (obj.name.startsWith('tree-trunk')) {
				obj.material = this.barkMaterial;
				this.trees.push(obj);
			}
		});
	}

	update() {
		// Noop for now.
	}

	public destroy() {
		this.barkMaterial?.dispose();
		this.trees.forEach((tree) => tree.geometry.dispose());
	}
}