import * as THREE from 'three';
import gsap from 'gsap';
import Engine from "../../lib/core/Engine.js";
import {MeshBasicMaterial, MeshPhongMaterial} from "three";
import createLightStandardMaterial from "../../lib/materials/light/LightStandardMaterial.js";

type BasaltRocksParams = {
	engine: Engine,
	islands: THREE.Group,
	initialTweaks: TweakValues,
}

type TweakValues = {
	floatingRocks: {
		speed: number,
		minSpeed: number,
		maxSpeed: number,
	}
}

export default class BasaltRocks {
	private readonly engine: Engine;
	private readonly islands: THREE.Group;
	private readonly landscapeColumns: THREE.Mesh[];
	private readonly floatingRocks: THREE.Mesh[];
	private readonly initialFloatingRocksPositions: THREE.Vector3[];
	private readonly tweakValues: TweakValues;

	private material!: THREE.MeshStandardMaterial | THREE.MeshPhongMaterial;

	private floatingRocksSpeed: number;

	constructor(
		{
			engine,
			islands,
			initialTweaks,
		}: BasaltRocksParams
	) {
		this.engine = engine;
		this.islands = islands;
		this.tweakValues = initialTweaks;
		this.floatingRocksSpeed = initialTweaks.floatingRocks.speed;
		this.landscapeColumns = [];
		this.floatingRocks = [];
		this.initialFloatingRocksPositions = [];

		this.init();
	}

	private init() {
		this.initMaterial();
		this.extractMeshes();
	}

	private extractMeshes() {
		this.islands.traverse((obj) => {
			if (!(obj instanceof THREE.Mesh)) return;
			if (!obj.name.startsWith('basalt-')) return;

			if (obj.name.startsWith('basalt-floating-rock')) {
				this.floatingRocks.push(obj);
				this.initialFloatingRocksPositions.push(obj.position.clone());
			} else {
				this.landscapeColumns.push(obj);
			}

			obj.material = this.material;
		});
	}

	private initMaterial() {
		this.material = new THREE.MeshStandardMaterial({
			color: new THREE.Color('#101722').multiplyScalar(2.5),
			flatShading: true,
			roughness: 0.6,
			metalness: 0,
		});

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;

			if (declineLevel === 2) {
				this.flipStandardForPhongMaterial();
			}
		});
	}

	private flipStandardForPhongMaterial() {
		console.warn('BasaltRocks: Low fps detected. Switching to Phong material.');

		this.material.dispose();
		this.material = new MeshPhongMaterial({
			color: '#8f7a52',
			flatShading: true,
			reflectivity: 0.05,
		});

		this.floatingRocks.forEach((mesh) => {
			mesh.material = this.material;
		});

		this.landscapeColumns.forEach((mesh) => {
			mesh.material = this.material;
		});
	}

	public throwFloatingRocksAway() {
		this.floatingRocks.forEach((mesh, index) => {
			// Get the mesh's current world position (its origin)
			const meshOrigin = new THREE.Vector3();
			mesh.getWorldPosition(meshOrigin);

			// Compute the mesh's visual center in world space
			const bbox = new THREE.Box3().setFromObject(mesh);
			const visualCenter = new THREE.Vector3();
			bbox.getCenter(visualCenter);

			// Direction from mesh ORIGIN to its VISUAL CENTER
			// This represents where the mesh geometry is relative to its origin
			const geometryOffset = visualCenter.clone().sub(meshOrigin);

			// Normalize to get direction
			const direction = geometryOffset.clone().normalize();

			// Expel distance
			const expelDistance = 0.2;

			// Calculate the movement in world space
			const worldMovement = direction.multiplyScalar(expelDistance);

			// Convert to local space if needed
			let localMovement = worldMovement;
			if (mesh.parent) {
				// Apply only the rotation part of the parent's inverse transform
				const parentMatrix = mesh.parent.matrixWorld.clone();
				const rotationMatrix = new THREE.Matrix4().extractRotation(parentMatrix);
				const inverseRotation = rotationMatrix.invert();
				localMovement = worldMovement.applyMatrix4(inverseRotation);
			}

			// Save initial local position
			const initialLocalPos = mesh.position.clone();

			// Target local position
			const targetLocalPos = initialLocalPos.clone().add(localMovement);

			// Animate outward
			gsap.to(mesh.position, {
				duration: 0.1,
				delay: 0.15,
				ease: "power2.out",
				x: targetLocalPos.x,
				y: targetLocalPos.y,
				z: targetLocalPos.z,
				onComplete: () => {
					// Animate back
					gsap.to(mesh.position, {
						duration: 2.0,
						delay: 0.5,
						ease: "power2.inOut",
						x: this.initialFloatingRocksPositions[index].x,
						y: this.initialFloatingRocksPositions[index].y,
						z: this.initialFloatingRocksPositions[index].z,
					});
				}
			});
		});
	}

	/**
	 * @param normalizedSpeed - 0 -> minimum speed. 1 -> max speed.
	 */
	changeFloatingRocksSpeed(normalizedSpeed: number) {
		this.floatingRocksSpeed = THREE.MathUtils.lerp(
			this.tweakValues.floatingRocks.minSpeed,
			this.tweakValues.floatingRocks.maxSpeed,
			normalizedSpeed,
		);
	}

	update() {
		const delta = this.engine.time.deltaSeconds;

		this.floatingRocks.forEach((mesh) => {
			mesh.rotation.y += delta * this.floatingRocksSpeed;
		});
	}

	destroy() {
		this.material.dispose();
		this.landscapeColumns.forEach((mesh) => mesh.geometry.dispose());
		this.floatingRocks.forEach((mesh ) => mesh.geometry.dispose());
	}
}