import EventEmitter from "../utils/EventEmitter.js";

export enum EVENTS {
	DECLINE = 'decline',
}

type FPSMonitorOptions = {
	fpsThreshold?: number;
	maxDeclineLevel?: number;
	sampleWindowMs?: number;
};

export default class FPSMonitor extends EventEmitter {
	private readonly fpsThreshold: number;
	private readonly maxDeclineLevel: number;
	private readonly sampleWindowMs: number;

	private fpsSamples: Array<{ fps: number; timestamp: number }> = [];
	private isStarted = false;
	private declineLevel = 0;
	private lastDeclineEmitTime = 0;
	private lastSampleTime = performance.now();

	constructor(options: FPSMonitorOptions = {}) {
		super();
		this.fpsThreshold = options.fpsThreshold ?? 30;
		this.maxDeclineLevel = options.maxDeclineLevel ?? 5;
		this.sampleWindowMs = options.sampleWindowMs ?? 3000;

		this.init();
	}

	private init() {
		document.addEventListener('visibilitychange', () => {
			if (this.isStarted) {
				this.stop();
			} else {
				this.fpsSamples.splice(0);
				this.start();
			}
		});
	}

	start(): void {
		this.isStarted = true;
		this.fpsSamples = [];
		this.declineLevel = 0;
		this.lastDeclineEmitTime = 0;
	}

	stop(): void {
		this.isStarted = false;
	}

	addSample(fps: number): void {
		if (!this.isStarted) return;
		if (document.visibilityState === "hidden") return;

		const now = performance.now();
		const delta = now - this.lastSampleTime;

		this.lastSampleTime = now;

		if (delta > 500) {
			return;
		}

		this.fpsSamples.push({ fps, timestamp: now });

		const cutoffTime = now - this.sampleWindowMs;
		this.fpsSamples = this.fpsSamples.filter(sample => sample.timestamp >= cutoffTime);

		this.checkForDecline(now);
	}

	private checkForDecline(now: number): void {
		if (this.fpsSamples.length < 5) {
			return;
		}

		const fpsAverage = this.computeFpsAverage();

		if (this.isBelowThreshold(fpsAverage) && this.canEmit()) {
			this.declineLevel++;
			this.lastDeclineEmitTime = now;

			this.emit(
				EVENTS.DECLINE,
				new CustomEvent(EVENTS.DECLINE, {
					detail: {
						fps: fpsAverage,
						declineLevel: this.declineLevel
					},
				}),
			);

			this.fpsSamples.splice(0);
		}
	}

	private computeFpsAverage(): number {
		if (this.fpsSamples.length === 0) {
			return 0;
		}

		const totalFps = this.fpsSamples.reduce((sum, sample) => sum + sample.fps, 0);
		return totalFps / this.fpsSamples.length;
	}

	private isBelowThreshold(fps: number): boolean {
		return fps < this.fpsThreshold;
	}

	private canEmit() {
		return (performance.now() - this.lastDeclineEmitTime >= 1000) &&
			(this.declineLevel < this.maxDeclineLevel);
	}

	setDeclineLevel(level: number): void {
		this.declineLevel = Math.max(0, Math.min(level, this.maxDeclineLevel));
	}
}