import PerfsGuiCapabilities from "./PerfsGuiCapabilities.js";
import * as THREE from "three";
import {FpsMetrics} from "./Perfs.js";
import PerfsGui from "./PerfsGui.js";
import EventBusCapabilities from "../core/events/EventBusCapabilities.js";

export default class PerfsGuiBridge implements PerfsGuiCapabilities {
	public static configure() {
		const parent = self.document.body?.querySelector('#perfs-monitor');

		if (!parent) {
			throw new Error('No element with id "perfs-monitor" found in document body !');
		}

		const gui = new PerfsGui({
			parent: parent as HTMLElement,
			enabled: true,
		});

		self.window.addEventListener('perfMetrics:update', (event) => {
			const customEvent = event as CustomEvent;
			gui.update(customEvent.detail.info, customEvent.detail.fpsStats);
		});

		self.window.addEventListener('perfMetrics:enable', () => {
			gui.enable();
		});

		self.window.addEventListener('perfMetrics:disable', () => {
			gui.disable();
		});

		self.window.addEventListener('perfMetrics:destroy', () => {
			gui.destroy();
		});
	}

	private readonly eventBus: EventBusCapabilities;

	constructor(eventBus: EventBusCapabilities) {
		this.eventBus = eventBus;
	}

	enable(): void {
		this.eventBus.dispatch('window', 'perfMetrics:enable');
	}

	disable(): void {
		this.eventBus.dispatch('window', 'perfMetrics:disable');
	}

	update(info: THREE.WebGLInfo, fpsStats: FpsMetrics): void {
		this.eventBus.dispatch('window', 'perfMetrics:update', {
			info: {
				memory: info.memory,
				render: info.render,
				programs: info.programs?.map(({ name }) => ({ name })) ?? [],
			},
			fpsStats,
		});
	}

	destroy(): void {
		this.eventBus.dispatch('window', 'perfMetrics:destroy');
	}
}