import * as THREE from 'three';
import Sizes, {SizesType} from "./Sizes.js";
import Time from "./Time.js";
import Camera from "./Camera.js";
import Renderer from "./Renderer.js";
import Perfs from "../perfs/Perfs.js";
import Monitor from "../perfs/Monitor.js";
import Tweaks from '../dev/Tweaks.js';
import EventEmitter from "../utils/EventEmitter.js";
import PostProcessing from "./PostProcessing.js";
import Raycaster from './Raycaster.js';
import EventBusCapabilities from "./events/EventBusCapabilities.js";
import PerfsGuiBridge from "../perfs/PerfsGuiBridge.js";
import PerfsGui from "../perfs/PerfsGui.js";
import TweaksCapabilities from "../dev/TweaksCapabilities.js";
import {isOffscreenCanvas} from "../compatibility/offscreenCanvas.js";
import TweaksBridge from "../dev/TweaksBridge.js";
import Audio, {AudioItems} from "./Audio.js";
import Pointer from "./Pointer.js";

export default class Engine<A extends AudioItems = any> extends EventEmitter{
	public readonly camera    : Camera;
	public readonly canvas    : HTMLCanvasElement | OffscreenCanvas;
	public readonly renderer  : Renderer;
	public readonly scene     : THREE.Scene;
	public readonly sizes     : Sizes;
	public readonly time      : Time;
	public readonly tweaks    : TweaksCapabilities;
	public readonly raycaster : Raycaster;
	public readonly audio     : Audio<A>;
	public readonly eventBus  : EventBusCapabilities;
	public readonly monitor   : Monitor;
	public readonly pointer   : Pointer;

	private readonly perfs    : Perfs;

	private postProcessing!   : PostProcessing;

	constructor(
		{
			canvas,
			initialSizes,
			eventBus,
		}: {
			canvas : HTMLCanvasElement | OffscreenCanvas,
			initialSizes : SizesType,
			eventBus : EventBusCapabilities,
		}
	) {
		super();

		if (!canvas) {
			throw new Error('canvas is required');
		}

		this.eventBus = eventBus;
		this.canvas    = canvas;
		this.tweaks    = this.isExecutedInWorker()
			? new TweaksBridge(eventBus)
			: new Tweaks();
		this.sizes     = new Sizes({
			eventBus,
			...initialSizes,
		});
		this.pointer = new Pointer(this.sizes);
		this.time      = new Time({
			inWorker: this.isExecutedInWorker(),
		});
		this.scene     = new THREE.Scene();

		this.camera    = new Camera({
			sizes  : this.sizes,
			scene  : this.scene,
			canvas : this.canvas,
			tweaks : this.tweaks,
			eventBus,
		});

		this.audio = new Audio({
			camera: this.camera,
		});

		this.raycaster = new Raycaster({
			sizes  : this.sizes,
			camera : this.camera,
			eventBus,
		});

		this.renderer  = new Renderer({
			sizes  : this.sizes,
			scene  : this.scene,
			canvas : this.canvas,
			camera : this.camera,
		});

		this.monitor = new Monitor();

		this.perfs     = new Perfs({
			gui : this.renderer.isExecutedInWorker()
				? new PerfsGuiBridge(eventBus)
				: new PerfsGui({
					parent  : self.document.body.querySelector('#perfs-monitor')!,
					enabled : true,
				}),
			renderer : this.renderer,
			monitor  : this.monitor,
		});

		this.sizes.on('resize', () => {
			this.resize();
		});

		this.time.on('tick', () => {
			this.update();
		});
	}

	public changeCursor(cursorType: string) {
		if (this.canvas instanceof HTMLCanvasElement) {
			this.canvas.setAttribute('style', `cursor: ${cursorType};`);
		} else {
			console.warn('changeCursor is not supported in OffscreenCanvas');
		}
	}

	private isExecutedInWorker(): boolean {
		return isOffscreenCanvas(this.canvas);
	}

	resize(): void {
		this.camera.resize();
		this.renderer.resize();
		this.postProcessing?.resize();
	}

	usePostProcessing(postProcessing: PostProcessing) {
		this.postProcessing = postProcessing;
	}

	update(): void {
		this.perfs.preRender();

		this.emit('update');
		this.camera.update();
		this.audio.update(this.time.deltaSeconds);

		if (this.postProcessing) {
			this.postProcessing.update();
		} else {
			this.renderer.update();
		}

		this.raycaster.update();

		this.perfs.postRender();
	}

	destroy(): void {
		this.sizes.off('resize');
		this.time.off('tick');

		this.scene.traverse((child) => {
			if (child instanceof THREE.Mesh) {
				child.geometry.dispose();

				for (const key in child.material) {
					const material = child.material[key];

					if (material && typeof material.dispose === 'function') {
						material.dispose();
					}
				}
			}
		});

		this.raycaster.destroy();
		this.camera.destroy();
		this.renderer.destroy();
		this.postProcessing?.destroy();
		this.sizes.destroy();

		this.tweaks.destroy();
		this.perfs.destroy();
	}
}
