import * as THREE from 'three';
import Engine from "../../../lib/core/Engine.js";
import Butterfly, {TweakValues} from "./Butterfly.js";
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";

type ButterfliesParams = {
	engine      : Engine,
	group       : THREE.Group,
	resources   : Resources<typeof sources>
	butterflies : TweakValues[],
	boundingBox : THREE.Box3,
}

export default class Butterflies {
	static extractZones(group: THREE.Group): {
		main: THREE.Box3,
		top: THREE.Box3,
	} {
		const zones: {
			main: THREE.Mesh,
			top: THREE.Mesh,
		} = {} as typeof zones;

		group.traverse((obj) => {
			if (obj instanceof THREE.Mesh && obj.name.startsWith('butterfly-zone')) {
				if (obj.name.includes('main')) {
					zones.main = obj;
				}

				zones.top = obj;
			}
		});

		zones.main.geometry.computeBoundingBox();
		zones.top.geometry.computeBoundingBox();

		const res = {
			main: zones.main.geometry.boundingBox!,
			top: zones.top.geometry.boundingBox!,
		};

		zones.main.removeFromParent();
		zones.top.removeFromParent();

		zones.main.geometry.dispose();
		zones.top.geometry.dispose();

		[ res.main, res.top ].forEach((zone) => {
			zone.min.multiplyScalar(group.scale.x);
			zone.max.multiplyScalar(group.scale.x);
		});

		return res;
	}

	private readonly engine      : Engine;
	private readonly group       : THREE.Group;
	private readonly resources   : Resources<typeof sources>;
	private readonly butterflies : Butterfly[];

	private geometry! : THREE.BufferGeometry;

	constructor(
		{
			group,
			engine,
			resources,
			butterflies,
			boundingBox,
		}: ButterfliesParams
	) {
		this.group       = group;
		this.engine      = engine;
		this.resources   = resources;
		this.butterflies = [];

		// const adjustedBox = boundingBox.clone();
		// adjustedBox.translate(new THREE.Vector3(0, 1.6, 0));
		// adjustedBox.max.add(new THREE.Vector3(0, -0.3, 0));

		this.init({ butterflies, boundingBox });
	}

	private init(
		{
			butterflies,
			boundingBox,
		}: Pick<ButterfliesParams, 'butterflies' | 'boundingBox'>
	) {
		this.createGeometry();
		butterflies.forEach((initialTweaks) => {
			this.butterflies.push(this.createButterfly(initialTweaks, boundingBox));
		});
	}

	private createGeometry() {
		this.geometry = new THREE.PlaneGeometry(
			0.04,
			0.04,
			10,
			10,
		);
	}

	private createButterfly(
		initialTweaks: TweakValues,
		boundingBox: THREE.Box3,
	): Butterfly {
		return new Butterfly({
			engine    : this.engine,
			group     : this.group,
			resources : this.resources,
			geometry  : this.geometry,
			boundingBox,
			initialTweaks,
		});
	}

	update() {
		this.butterflies.forEach((butterfly) => butterfly.update());
	}

	destroy() {
		this.butterflies.forEach((butterfly) => butterfly.destroy());
		this.geometry.dispose();
	}
}