import * as THREE from 'three';

type LevelFeatures = {
	geometry? : THREE.BufferGeometry,
	count?    : number,
}

type Level = {
	features: LevelFeatures,
	distance: number,
};

export default class ChunkedInstancedMeshLod {
	private levels: Level[];
	private clonable : boolean;

	constructor(mostDetailedLevel?: LevelFeatures) {
		this.levels   = [];
		this.clonable = true;

		if (mostDetailedLevel) {
			this.addLevel(0, mostDetailedLevel);
		}
	}

	divideCountsBy(factor: number) {
		this.levels.forEach(({ features }) => {
			if (features.count !== undefined) {
				features.count /= factor;
			} else {
				features.count = 1 / factor;
			}
		});
	}

	addLevel(
		distance: number,
		features: LevelFeatures
	) {
		if (Object.keys(features).length === 0) {
			throw new Error(
				'A LOD level must at least define a feature (count or geometry)',
			);
		}

		this.levels.push({
			distance,
			features
		});

		this.levels.sort((a, b) => b.distance - a.distance);
	}

	getLod(
		meshPosition   : THREE.Vector3,
		cameraPosition : THREE.Vector3,
	): LevelFeatures {
		const distance = meshPosition.distanceTo(cameraPosition);

		return this.levels
			.find((level) => distance >= level.distance)!
			.features;
	}

	getDefaultGeometry(): THREE.BufferGeometry {
		return this.levels[this.levels.length - 1].features.geometry!;
	}

	cloneWithAttributes(
		attributes: Record<string, THREE.InstancedBufferAttribute>,
	): ChunkedInstancedMeshLod {
		if (!this.clonable) {
			throw new Error(
				"Can't clone this instance with different attributes : it could mess up the geometries." +
				" Please use the parent LoD instance to configure a new chunk."
			);
		}

		const lod = new ChunkedInstancedMeshLod();

		lod.levels = this.levels.slice(0).map(({distance, features}) => {
			let newGeometry: THREE.BufferGeometry | undefined = undefined;

			if (features.geometry) {
				newGeometry = features.geometry.clone();

				Object.entries(attributes).forEach(([name, attribute]) => {
					newGeometry!.setAttribute(name, attribute);
				});
			}

			return {
				distance,
				features: {
					...features,
					geometry: newGeometry ?? features.geometry,
				}
			}
		});

		lod.clonable = false;

		return lod;
	}

	dispose() {
		this.levels
			.map(({ features }) => features.geometry)
			.filter(Boolean)
			.forEach((geometry) => geometry!.dispose());

	}
}