import Experience from "./experience/Experience.js";
import {SizesType} from "./experience/lib/core/Sizes.js";
import DomEventBus from "./experience/lib/core/events/DomEventBus.js";
import Ui from "./experience/ui/Ui.js";

const canvas: HTMLCanvasElement = document.querySelector('canvas.webgl')!;
const initialSizes: SizesType = {
	width: window.innerWidth,
	height: window.innerHeight,
	devicePixelRatio: window.devicePixelRatio,
};

const eventBus = new DomEventBus();
eventBus.registerTarget('canvas', canvas);

const experience = new Experience({
	canvas: canvas,
	initialSizes,
	eventBus,
});

new Ui(experience);