import * as THREE from 'three';
import Engine from "../../../lib/core/Engine.js";
import vertexShader from './shaders/vertex.glsl';
import fragmentShader from './shaders/fragment.glsl';
import config from "../../../config/Conf.js";
import ShaderBaker from "../../../lib/utils/baker/ShaderBaker.js";
import bakingVertexShader from "./shaders/bakingVertex.glsl";
import Resources from "../../../lib/core/Resources.js";
import sources from "../../../config/resources.config.js";
import bakedFragmentShader from './shaders/bakedFragment.glsl';

type TweaksValue = {
	topColor: string,
	midColor: string,
	baseColor: string,
};

type MainWaterParams = {
	resources: Resources<typeof sources>,
	engine: Engine,
	group: THREE.Group,
	initialTweaks: TweaksValue,
}

export default class MainWater {
	private readonly resources : Resources<typeof sources>;
	private readonly engine : Engine;
	private readonly group  : THREE.Group;
	private readonly tweaksValue  : TweaksValue;

	private water!    : THREE.Mesh;
	private topWater! : THREE.Mesh;
	private material! : THREE.ShaderMaterial;

	constructor(
		{
			engine,
			group,
			resources,
			initialTweaks,
		}: MainWaterParams
	) {
		this.engine = engine;
		this.group  = group;
		this.resources = resources;
		this.tweaksValue = initialTweaks;

		this.init();
		this.configureTweaks();

		this.engine.on(
			'global:config:changed',
			(event) => {
				const conf = event?.detail?.config;
				if (!conf) return;

				this.configChanged(conf);
			}
		);
	}


	private configChanged(conf: typeof config) {
		if (conf.islands.waterfalls) {
			this.updateMidColor(conf.islands.water.midColor);
			this.updateTopColor(conf.islands.water.topColor);
			this.updateBaseColor(conf.islands.water.baseColor);
		}
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweaksValue,
			{
				folder: 'Islands.Water (Main)',
				topColor: {
					onChange: this.updateTopColor.bind(this),
				},
				midColor: {
					onChange: this.updateMidColor.bind(this),
				},
				baseColor: {
					onChange: this.updateBaseColor.bind(this),
				},
			},
		);
	}

	private updateTopColor(color: string) {
		if (!this.material.uniforms.uTopColor) return;

		this.material.uniforms.uTopColor.value = new THREE.Color(color);
	}

	private updateMidColor(color: string) {
		if (!this.material.uniforms.uMidColor) return;

		this.material.uniforms.uMidColor.value = new THREE.Color(color);
	}

	private updateBaseColor(color: string) {
		if (!this.material.uniforms.uBaseColor) return;

		this.material.uniforms.uBaseColor.value = new THREE.Color(color);
	}


	private init() {
		this.extractMesh();
		this.createMaterial();
		this.applyMaterialToMesh();

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;
			if (!declineLevel) return;

			if (declineLevel === 4) {
				console.warn('Water: Low fps detected. Baking shaders...');
				this.bakeShaders();
			}
		});
	}

	private bakeShaders() {
		const bakedShader = new ShaderBaker(
			bakingVertexShader,
			2048,
			this.engine,
			this.resources,
			this.water,
			[
				{ uTime: 30 },
				{ uTime: 1 }
			],
			bakedFragmentShader,
		);

		try {
			const material = bakedShader.bake();
			this.water.material = material;
			this.material = material;
			this.topWater.material = material;
			console.log('Water: Shaders successfully baked for performance optimization');
		} catch (error) {
			console.error('Water: Failed to bake shaders:', error);
		}
	}

	private extractMesh() {
		this.group.traverse((child) => {
			if (child.name !== 'main-water') return;

			this.water = child as THREE.Mesh;
			this.water.geometry.computeTangents();
		});
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			vertexShader,
			fragmentShader,
			transparent: false,
			fog: true,
			uniforms: {
				uTime      : new THREE.Uniform(0),
				uBaseColor : new THREE.Uniform(new THREE.Color(this.tweaksValue.baseColor)),
				uTopColor  : new THREE.Uniform(new THREE.Color(this.tweaksValue.topColor)),
				uMidColor  : new THREE.Uniform(new THREE.Color(this.tweaksValue.midColor)),
				envMapIntensity: new THREE.Uniform(1),
				...THREE.UniformsLib.fog,
			}
		});
	}

	private applyMaterialToMesh() {
		this.water.material = this.material;

		this.group.traverse((child) => {
			if (child instanceof THREE.Mesh && child.name === 'top-water') {
				child.material = this.material;
				child.receiveShadow = true;
				child.geometry.computeTangents();
				this.topWater = child;
			}
		})
	}

	update() {
		if (!this.material) return;

		this.material.transparent = this.engine.camera.isCloseEnough(22);

		if (this.material.uniforms.uTime) {
			this.material.uniforms.uTime.value = this.engine.time.elapsedSeconds;
		}

		if (this.material.uniforms.mixFactor) {
			this.material.uniforms.mixFactor.value = this.engine.time.elapsedSeconds;
		}
	}

	destroy() {
		this.water.geometry.dispose();
		this.material.dispose();
	}
}