export default class RingBuffer {
	private readonly buffer     : number[];
	private readonly size       : number;
	private readonly defaultMax : number = 0;

	private index  : number  = 0;
	private isFull : boolean = false;
	private _max   : number  = 0;

	constructor(size: number, defaultMax?: number) {
		if (size <= 0) {
			throw new Error(`RingBuffer size must be > 0 (provided: ${size})`);
		}

		this.defaultMax = defaultMax ?? 0;
		this._max       = this.defaultMax;
		this.size       = size;
		this.buffer     = new Array(size).fill(0);
	}

	push(value: number) {
		const previousValue = this.buffer[this.index];

		this.buffer[this.index] = value;

		if (previousValue === this._max) {
			this._max = Math.max(...this.buffer);

			if (this._max < this.defaultMax) {
				this._max = this.defaultMax;
			}
		}

		if (value > this._max){
			this._max = value;
		}

		this.index = (this.index + 1) % this.size;
		if (this.index === 0) this.isFull = true;
	}

	get values(): number[] {
		if (this.isFull) {
			return [
				...this.buffer.slice(this.index),
				...this.buffer.slice(0, this.index),
			];
		}

		return this.buffer.slice(0, this.index);
	}

	get max(): number {
		return this._max;
	}

	get length(): number {
		return this.isFull
			? this.size
			: this.index;
	}
}