import Renderer from "../core/Renderer.js";

export default class GpuPerfCollector {
	private readonly glContext?  : WebGL2RenderingContext;
	private readonly glExtension : any;
	private readonly gpuAlpha    : number = 0.1;

	private gpuQuery          : any           = null;
	private lastGpuTime       : number | null = null;
	private pendingQuery      : any           = null;
	private smoothedGpuTime   : number        = 0;

	constructor(renderer: Renderer) {
		const glContext = renderer.instance.getContext();

		if (glContext instanceof WebGL2RenderingContext) {
			this.glContext = glContext;
			this.glExtension = this.glContext.getExtension('EXT_disjoint_timer_query_webgl2');
		}
	}

	private isGpuTimingSupported() {
		return this.glExtension && this.glContext instanceof WebGL2RenderingContext;
	}

	begin() {
		if (this.isGpuTimingSupported() && !this.pendingQuery) {
			this.gpuQuery = this.glContext!.createQuery();
			this.glContext!.beginQuery(this.glExtension.TIME_ELAPSED_EXT, this.gpuQuery);
		}
	}

	end(): number | undefined {
		let gpuTimePerFrame;

		if (!this.isGpuTimingSupported()) {
			return;
		}

		if (this.gpuQuery) {
			this.glContext!.endQuery(this.glExtension.TIME_ELAPSED_EXT);
			this.pendingQuery = this.gpuQuery;
			this.gpuQuery = null;
		}

		if (this.glExtension && this.pendingQuery) {
			const available = this.glContext!.getQueryParameter(this.pendingQuery, WebGL2RenderingContext.QUERY_RESULT_AVAILABLE);
			const disjoint = this.glContext!.getParameter(this.glExtension.GPU_DISJOINT_EXT);

			if (available && !disjoint) {
				const gpuTimeNs = this.glContext!.getQueryParameter(this.pendingQuery, WebGL2RenderingContext.QUERY_RESULT);
				this.lastGpuTime = gpuTimePerFrame = gpuTimeNs / 1e6; // convert to ms
				this.pendingQuery = null;
				this.smoothedGpuTime = this.gpuAlpha * gpuTimePerFrame + (1 - this.gpuAlpha) * this.smoothedGpuTime;
				return this.smoothedGpuTime;
			}
		}

		return this.smoothedGpuTime ?? this.lastGpuTime ?? 0;
	}
}