import * as THREE from 'three';
import gsap from "gsap";
import {OrbitControls} from "three/examples/jsm/controls/OrbitControls.js";
import Sizes from './Sizes.js';
import OrbitControlsBridge from "../compatibility/controls/OrbitControlsBridge.js";
import EventBusCapabilities from "./events/EventBusCapabilities.js";
import {isOffscreenCanvas} from "../compatibility/offscreenCanvas.js";
import TweaksCapabilities from "../dev/TweaksCapabilities.js";

type CameraParams = {
	sizes  : Sizes,
	tweaks : TweaksCapabilities,
	scene  : THREE.Scene,
	canvas : HTMLCanvasElement | OffscreenCanvas,
	eventBus : EventBusCapabilities,
	autoUpdateFrustum?: boolean,
}

export default class Camera {
	private readonly sizes  : Sizes;
	private readonly scene  : THREE.Scene;
	private readonly canvas : HTMLCanvasElement | OffscreenCanvas;
	private readonly tweaks : TweaksCapabilities;
	private readonly autoUpdateFrustum : boolean;
	private readonly matrix : THREE.Matrix4;
	private readonly eventBus : EventBusCapabilities;
	private readonly vec3: THREE.Vector3 = new THREE.Vector3();

	#frustum   : THREE.Frustum;
	#instance! : THREE.PerspectiveCamera;
	#controls! : OrbitControls;
	#shaking   : boolean;

	public readonly group  : THREE.Group;

	constructor(
		{
			sizes,
			scene,
			canvas,
			tweaks,
			autoUpdateFrustum,
			eventBus,
		}: CameraParams
	) {
		this.sizes  = sizes;
		this.tweaks = tweaks;
		this.scene  = scene;
		this.canvas = canvas;
		this.eventBus = eventBus;
		this.group    = new THREE.Group();
		this.#frustum = new THREE.Frustum();
		this.matrix   = new THREE.Matrix4();
		this.#shaking = false;
		this.autoUpdateFrustum = autoUpdateFrustum ?? true;

		this.initInstance();
		this.initControls();
		this.configureTweaks();
	}

	configureTweaks() {
		const REFERENCE_FOV = 75;
		const REFERENCE_DISTANCE = 4.2;
		const EFFECT_INTENSITY = 0.3; // Reduce this to make movement more subtle (0.0 = no movement, 1.0 = full effect)
		const target = new THREE.Vector3(0, 0, 0);
		const fixedDirection = new THREE.Vector3(1, 0.27, 1).normalize();

		this.tweaks.configure(
			{
				orbitLocked: Boolean(this.#controls?.enabled),
				fov: 90
			},
			{
				folder: 'Scene',
				orbitLocked: {
					onChange: (value: boolean) => {
						this.#controls.enabled = value;
					}
				},
				fov: {
					params: {
						min: 5,
						max: 160,
						step: 1,
					},
					onChange: (value: number) => {
						const newFOV = value;

						// Calculate the full dolly zoom distance
						const fullDollyDistance = REFERENCE_DISTANCE *
							(Math.tan(THREE.MathUtils.degToRad(REFERENCE_FOV / 2)) /
								Math.tan(THREE.MathUtils.degToRad(newFOV / 2)));

						// Interpolate between reference distance and full dolly distance
						const newDistance = REFERENCE_DISTANCE + (fullDollyDistance - REFERENCE_DISTANCE) * EFFECT_INTENSITY;

						this.instance.position.copy(target).addScaledVector(fixedDirection, newDistance);

						this.instance.fov = newFOV;
						this.instance.updateProjectionMatrix();
						this.instance.lookAt(target);
					}
				}
			}
		)
	}

	shake(
		{
			duration = 0.5,
			intensity = 0.2
		}: {
			duration?: number,
			intensity?: number
		} = {}
	) {
		if (this.#shaking) {
			return;
		}

		this.#shaking = true;

		const cam = this.#instance;
		const original = cam.position.clone();
		const proxy = { t: 0 };

		gsap.to(proxy, {
			t: 1,
			duration,
			ease: "power2.out",
			onUpdate: () => {
				// small random offsets that decay with time
				const progress = 1 - proxy.t;
				cam.position.set(
					original.x + (Math.random() - 0.5) * 2 * intensity * progress,
					original.y + (Math.random() - 0.5) * 2 * intensity * progress,
					original.z + (Math.random() - 0.5) * 2 * intensity * progress,
				);
			},
			onComplete: () => {
				cam.position.copy(original);
				this.#shaking = false;
			}
		});
	}

	public disableControls() {
		if (!this.#controls) {
			return;
		}

		this.#controls.enabled = false;
	}

	public enableControls() {
		if (!this.#controls) {
			return;
		}

		this.#controls.enabled = true;
	}

	public isCloseEnough(threshold: number, point?: THREE.Vector3) {
		if (!point) {
			point = new THREE.Vector3();
		}

		return this.vec3
			.copy(point)
			.sub(this.instance.position)
			.length() < threshold;
	}

	get instance() {
		return this.#instance;
	}

	get frustum() {
		return this.#frustum;
	}

	get controls() {
		return this.#controls;
	}

	initInstance(): void {
		const sizes = this.sizes;

		this.#instance = new THREE.PerspectiveCamera(
			60,
			sizes.width / sizes.height,
			0.1,
			1000,
		);

		this.#instance.position.set(5.5, 1.5, 5.5);
		this.#instance.lookAt(
			new THREE.Vector3(0, 10, -8),
		);

		this.group.add(this.#instance);
		this.scene.add(this.group);
	}

	initControls(): void {
		this.#controls = new OrbitControls(
			this.#instance,
			isOffscreenCanvas(this.canvas)
				? new OrbitControlsBridge(this.eventBus, this.sizes) as unknown as HTMLElement
				: this.canvas,
		);

		this.#controls.enableDamping = true;
	}

	resize(): void {
		this.#instance.aspect = this.sizes.width / this.sizes.height;
		this.#instance.updateProjectionMatrix();
	}

	update(): void {
		this.#controls?.update();

		if (this.autoUpdateFrustum) {
			this.updateFrustum();
		}
	}

	updateFrustum() {
		this.matrix.multiplyMatrices(
			this.instance.projectionMatrix,
			this.instance.matrixWorldInverse,
		);

		this.#frustum.setFromProjectionMatrix(this.matrix);
	}

	destroy() {
		this.#controls.dispose();
	}
}