import * as THREE from 'three';
import EventEmitter from "../utils/EventEmitter.js";
import {GLTF, GLTFLoader} from "three/examples/jsm/loaders/GLTFLoader.js";
import {RGBELoader} from "three/examples/jsm/loaders/RGBELoader.js";
import {DRACOLoader} from "three/examples/jsm/loaders/DRACOLoader.js";

// region Types

export enum RESOURCE_TYPE {
	HDR     = 'hdr',
	GLTF    = 'gltf',
	DRACO   = 'draco',
	TEXTURE = 'texture',
	SOUND   = 'sound',
}

export enum LOADING_MODE {
	/**
	 * The default one. The app will not be considered ready until all
	 * auto resources have not been loaded.
	 */
	AUTO     = 'auto',

	/**
	 * Will start automatically, but will not block the emission of the ready event.
	 */
	DEFERRED = 'deferred',

	/**
	 * The resource will not be loaded until someone call the Resources.load method
	 * specifying its key.
	 */
	MANUAL   = 'manual',
}

export type ResourceType = {
	readonly type  : RESOURCE_TYPE,
	readonly urls  : readonly string[],
	readonly loadingMode? : LOADING_MODE,
	readonly on?   : {
		load?: (file: any) => void,
	},
}

export type ResourceConfig = {
	[key: string]: ResourceType
}

const LOADING_ERROR_TIPS = [
	'- Check your browser network console for more details.',
	'- You may also double check the source type.',
];

type ResourceTypeMap = {
	[RESOURCE_TYPE.HDR    ]: THREE.DataTexture;
	[RESOURCE_TYPE.GLTF   ]: GLTF;
	[RESOURCE_TYPE.DRACO  ]: GLTF;
	[RESOURCE_TYPE.TEXTURE]: THREE.Texture;
	[RESOURCE_TYPE.SOUND  ]: AudioBuffer;
};

type LoadedItems<T extends ResourceConfig> = {
	[K in keyof T]: ResourceTypeMap[T[K]['type']];
};

// endregion
// region Privates

function capitalizeType(type: RESOURCE_TYPE): Capitalize<RESOURCE_TYPE> {
	// @ts-ignore
	return `${
		type.charAt(0).toUpperCase()
	}${
		type.slice(1)
	}`;
}

// endregion
// region Utils

type HelperParams = {
	compressed?: boolean,
	loadingMode? : LOADING_MODE,
	on?   : ResourceType['on'],
};

export function texture(
	url: string,
	{
		loadingMode,
		on
	}: HelperParams = {}
): ResourceType & { type: RESOURCE_TYPE.TEXTURE } {
	return {
		type : RESOURCE_TYPE.TEXTURE,
		urls : [url],
		loadingMode : loadingMode ?? LOADING_MODE.AUTO,
		on,
	};
}

export function texturePack(
	textureName: string,
	{
		aormh,
		colors,
		normals,
	}: {
		aormh?: HelperParams,
		colors?: HelperParams,
		normals?: HelperParams,
	},
): {
	aormh: ResourceType & { type: RESOURCE_TYPE.TEXTURE },
	colors: ResourceType & { type: RESOURCE_TYPE.TEXTURE },
	normals: ResourceType & { type: RESOURCE_TYPE.TEXTURE },
} {
	return {
		aormh: texture(`/textures/${textureName}/${textureName}_ao_r_m_h_1k.png`, aormh),
		colors: texture(`/textures/${textureName}/${textureName}_basecolor_1k.png`, colors),
		normals: texture(`/textures/${textureName}/${textureName}_normal_gl_1k.png`, normals),
	}
}

export function gltf(
	url: string,
	{
		on,
		loadingMode,
		compressed
	}: HelperParams = {}
): ResourceType & { type: RESOURCE_TYPE.GLTF | RESOURCE_TYPE.DRACO } {
	return {
		type : compressed ? RESOURCE_TYPE.DRACO : RESOURCE_TYPE.GLTF,
		urls : [url],
		loadingMode : loadingMode ?? LOADING_MODE.AUTO,
		on,
	}
}

export function sound(
	url: string,
	{
		loadingMode,
	}: HelperParams = {}
): ResourceType & { type: RESOURCE_TYPE.SOUND } {
	return {
		type : RESOURCE_TYPE.SOUND,
		urls : [url],
		loadingMode : loadingMode ?? LOADING_MODE.AUTO,
	}
}

// endregion

export default class Resources<T extends ResourceConfig = any> extends EventEmitter {
	readonly #sources : T;
	readonly #items   : LoadedItems<T>;
	readonly #toLoad  : number;

	#loaded   : number;
	#loaders! : {
		dracoLoader   : GLTFLoader,
		gltfLoader    : GLTFLoader,
		rgbeLoader    : RGBELoader,
		textureLoader : THREE.ImageBitmapLoader,
		soundLoader   : THREE.AudioLoader
	};

	constructor(resources: T) {
		super({ persistent: true });

		this.#sources = resources;

		this.#items  = {} as LoadedItems<T>;
		this.#toLoad = this.getAutoSources().length;
		this.#loaded = 0;

		this.initLoaders();
		this.startLoading();
	}

	private getAutoSources() {
		return Object
			.values(this.#sources)
			.filter(
				(source) => !source.loadingMode
					|| source.loadingMode === LOADING_MODE.AUTO
			);
	}

	private get gltfLoader() {
		return this.#loaders.gltfLoader;
	}

	private get textureLoader() {
		return this.#loaders.textureLoader;
	}

	private get rgbeLoader() {
		return this.#loaders.rgbeLoader;
	}

	private get dracoLoader() {
		return this.#loaders.dracoLoader;
	}

	private get soundLoader() {
		return this.#loaders.soundLoader;
	}

	public get items() {
		return this.#items;
	}

	initLoaders() {
		const dracoLoader = new DRACOLoader();
		dracoLoader.setDecoderPath('/draco/');

		const dracoEnabledGltfLoader = new GLTFLoader();
		dracoEnabledGltfLoader.setDRACOLoader(dracoLoader);

		this.#loaders = {
			gltfLoader    : new GLTFLoader(),
			dracoLoader   : dracoEnabledGltfLoader,
			textureLoader : new THREE.ImageBitmapLoader(),
			rgbeLoader    : new RGBELoader(),
			soundLoader   : new THREE.AudioLoader(),
		};
	}

	private getSourcesToLoadImmediately() {
		return Object.keys(this.#sources)
			.filter((key) => this.#sources[key].loadingMode !== LOADING_MODE.MANUAL);
	}

	startLoading() {
		this.getSourcesToLoadImmediately()
			.forEach((key) => this.loadSource(key as keyof T));
	}

	private loadSource(key: keyof T) {
		const source = this.#sources[key];

		const methodName: `load${Capitalize<typeof source.type>}` = `load${
			capitalizeType(source.type)
		}`;

		if (typeof this[methodName] !== "function") {
			throw new Error(
				`Unsupported asset type ${source.type} for resource ${String(key)} !`,
			);
		}

		this[methodName](key, source);
	}

	load(key : keyof T) {
		const source = this.#sources[key];

		if (source.loadingMode !== LOADING_MODE.MANUAL) {
			throw new Error(
				`Can't load manually the resource ${
					String(key)
				}: its loading mode is ${
					source.loadingMode
				} instead of ${
					LOADING_MODE.MANUAL
				}`,
			);
		}

		this.loadSource(key);
	}

	private loadDraco<Name extends keyof T>(
		key: Name,
		source: T[Name]
	) {
		this.checkType(source, RESOURCE_TYPE.DRACO);

		this.dracoLoader.load(
			source.urls[0],
			(file) => {
				this.sourceLoaded(
					key,
					file
				);
			},
			() => {},
			this.loadingError.bind(this, key, source),
		)
	}

	private loadGltf<Name extends keyof T>(
		key: Name,
		source: T[Name]
	) {
		this.checkType(source, RESOURCE_TYPE.GLTF);

		this.gltfLoader.load(
			source.urls[0],
			(file) => {
				this.sourceLoaded(
					key,
					file
		);
			},
			() => {},
			this.loadingError.bind(this, key, source),
		)
	}

	private loadHdr<Name extends keyof T>(
		key: Name,
		source: T[Name]
	)  {
		this.checkType(source, RESOURCE_TYPE.HDR);

		this.rgbeLoader.load(
			source.urls[0],
			(texture) => {
				this.sourceLoaded(
					key,
					texture
				);
			},
			() => {},
			this.loadingError.bind(this, key, source),
		)
	}

	private loadTexture<Name extends keyof T>(
		key: Name,
		source: T[Name]
	)  {
		this.checkType(source, RESOURCE_TYPE.TEXTURE);

		this.textureLoader.load(
			source.urls[0],
			(imageBitmap) => {
				const canvas = self.OffscreenCanvas
					? new OffscreenCanvas(imageBitmap.width, imageBitmap.height)
					: document.createElement('canvas');

				canvas.width = imageBitmap.width;
				canvas.height = imageBitmap.height;

				const ctx = canvas.getContext('2d');
				if (!ctx) {
					throw new Error('Unable to access canvas context !');
				}

				ctx.drawImage(imageBitmap, 0, 0);

				const texture = new THREE.CanvasTexture(canvas);
				texture.flipY = true;
				texture.needsUpdate = true;

				this.sourceLoaded(
					key,
					texture,
				);
			},
			() => {},
			this.loadingError.bind(this, key, source),
		);
	}

	private loadSound<Name extends keyof T>(
		key: Name,
		source: T[Name]
	)  {
		this.checkType(source, RESOURCE_TYPE.SOUND);

		this.soundLoader.load(
			source.urls[0],
			(buffer) => {
				this.sourceLoaded(
					key,
					buffer
				);
			},
			() => {},
			this.loadingError.bind(this, key, source),
		)
	}

	private checkType(source: ResourceType, type: RESOURCE_TYPE) {
		if (source.type !== type) {
			throw new Error(
				`Invalid type : expected '${type}', got '${source.type}'`,
			);
		}
	}

	private loadingError(name: keyof T, source: ResourceType, error?: any) {
		// We still count it as loaded, because otherwise we would never get the ready event.
		if (source.loadingMode === LOADING_MODE.AUTO) {
			this.#loaded++;
		}

		if (error instanceof Error) {
			console.error(
				`An error occurred while trying to load resource ${
					String(name)
				} (type: ${
					source.type
				}) at ${
					source.urls.join(', ')
				} : ${
					error.stack
				}`,
			);
			return;
		}

		console.error(
			`An unknown error occurred while trying to load ${
				String(name)
			} (${
				source.type
			}) at ${
				source.urls.join(', ')
			}.\n${
				LOADING_ERROR_TIPS.join('\n')
			}`,
			error,
		);
	}

	private sourceLoaded<
		Type extends RESOURCE_TYPE,
		Name extends keyof T = keyof T,
	>(
		name: Name,
		file: ResourceTypeMap[Type],
	) {
		this.#items[name] = file;

		this.emit(`loaded:${String(name)}`);

		const source = this.#sources[name];
		if (source.loadingMode === LOADING_MODE.AUTO) {
			this.#loaded++;
		}

		if (typeof source.on?.load === 'function') {
			source.on.load(file);
		}

		this.emit(
			'loaded',
			new CustomEvent('loaded', { detail: {
					name: String(name),
					file,
					total: this.#toLoad,
					loaded: this.#loaded,
				} }),
		);

		if (this.#loaded === this.#toLoad) {
			this.emit('ready');
		}
	}

	destroy() {
		Object.values(this.#items).forEach((item) => {
			if (item.dispose !== 'function') return;

			item.dispose();
		});
	}
}