import * as THREE from "three";

export default class Random {
	public static sign(): 1 | -1 {
		return Math.random() > 0.5 ? 1 : -1;
	}

	public static between(min: number, max: number): number {
		return Math.random() * (max - min) + min;
	}

	public static betweenInt(min: number, max: number): number {
		return Math.floor(Math.random() * (max - min + 1)) + min;
	}

	public static color(): THREE.Color {
		return new THREE.Color(Math.random(), Math.random(), Math.random());
	}

	public static colorBetween(
		color1: THREE.Color,
		color2: THREE.Color,
		variation: number = 1,
	): THREE.Color {
		return color1.clone().lerp(color2, Math.random() * variation);
	}

	/**
	 * Picks a random point within the boundaries of a Three.js Box3
	 */
	public static pointInBox(box3: THREE.Box3): THREE.Vector3 {
		// Check if the box is valid (not empty)
		if (box3.isEmpty()) {
			throw new Error('Cannot pick random point from empty Box3');
		}

		// Get min and max bounds
		const min = box3.min;
		const max = box3.max;

		// Generate random coordinates within the bounds
		const x = Math.random() * (max.x - min.x) + min.x;
		const y = Math.random() * (max.y - min.y) + min.y;
		const z = Math.random() * (max.z - min.z) + min.z;

		return new THREE.Vector3(x, y, z);
	}

	public static inArray<T>(array: T[]): T {
		return array[Random.betweenInt(0, array.length - 1)];
	}
}