import * as THREE from 'three';
import gsap from 'gsap';
import EventEmitter from "../../../../lib/utils/EventEmitter.js";
import Engine from "../../../../lib/core/Engine.js";
import LineGeometry from "./LineGeometry.js";
import vertexShader from "./shaders/vertex.glsl";
import fragmentShader from "./shaders/fragment.glsl";

type TweakValues = {
	color         : string,
	length        : number,
	duration      : number,
	amplitude     : number,
	sampledPoints : number,
	thickness     : number,
	progress      : number,
	directorPointsCount? : number,
}

type InitialTweaks = {
	[key in keyof TweakValues]?: TweakValues[key]
}

type WindLineParams = {
	engine         : Engine,
	group          : THREE.Group,
	initialTweaks? : InitialTweaks,
	points?        : THREE.Vector3[],
}

export enum EVENTS {
	START    = 'start',
	RESET    = 'reset',
	COMPLETE = 'complete',
}

export default class WindLine extends EventEmitter {
	private static id = 0;

	private readonly id          : number;
	private readonly engine      : Engine;
	private readonly group       : THREE.Group;
	private readonly points      : THREE.Vector3[];
	private readonly tweakValues : TweakValues;

	private geometry! : THREE.BufferGeometry;
	private material! : THREE.ShaderMaterial;
	private mesh!     : THREE.Mesh;
	private twean!    : ReturnType<typeof gsap.fromTo>;

	constructor(
		{
			engine,
			group,
			points,
			initialTweaks,
		}: WindLineParams
	) {
		super();

		this.id          = WindLine.id++;
		this.engine      = engine;
		this.group       = group;
		this.tweakValues = {
			color         : 'white',
			length        : 2,
			duration      : 6,
			amplitude     : 0.25,
			thickness     : 0.02,
			sampledPoints : 51,
			progress      : 0,
			directorPointsCount : 4,
			...initialTweaks,
		};

		this.points      = points ?? [];

		this.init();
		this.configureTweaks();
	}

	private configureTweaks() {
		this.engine.tweaks.configure(
			this.tweakValues,
			{
				folder: `GrassField.Wind.WindLines.${this.id}`,
				duration: {
					params: {
						min: 1,
						max: 10,
						step: 0.5,
					}
				},
				length: {
					params: {
						min: 0.1,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						if (!this.geometry) return;

						console.warn(`WindLine length changed to ${value}, but length change is not implemented yet.`);
					}
				},
				amplitude: {
					params: {
						min: 0.01,
						max: 0.5,
						step: 0.01,
					},
					onChange: (value: number) => {
						if (!this.geometry) return;

						console.warn(`WindLine amplitude changed to ${value}, but amplitude change is not implemented yet.`);
					},
				},
				sampledPoints: {
					params: {
						min: 5,
						max: 200,
						step: 1,
					},
					onChange: (value: number) => {
						if (!this.geometry) return;

						console.warn(`WindLine sampledPoints changed to ${value}, but sampledPoints change is not implemented yet.`);
					}
				},
				color: {
					onChange: (value) => {
						if (!this.material) return;

						this.material.uniforms.uColor.value = new THREE.Color(value);
					}
				},
				thickness: {
					params: {
						min: 0.001,
						max: 0.06,
						step: 0.001,
					},
					onChange: (value: number) => {
						if (!this.material) return;

						this.material.uniforms.uThickness.value = value;
					}
				},
				progress: {
					params: {
						min: 0,
						max: 1,
						step: 0.01,
					},
					onChange: (value: number) => {
						if (!this.material) return;

						this.material.uniforms.uProgress.value = value;
					}
				}
			}
		)
	}

	private init() {
		this.createGeometry();
		this.createMaterial();
		this.createMesh();

		this.group.add(this.mesh);
	}

	private createGeometry() {
		this.geometry = new LineGeometry({
			points: this.points,
			...this.tweakValues,
		});
	}

	private createMaterial() {
		this.material = new THREE.ShaderMaterial({
			vertexShader,
			fragmentShader,
			transparent: true,
			depthWrite: false,
			uniforms: {
				uColor          : new THREE.Uniform(new THREE.Color(this.tweakValues.color)),
				uProgress       : new THREE.Uniform(0),
				uThickness      : new THREE.Uniform(this.tweakValues.thickness),
				uCameraPosition : new THREE.Uniform(this.cameraPosition.clone()),
			}
		});
	}

	private get cameraPosition(): THREE.Vector3 {
		return this.engine.camera.instance.position;
	}

	private createMesh() {
		this.mesh = new THREE.Mesh(
			this.geometry,
			this.material,
		);
	}

	getMesh(): THREE.Mesh {
		return this.mesh;
	}

	start() {
		this.emit(EVENTS.START);

		this.twean = gsap.fromTo(
			this.material.uniforms.uProgress,
			{
				value: 0,
			},
			{
				value: 1,
				duration: this.tweakValues.duration,
				ease: 'expo.out',
				onComplete: () => {
					this.emit(EVENTS.COMPLETE);
				}
			}
		);
	}

	reset() {
		if (!this.material)  return;

		this.emit(EVENTS.RESET);

		this.material.uniforms.uProgress.value = 0;
	}

	update() {
		if (!this.material) {
			return;
		}

		this.material.uniforms.uCameraPosition.value.copy(this.cameraPosition);
	}

	destroy() {
		this.twean?.kill();
		this.group.remove(this.mesh);
		this.material?.dispose();
		this.geometry?.dispose();
	}
}