import EventBusCapabilities from "../../core/events/EventBusCapabilities.js";
import MainThreadEventBus from "../../core/events/MainThreadEventBus.js";
import Sizes from "../../core/Sizes.js";

export default class OrbitControlsBridge {
	public static configureMainThreadEventBus(
		canvas: HTMLCanvasElement,
		eventBus: MainThreadEventBus,
	) {
		canvas.style.touchAction = "none";

		eventBus.addEventHook('canvas', 'contextmenu', 'core:orbitControls', (e) => {
			e.preventDefault();
		});

		function touchEventsHook(event: Event) {
			event.preventDefault();
			const touchEvent = event as TouchEvent;

			const touches: {
				pageX: number,
				pageY: number,
				clientX: number,
				clientY: number,
			}[] = [];

			for (let i = 0; i < touchEvent.touches.length; ++i) {
				const touch = touchEvent.touches[i];
				touches.push({
					pageX: touch.pageX,
					pageY: touch.pageY,
					clientX: touch.clientX,
					clientY: touch.clientY,
				});
			}

			return {
				touches,
			};
		}

		// eventBus.addEventHook('canvas', 'touchstart', 'core:orbitControls', touchEventsHook);
		// eventBus.addEventHook('canvas', 'touchmove', 'core:orbitControls', touchEventsHook);
		// eventBus.addEventHook('canvas', 'touchend', 'core:orbitControls', touchEventsHook);
	}

	private readonly eventBus: EventBusCapabilities;

	private readonly sizes: Sizes;

	constructor(
		eventBus: EventBusCapabilities,
		sizes: Sizes
	) {
		this.eventBus = eventBus;
		this.sizes = sizes;
	}

	// Canvas-like properties that OrbitControls might check
	get clientWidth(): number { return this.sizes.resolution[0]; }
	get clientHeight(): number { return this.sizes.resolution[1] }

	get width(): number { return this.sizes.resolution[0] }
	get height(): number { return this.sizes.resolution[1]; }

	get ownerDocument(): Partial<Document> {
		return {
			addEventListener: (event: string, listener: EventListener, options: AddEventListenerOptions) => {
				this.eventBus.subscribe('document', event, listener, {
					listenerId: 'core:orbitControls',
					options,
				});
			},
			removeEventListener: (event: string, listener: EventListener) => {
				this.eventBus.unsubscribe('document', event, listener);
			}
		};
	}

	getRootNode() {
		return {
			addEventListener: (event: string, listener: EventListener, options: AddEventListenerOptions) => {
				this.eventBus.subscribe('document', event, listener, {
					listenerId: 'core:orbitControls',
					options,
				});
			},
			removeEventListener: (event: string, listener: EventListener) => {
				this.eventBus.unsubscribe('document', event, listener);
			}
		};
	}

	private isMouseRelatedEvent(event: string): boolean {
		return event.startsWith('mouse')
				|| event.startsWith('pointer');
	}

	addEventListener(event: string, listener: EventListener, options: AddEventListenerOptions): void {
		// For mouse events, specify which properties we need
		if (this.isMouseRelatedEvent(event)) {
			this.eventBus.subscribe('canvas', event, listener, {
				listenerId: 'core:orbitControls',
				propertiesToCopy: [
					'ctrlKey',
					'metaKey',
					'shiftKey',
					'button',
					'pointerType',
					'clientX',
					'clientY',
					'pointerId',
					'pageX',
					'pageY',
				],
				options,
			});
		} else if(event === 'wheel') {
			this.eventBus.subscribe('canvas', event, listener, {
				listenerId: 'core:orbitControls',
				propertiesToCopy: [
					'deltaX',
					'deltaY',
				],
				options,
			});
		} else {
			this.eventBus.subscribe('canvas', event, listener, {
				listenerId: 'core:orbitControls',
				options,
			});
		}
	}

	removeEventListener(event: string, listener: EventListener): void {
		this.eventBus.unsubscribe('canvas', event, listener);
	}

	setPointerCapture() {}

	releasePointerCapture() {}

	// OrbitControls might call these
	focus(): void { /* no-op in worker */ }
	blur(): void { /* no-op in worker */ }

	// Style property that some controls check
	get style(): Partial<CSSStyleDeclaration> {
		return {
			touchAction: 'none' // OrbitControls sets this
		};
	}
}