import * as THREE from 'three';
import Camera from "./Camera.js";
import {Effect, EffectComposer, RenderPass, SMAAEffect} from "postprocessing";
import Renderer from "./Renderer.js";
import Sizes from "./Sizes.js";

type PostProcessingParams = {
	scene    : THREE.Scene,
	camera   : Camera,
	renderer : Renderer,
	sizes    : Sizes,
}

export default class PostProcessing {
	private readonly sizes: Sizes;
	readonly #renderer: Renderer;

	protected readonly effectComposer: EffectComposer;
	protected readonly advisedEffectPasses: Effect[];

	constructor(
		{
			renderer,
			scene,
			camera,
			sizes,
		}: PostProcessingParams,
	) {
		this.sizes = sizes;
		this.#renderer = renderer;
		this.advisedEffectPasses = [];

		this.effectComposer = new EffectComposer(
			renderer.instance,
			{
				frameBufferType: THREE.HalfFloatType,
				multisampling: 0,
			}
		);

		renderer.disableAutoRenderOnResize();

		this.effectComposer.addPass(new RenderPass(scene, camera.instance));
		if(sizes.pixelRatio === 1 /*&& !renderer.instance.capabilities.isWebGL2*/) {
			this.advisedEffectPasses.push(new SMAAEffect());
		}
	}

	get renderer() {
		return this.effectComposer.getRenderer();
	}

	resize() {
		this.effectComposer.setSize(this.sizes.width, this.sizes.height);

		if (this.#renderer.isExecutedInWorker()) {
			this.update();
		}
	}

	update() {
		this.effectComposer.render();
	}

	destroy() {
		this.effectComposer.dispose();
	}
}