import * as THREE from 'three';
import EventEmitter, {Callback} from "../utils/EventEmitter.js";
import Camera from "./Camera.js";
import EventBusCapabilities from "./events/EventBusCapabilities.js";
import Sizes from "./Sizes.js";

export enum RAYCASTER_EVENTS {
	POINTER_IN = 'mesh:pointerIn',
	POINTER_OUT = 'mesh:pointerOut',
	POINTER_MOVE = 'mesh:pointerMove',
	POINTER_DOWN = 'mesh:pointerDown',
	POINTER_UP = 'mesh:pointerUp',
}

type MeshEventMap = Map<
	THREE.Object3D,
	Map<RAYCASTER_EVENTS, Set<(event: CustomEvent) => void>>
>;

type RaycasterParams = {
	sizes    : Sizes,
	camera   : Camera,
	eventBus : EventBusCapabilities,
}

export default class Raycaster extends EventEmitter {
	private readonly camera      : Camera;
	private readonly sizes       : Sizes;
	private readonly eventBus    : EventBusCapabilities;
	private readonly pointer     : THREE.Vector2;
	private readonly lastPointer : THREE.Vector2;
	private readonly pointerMoveListener  : (event: PointerEvent) => void;
	private readonly pointerLeaveListener : (event: PointerEvent | TouchEvent) => void;
	private readonly pointerUpListener : (event: PointerEvent) => void;
	private readonly pointerDownListener : (event: PointerEvent) => void;

	private lastEvent  : PointerEvent | undefined;
	private raycaster! : THREE.Raycaster;
	private hoveredMeshes = new Set<THREE.Object3D>();
	private pointerUp : PointerEvent | null = null;
	private pointerDown : PointerEvent | null = null;
	private meshListeners: MeshEventMap = new Map();

	private readonly INTERACTIVE_LAYER = Number.MAX_SAFE_INTEGER;

	constructor(
		{
			sizes,
			camera,
			eventBus,
		}: RaycasterParams
	) {
		super();

		this.sizes    = sizes;
		this.camera   = camera;
		this.eventBus = eventBus;
		this.pointer  = new THREE.Vector2();
		this.lastPointer = new THREE.Vector2();

		this.pointerMoveListener = this.onPointerMove.bind(this);
		this.pointerLeaveListener = this.onPointerLeave.bind(this);
		this.pointerDownListener = this.onPointerDown.bind(this);
		this.pointerUpListener = this.onPointerUp.bind(this);
		this.init();
	}

	init() {
		this.eventBus.subscribe(
			'canvas',
			'pointermove',
			this.pointerMoveListener,
		);

		this.eventBus.subscribe(
			'canvas',
			'pointerout',
			this.pointerLeaveListener,
		);
		this.eventBus.subscribe(
			'canvas',
			'mouseleave',
			this.pointerLeaveListener,
		);

		this.eventBus.subscribe(
			'canvas',
			'pointerup',
			this.pointerUpListener,
		);

		this.eventBus.subscribe(
			'canvas',
			'pointerdown',
			this.pointerDownListener,
		);

		this.raycaster = new THREE.Raycaster();
		this.raycaster.layers.set(this.INTERACTIVE_LAYER);
	}

	extractPointerCoordinates(event: PointerEvent) {
		// FIXME : initially : window.innerHeight/Width. Maybe sizes should track the window
		// sizes AND the canvas size, because they can be different.
		this.pointer.x = (event.clientX / this.sizes.width) * 2 - 1;
		this.pointer.y = - (event.clientY / this.sizes.height) * 2 + 1;
	}

	private onPointerMove(event: PointerEvent) {
		this.lastPointer.copy(this.pointer);

		this.extractPointerCoordinates(event);
		this.lastEvent = event;
	}

	private onPointerDown(event: PointerEvent) {
		this.lastPointer.copy(this.pointer);
		this.extractPointerCoordinates(event);
		this.pointerDown = event;
	}

	private onPointerUp(event: PointerEvent) {
		this.lastPointer.copy(this.pointer);
		this.extractPointerCoordinates(event);
		this.pointerUp = event;
	}

	private onPointerLeave() {
		this.lastPointer.copy(this.pointer);

		this.hoveredMeshes.forEach(mesh => {
			this.emitEvent(
				RAYCASTER_EVENTS.POINTER_OUT,
				mesh,
				this.lastEvent
			);
		});

		this.hoveredMeshes.clear();
	}

	private subscribe(mesh: THREE.Object3D) {
		if (!this.meshListeners.has(mesh)) {
			this.meshListeners.set(mesh, new Map());
			mesh.layers.enable(this.INTERACTIVE_LAYER);
		}
	}

	private unsubscribe(mesh: THREE.Object3D) {
		mesh.layers.disable(this.INTERACTIVE_LAYER);

		this.meshListeners.delete(mesh);
		this.hoveredMeshes.delete(mesh);
	}

	remove(mesh: THREE.Object3D) {
		this.meshListeners.delete(mesh);
		this.meshListeners.delete(mesh);
	}

	on(eventName: string, callback: Callback): void;
	on(eventName: RAYCASTER_EVENTS, mesh: THREE.Object3D, callback: Callback): void;
	on(eventName: string | RAYCASTER_EVENTS, meshOrCallback: Callback | THREE.Object3D, callback?: Callback): void {
		if (meshOrCallback instanceof THREE.Object3D) {
			const mesh = meshOrCallback;
			const event = eventName as RAYCASTER_EVENTS;

			this.subscribe(mesh);
			const typeMap = this.meshListeners.get(mesh);
			if (!typeMap) {
				return;
			}

			if (!typeMap.has(event)) {
				typeMap.set(event, new Set());
			}
			typeMap.get(event)!.add(callback as Callback);

			return;
		}

		super.on(eventName, meshOrCallback);
	}

	off(eventName: string, callback?: Callback): void;
	off(eventName: string, mesh: THREE.Object3D, callback?: Callback): void;
	off(...eventNames: string[]): void;
	off(
		eventName: string | RAYCASTER_EVENTS,
		meshOrCallback?: Callback | THREE.Object3D | string,
		callback?: Callback | string,
		...rest: string[]
	): void {
		if (meshOrCallback instanceof THREE.Object3D) {
			const mesh = meshOrCallback;
			const event = eventName as RAYCASTER_EVENTS;

			const typeMap = this.meshListeners.get(mesh)!;
			if (!typeMap.has(event)) return;

			const listeners = typeMap.get(event)!;
			if (callback) {
				listeners.delete(callback as Callback);
			} else {
				listeners.clear();
			}

			if (listeners.size === 0) {
				typeMap.delete(event);
			}

			if (typeMap.size === 0) {
				this.unsubscribe(mesh);
			}

			return;
		}

		if (typeof meshOrCallback === 'function') {
			super.off(eventName as string, meshOrCallback as Callback);
			return;
		}

		super.off(
			...[
				eventName,
				meshOrCallback,
				callback,
				...rest
			].filter(Boolean) as string[],
		);
	}

	private emitEvent(
		type: RAYCASTER_EVENTS,
		object: THREE.Object3D,
		event: PointerEvent | undefined,
		intersect?:  THREE.Intersection<THREE.Object3D<THREE.Object3DEventMap>>
	) {
		const listeners = this.meshListeners.get(object)?.get(type);

		if (!listeners) return;

		const customEvent = new CustomEvent(type, {
			detail: {
				object,
				intersect,
				pointer: this.pointer.clone(),
				originalEvent: event,
			}
		});

		for (const listener of listeners) {
			listener(customEvent);
		}
	}

	private pointerMoved() {
		return this.pointer.x !== this.lastPointer.x
			  || this.pointer.y !== this.lastPointer.y;
	}

	update() {
		this.raycaster.setFromCamera(this.pointer, this.camera.instance);

		const targets = Array.from(this.meshListeners.keys());
		const intersects = this.raycaster.intersectObjects(targets, true);

		const intersected = new Set<THREE.Object3D>();

		for (const intersect of intersects) {
			const obj = intersect.object;
			intersected.add(obj);

			if (!this.hoveredMeshes.has(obj)) {
				this.hoveredMeshes.add(obj);
				this.emitEvent(
					RAYCASTER_EVENTS.POINTER_IN,
					obj,
					this.lastEvent,
					intersect,
				);
			}

			if (this.pointerMoved()) {
				this.emitEvent(
					RAYCASTER_EVENTS.POINTER_MOVE,
					obj,
					this.lastEvent,
					intersect,
				);
			}

			if (this.pointerDown) {
				this.emitEvent(
					RAYCASTER_EVENTS.POINTER_DOWN,
					obj,
					this.pointerDown,
					intersect
				);

				this.pointerDown = null;
			}

			if (this.pointerUp) {
				this.emitEvent(
					RAYCASTER_EVENTS.POINTER_UP,
					obj,
					this.pointerUp,
					intersect
				);

				this.pointerUp = null;
			}
		}

		for (const mesh of Array.from(this.hoveredMeshes)) {
			if (!intersected.has(mesh)) {
				this.emitEvent(RAYCASTER_EVENTS.POINTER_OUT, mesh, this.lastEvent);
				this.hoveredMeshes.delete(mesh);
			}
		}

		this.pointerDown = null;
		this.pointerUp = null;

		this.lastPointer.copy(this.pointer);
	}

	destroy() {
		this.eventBus.unsubscribe('canvas', 'pointermove', this.pointerMoveListener);
		this.eventBus.unsubscribe('canvas', 'pointerout', this.pointerLeaveListener);
		this.eventBus.unsubscribe('canvas', 'pointerup', this.pointerUpListener);
		this.eventBus.unsubscribe('canvas', 'pointerdown', this.pointerDownListener);
	}
}