import * as THREE from 'three';
import Engine from "../../../lib/core/Engine.js";
import Fire from "./fire/Fire.js";
import Sparks from "./sparks/Sparks.js";
import {ExperienceAudioItems} from "../../../AudioItems.js";
import sources from "../../../config/resources.config.js";
import Resources from "../../../lib/core/Resources.js";

type CampfireParams = {
	engine: Engine,
	islands: THREE.Group,
	resources: Resources<typeof sources>,
}

export default class Campfire {
	private readonly resources: Resources<typeof sources>;
	private readonly engine: Engine<ExperienceAudioItems>;
	private readonly islands: THREE.Group;
	private readonly woodMeshes: THREE.Mesh[];

	private fire!: Fire;
	private sparks!: Sparks;
	private woodMaterial!: THREE.MeshStandardMaterial;

	constructor(
		{
			engine,
			islands,
			resources,
		}: CampfireParams,
	) {
		this.engine = engine;
		this.islands = islands;
		this.woodMeshes = [];
		this.resources = resources;

		this.init();
	}

	private init() {
		this.woodMaterial = new THREE.MeshStandardMaterial({
			color: new THREE.Color('#241e13'),
			roughness: 1.0,
			metalness: 0,
		});

		const boundingBox = new THREE.Box3();

		this.islands.traverse((obj) => {
			if (!(obj instanceof THREE.Mesh)) {
				return;
			}

			if (obj.name.startsWith('campfire-wood')) {
				this.woodMeshes.push(obj);
				obj.material = this.woodMaterial;
				obj.castShadow = true;

				boundingBox.expandByObject(obj);
			}
		});

		const logsCenter = boundingBox.getCenter(new THREE.Vector3());
		this.fire = new Fire({
			engine: this.engine,
			islands: this.islands,
			position: logsCenter.clone(),
		});

		this.sparks = new Sparks({
			engine: this.engine,
			islands: this.islands,
			position: logsCenter.clone(),
		});

		this.resources.once('loaded:soundCampfire', () => {
			const audio = this.engine.audio.createPositionalAudio(
				'campfire',
				this.resources.items.soundCampfire,
				{
					volume: 7.5,
					loop: true,
				}
			);

			audio.position.copy(logsCenter);
			audio.setRefDistance(1);
			audio.setRolloffFactor(4);
			audio.setMaxDistance(2);
			audio.play();

			this.islands.add(audio);
		});
	}

	update() {
		this.fire?.update();
		this.sparks?.update();
	}

	destroy() {
		this.fire?.destroy();
		this.sparks?.destroy();
	}
}