import gsap from "gsap";
import Experience from "../Experience.js";
import EventEmitter from "../lib/utils/EventEmitter.js";
import { EVENTS as CAMERA_SPOTS_EVENTS } from "../CameraSpots.js";
import DayTimeSwitch from "./DayTimeSwitch.js";

export enum LOADING_EVENTS {
	START_BUTTON_CLICKED = 'ui.loading:startButtonClicked',
}

export default class LoadingScreen extends EventEmitter {
	private readonly experience: Experience;
	private readonly dayTimeSwitch: DayTimeSwitch;

	constructor(experience: Experience, dayTimeSwitch: DayTimeSwitch) {
		super();

		this.dayTimeSwitch = dayTimeSwitch;
		this.experience = experience;
		this.init();
	}

	private init() {
		const loadingContainer = document.querySelector('.loading')!;
		const progressFeedback = document.querySelector('.progress-percentage')!;
		const loadingText = document.querySelector('.loading-text')!;
		const startButton = document.querySelector('.loading button')!;

		this.experience.cameraSpots.on(
			CAMERA_SPOTS_EVENTS.INTRO_PLAYED,
			() => loadingContainer.classList.add('hidden'),
		);

		startButton.addEventListener('click', () => {
			this.emit(LOADING_EVENTS.START_BUTTON_CLICKED);

			this.experience.engine.audio.items.button?.play();

			if (this.dayTimeSwitch.isDay()) {
				this.experience.engine.audio.items.ambientAudio?.play();
				this.experience.engine.audio.items.ambientMusic?.play();
			} else {
				this.experience.engine.audio.items.ambientNightAudio?.play();
				this.experience.engine.audio.items.ambientNightMusic?.play();
			}

			this.experience.engine.audio.items.wind?.play();
			this.experience.engine.audio.items['waterfall-0']?.play();
			this.experience.engine.audio.items['waterfall-1']?.play();
			this.experience.engine.audio.items['waterfall-2']?.play();
			this.experience.engine.audio.items['waterfall-3']?.play();

			loadingContainer.classList.add('loaded');
			loadingText.classList.add('hidden');
			startButton.classList.add('hidden');
			progressFeedback.classList.add('hidden');

			setTimeout(() => {
				this.experience.cameraSpots.playIntro();
			}, 50);
		});

		// @ts-ignore
		this.experience.resources.on('loaded', ({ detail: { total, loaded } } = {}) => {
			const progressionInPercent = Math.round(loaded / total * 100);

			const percentageText = progressFeedback.querySelector('.circle span')!;
			percentageText.innerHTML = `${progressionInPercent}%`;

			if (total === loaded) {
				startButton.classList.remove('hidden');
				loadingContainer.classList.add('ready');
				percentageText.classList.add('hidden');
			}
		});
	}
}