import * as THREE from 'three';
import Engine from "./lib/core/Engine.js";
import Environment from "./environment/Environment.js";
import sources from './config/resources.config.js';
import Resources from "./lib/core/Resources.js";
import World from "./World.js";
import PostProcessing from "./PostProcessing.js";
import Light from "./Light.js";
import {SizesType} from "./lib/core/Sizes.js";
import EventBusCapabilities from "./lib/core/events/EventBusCapabilities.js";
import EventEmitter from "./lib/utils/EventEmitter.js";
import {ExperienceAudioItems} from "./AudioItems.js";
import CameraSpots, { EVENTS as CAMERA_SPOTS_EVENTS } from "./CameraSpots.js";
import config from "./config/Conf.js";
import ParallaxEffect from "./lib/utils/ParallaxEffect.js";

type TweakValues = {
	bgColor: string,
	enableZoom: boolean,
	enablePan: boolean,
};

type ExperienceParams = {
	canvas: HTMLCanvasElement | OffscreenCanvas,
	initialSizes: SizesType,
	eventBus : EventBusCapabilities,
}

export default class Experience extends EventEmitter {
	public readonly group: THREE.Group;
	public readonly engine: Engine<ExperienceAudioItems>;
	public readonly resources: Resources<typeof sources>;
	public readonly environment: Environment;
	public readonly world: World;
	public readonly light: Light;
	public readonly eventBus: EventBusCapabilities;
	public readonly cameraSpots: CameraSpots;
	public parallax!: ParallaxEffect;

	private readonly tweakValues : TweakValues;

	private introPlayed: boolean;
	private reachedLowEndPerfProfile: boolean;

	constructor(
		{
			canvas,
			initialSizes,
			eventBus,
		}: ExperienceParams
	) {
		super();

		this.introPlayed = false;
		this.reachedLowEndPerfProfile = false;

		this.tweakValues = {
			bgColor: '#142424',
			enablePan: false,
			enableZoom: false,
		};

		this.eventBus = eventBus;

		this.engine = new Engine({
			canvas,
			initialSizes,
			eventBus,
		});
		this.engine.scene.background = new THREE.Color(this.tweakValues.bgColor);

		this.engine.camera.controls.enableZoom   = this.tweakValues.enableZoom;
		this.engine.camera.controls.enablePan    = this.tweakValues.enablePan;
		this.engine.camera.controls.enableRotate = false;

		this.resources = new Resources(sources);

		this.light = new Light({
			engine: this.engine,
			resources: this.resources,
			initialTweaks: {
				sunColor: config.scene.light.sunColor,
				sunIntensity: config.scene.light.sunIntensity,
			},
		});

		this.engine.usePostProcessing(
			new PostProcessing({
				engine: this.engine,
				light: this.light,
			}),
		);

		this.group = new THREE.Group();
		this.engine.scene.add(this.group);
		this.engine.renderer.instance.shadowMap.enabled = true;

		this.environment = new Environment({
			group     : this.group,
			engine    : this.engine,
			resources : this.resources,
		});

		this.world = new World({
			light     : this.light,
			group     : this.group,
			engine    : this.engine,
			resources : this.resources,
			environment : this.environment,
		});

		this.configureTweaks();

		this.engine.on('update', () => {
			this.update();
		});

		this.resources.on('ready', () => {
			this.emit('ready');

			this.light.updateShadows();

			// Let the whole app breath for a bit before deciding to cut corners.
			// we're trying to get stable FPS at the beginning
			setTimeout(() => this.engine.monitor.start(), 1000);
		});

		this.cameraSpots = new CameraSpots({
			engine: this.engine,
		});

		this.cameraSpots.on(CAMERA_SPOTS_EVENTS.INTRO_PLAYED, () => {
			this.engine.camera.controls.enableRotate = true;
			this.introPlayed = true;
			this.deleteCloudsForLowEndDevices();
		});

		this.engine.monitor.on('decline', (event) => {
			const declineLevel = event?.detail?.declineLevel;
			if (!declineLevel) return;

			switch (declineLevel) {
				case 5:
					this.reachedLowEndPerfProfile = true;
					this.deleteCloudsForLowEndDevices();

					break;
			}
		});

		this.initParallaxEffect();
	}

	private initParallaxEffect() {
		this.parallax = new ParallaxEffect(this.engine);

		this.cameraSpots.on(CAMERA_SPOTS_EVENTS.TRAVEL_STARTED, () => {
			this.parallax.disable();
		});
		this.cameraSpots.on(CAMERA_SPOTS_EVENTS.TRAVEL_ENDED, () => {
			this.parallax.enable();
		});
	}

	private deleteCloudsForLowEndDevices() {
		if (this.reachedLowEndPerfProfile && this.introPlayed) {
			this.world.islands.clouds.destroy();
		}
	}

	private get tweaks() {
		return this.engine.tweaks;
	}

	configureTweaks(): void {
		this.tweaks.configure(
			this.tweakValues,
			{
				folder: 'Scene',
				bgColor: {
					onChange: (value: string) => {
						this.engine.scene.background = new THREE.Color(value);
					}
				},
				enableZoom: {
					onChange: (value: boolean) => {
						this.engine.camera.controls.enableZoom = value;
					}
				},
				enablePan: {
					onChange: (value: boolean) => {
						this.engine.camera.controls.enablePan = value;
					}
				},
			}
		);
	}


	update() {
		this.world?.update();
		this.environment.update();
		this.light.update();
		this.parallax.update();
	}

	private resetCanva() {
		const gl = this.engine.canvas.getContext('webgl2');
		if (gl) {
			gl.clearColor(0, 0, 0, 1);
			gl.clear(gl.COLOR_BUFFER_BIT);
		}
	}

	destroy() {
		this.engine.scene.remove(this.group);
		this.light.destroy();
		this.world?.destroy();
		this.environment.destroy();
		this.engine.destroy();

		this.resetCanva();

		this.resources.destroy();
	}
}