export type Callback<T = any> = (event?: CustomEvent<T>) => void;

function isSpecificCallback<T = any>(args: (Callback<T> | string)[]): args is [string, Callback] {
	return args.length === 2 && typeof args[1] === 'function';
}

type EventEmitterProps = {
	/**
	 * If true, will persist event emission and keep the last event for each event name.
	 * This way, while subscribing with on(), if the event name has been fired once, the listener
	 * will be subscribed and will be immediately called.
	 */
	persistent?: boolean
}

export default class EventEmitter {
	private readonly persistent : boolean;
	private readonly state      : Record<string, CustomEvent | undefined>;

	private listeners: Record<string, Callback[]>;

	/**
	 * @param persistent - If true, will persist event emission and keep the last event for each event name.
	 * 										 This way, while subscribing with on(), if the event name has been fired once, the listener
	 * 										 will be subscribed and will be immediately called.
	 */
	constructor({ persistent = false }: EventEmitterProps = {}) {
		this.persistent = persistent;
		this.listeners  = {};
		this.state      = {};
	}

	on<T = any>(eventName: string, callback: Callback<T>) {
		if (!(eventName in this.listeners)) {
			this.listeners[eventName] = [];
		}

		if (!this.listeners[eventName].includes(callback)) {
			this.listeners[eventName].push(callback);
		}

		if (this.persistent && eventName in this.state) {
			callback(this.state[eventName]);
		}
	}

	onceAll<T = any>(eventNames: string[], callback: (events: (CustomEvent<T> | undefined)[]) => void) {
		const received: Record<string, CustomEvent | undefined> = {};
		const unsubscribers: (() => void)[] = [];

		const tryEmit = () => {
			if (eventNames.every(name => name in received)) {
				unsubscribers.forEach(unsub => unsub());
				const orderedEvents = eventNames.map(name => received[name]);
				callback(orderedEvents);
			}
		};

		eventNames.forEach(eventName => {
			const handler = (event?: CustomEvent) => {
				received[eventName] = event;
				tryEmit();
			};

			this.on(eventName, handler);
			unsubscribers.push(() => this.off(eventName, handler));
		});
	}

	once<T = any>(eventName: string, callback: Callback<T>) {
		const wrapper = (event?: CustomEvent<T>) => {
			this.off(eventName, wrapper);
			callback(event);
		};

		this.on(eventName, wrapper);
	}

	off<T = any>(eventName: string, callback: Callback<T>): void;
	off<T = any>(...eventNames: string[]): void;
	off<T = any>(...args: [string, Callback<T>] | string[]): void {
		if (isSpecificCallback(args)) {
			return this.unregisterSpecificCallback(...args);
		}

		args.forEach((eventName) => {
			this.unregisterAllCallbacks(eventName as string);
		});
	}

	reset(): void {
		this.listeners = {};
	}

	private unregisterAllCallbacks(eventName: string): void {
		if (!(eventName in this.listeners)) {
			return;
		}

		this.listeners[eventName] = [];
	}

	private unregisterSpecificCallback<T = any>(eventName: string, callback: Callback<T>): void {
		if (!(eventName in this.listeners)) {
			return;
		}

		this.listeners[eventName] = this.listeners[eventName].filter(cb => cb !== callback);
	}

	emit<T = any>(eventName: string, event?: CustomEvent<T>): void {
		if (this.persistent) {
			this.state[eventName] = event;
		}

		if (!(eventName in this.listeners)) {
			return;
		}

		this.listeners[eventName].forEach(callback => callback(event));
	}
}