import * as THREE from "three";
import Engine from "./lib/core/Engine.js";
import sources from "./config/resources.config.js";
import Resources from "./lib/core/Resources.js";
import Environment from "./environment/Environment.js";
import MainIslands from "./scenes/islands/MainIslands.js";
import Light from "./Light.js";
import {ExperienceAudioItems} from "./AudioItems.js";
import config from "./config/Conf.js";

type WorldParams = {
	light     : Light,
	group     : THREE.Group,
	engine    : Engine<ExperienceAudioItems>,
	resources : Resources<typeof sources>,
	environment : Environment,
}

export default class World {
	private readonly group       : THREE.Group;
	private readonly light       : Light;
	private readonly engine      : Engine<ExperienceAudioItems>;
	private readonly environment : Environment;
	private readonly resources   : Resources<typeof sources>;

	public islands! : MainIslands;

	constructor(
		{
			light,
			group,
			engine,
			resources,
			environment,
		}: WorldParams,
	) {
		this.light     = light;
		this.group     = group;
		this.engine    = engine;
		this.environment = environment;
		this.resources   = resources;

		this.init();
	}

	init() {
		this.resources.onceAll(
			[
				'loaded:testIsland',
			],
			() => {
				this.islands = new MainIslands({
					group       : this.group,
					light       : this.light,
					engine      : this.engine,
					resources   : this.resources,
					environment : this.environment,
					initialTweaks : config.islands.main,
				});

				this.environment.updateMaterials();
			}
		);

		this.resources.onceAll([
			'loaded:soundMain',
			'loaded:soundNightMain',
			'loaded:soundWind',
			'loaded:soundAmbience',
			'loaded:soundNightAmbience'
		], () => {
			this.configureAmbientMusic();
			this.configureAmbientAudio();

			this.configureAmbientNightMusic();
			this.configureAmbientNightAudio();

			this.configureWindSound();
		});
	}

	private configureAmbientAudio() {
		this.engine.audio.createAmbientAudio(
			'ambientAudio',
			this.resources.items.soundAmbience,
			{
				volume: 0.4,
				loop: true,
			}
		);
	}

	private configureAmbientMusic() {
		this.engine.audio.createAmbientAudio(
			'ambientMusic',
			this.resources.items.soundMain,
			{
				volume: 0.5,
				loop: true,
			},
		);
	}

	private configureAmbientNightAudio() {
		this.engine.audio.createAmbientAudio(
			'ambientNightAudio',
			this.resources.items.soundNightAmbience,
			{
				volume: 0.4,
				loop: true,
			}
		);
	}

	private configureAmbientNightMusic() {
		this.engine.audio.createAmbientAudio(
			'ambientNightMusic',
			this.resources.items.soundNightMain,
			{
				volume: 0.7,
				loop: true,
			},
		);
	}

	private configureWindSound() {
		this.engine.audio.createAmbientAudio(
			'wind',
			this.resources.items.soundWind,
			{
				volume: 0.1,
				loop: true,
			},
		);
	}

	update() {
		this.islands?.update();
	}

	destroy() {
		this.islands?.destroy();
	}
}