import EventEmitter from "../utils/EventEmitter.js";
import EventBusCapabilities from "./events/EventBusCapabilities.js";
import MainThreadEventBus from "./events/MainThreadEventBus.js";
import {addSizesPropertiesToEvent, ResizeEventListenerData} from "../compatibility/window.js";

export type SizesType = {
	width: number,
	height: number,
	devicePixelRatio: number,
}

type SizesParams = SizesType & {
	eventBus: EventBusCapabilities,
}

export default class Sizes extends EventEmitter {
	public static configureMainThreadEventBus(eventBus: MainThreadEventBus) {
		eventBus.addEventHook(
			'window',
			'resize',
			'core:Sizes',
			() => {
				return {
					width: window.innerWidth,
					height: window.innerHeight,
					devicePixelRatio: window.devicePixelRatio,
				};
			},
		);
	}

	private readonly eventBus: EventBusCapabilities;

	#width!: number;
	#height!: number;
	#pixelRatio!: number;
	#resizeListener: (data: Event) => void;

	constructor(
		{
			eventBus,
			...initialSizes
		}: SizesParams
	) {
		super();
		this.eventBus = eventBus;

		this.update(initialSizes);

		this.#resizeListener = (event: Event) => {
			this.update(addSizesPropertiesToEvent(event));
			this.emit('resize');
		};

		this.eventBus.subscribe(
			'window',
			'resize',
			this.#resizeListener,
			{
				listenerId: 'core:Sizes'
			}
		);
	}

	private update(
		{
			width,
			height,
			devicePixelRatio
		}: ResizeEventListenerData,
	) {
		this.#width = width;
		this.#height = height;
		this.#pixelRatio = Math.min(devicePixelRatio, 2);
	}

	get width() {
		return this.#width;
	}

	get height() {
		return this.#height;
	}

	get pixelRatio() {
		return this.#pixelRatio;
	}

	/**
	 * [width, height]
	 */
	get resolution() {
		return [
			this.width * this.pixelRatio,
			this.height * this.pixelRatio,
		];
	}

	get resolutionAsNumber() {
		const [width, height] = this.resolution;
		return width * height;
	}

	get aspectRatio() {
		const [width, height] = this.resolution;
		return width / height;
	}

	destroy() {
		this.eventBus.unsubscribe('window', 'resize', this.#resizeListener);
	}
}
